local config = {
  ui_story_5051_50510101_X1_dialog_content = "Advertencia, advertencia, situación de emergencia.",
  ui_story_5051_50510101_X2_dialog_content = "Advertencia, advertencia, situación de emergencia.",
  ui_story_5051_50510101_1_dialog_content = "No otra vez.",
  ui_story_5051_50510101_2_dialog_content = "¡¿Por qué ahora, de todos los tiempos?!",
  ui_story_5051_50510101_3_dialog_content = "El med... Ah, por aquí.",
  ui_story_5051_50510101_4_dialog_content = "Tu condición está empeorando últimamente.",
  ui_story_5051_50510101_5_dialog_content = "Por lo que sé, tal vez ya sea...",
  ui_story_5051_50510101_6_dialog_content = "Mi señor, ¿pasa algo?",
  ui_story_5051_50510101_7_dialog_content = "¡No es nada! Como dije antes, ¡no quiero que me molesten!",
  ui_story_5051_50510101_8_dialog_content = "Pero ha llegado tu carruaje para el banquete del Día de la Familia.",
  ui_story_5051_50510101_9_dialog_content = "¡Me veré abajo en un momento!",
  ui_story_5051_50510101_10_dialog_content = "<color=#FFB400>Dia familiar</color>? ¡Qué farsa!",
  ui_story_5051_50510101_11_dialog_content = "¿Arruinó tu vida y todavía tiene el descaro de hacer una fiesta y llamarla banquete del Día de la Familia?",
  ui_story_5051_50510101_12_dialog_content = "No te preocupes, no pelearé con él.",
  ui_story_5051_50510101_13_dialog_content = "Esta puede ser la última oportunidad. debo traer <color=#FFB400>él</color> atrás.",
  ui_story_5051_50510101_14_dialog_content = "Nunca rompiste tus promesas hacia mí, y yo tampoco lo haré.",
  ui_story_5051_50510101_15_dialog_content = "Esta vez, te prometo que...",
  ui_story_5051_50510101_16_dialog_content = "Dios.",
  ui_story_5051_50510101_17_dialog_content = "¡Vamos a llegar tarde a este ritmo!",
  ui_story_5051_50510101_18_dialog_content = "Incluso me puse mi ropa dos horas antes, ¡¿por qué no ha llegado nadie todavía?!",
  ui_story_5051_50510101_19_dialog_content = "¿Dónde diablos está el enviado de la reina Belén?",
  ui_story_5051_50510101_20_dialog_content = "\"Estimado PlayerName, un enviado de Northland pronto visitará Lumopolis para asistir al banquete\".",
  ui_story_5051_50510101_21_dialog_content = "\"Como lo más probable es que usted también esté presente, le pido humildemente que la acompañe durante su estadía\".",
  ui_story_5051_50510101_22_dialog_content = "Te estará esperando fuera de Umbraton a la hora señalada.",
  ui_story_5051_50510101_X22_dialog_content = "Estamos fuera de tiempo. ¡Vamos a llegar tarde!",
  ui_story_5051_50510101_X23_dialog_content = "¿Dónde se menciona el mensajero en la correspondencia?",
  ui_story_5051_50510101_23_dialog_content = "La Reina Belén es otra cosa. Incluso sabía que yo iba a asistir a la <color=#FFB400>Schwartz Dia familiar</color> banquete de hoy.",
  ui_story_5051_50510101_24_dialog_content = "<size=30>Mmm...</size>",
  ui_story_5051_50510101_25_dialog_content = "Incluso me sorprendió recibir una invitación. Nunca he estado en un banquete tan formal como este.",
  ui_story_5051_50510101_26_dialog_content = "¿Es mi atuendo lo suficientemente elegante para la ocasión? No pensarán que soy raro, ¿verdad?",
  ui_story_5051_50510101_27_dialog_content = "Lady Sheol dice que esta es la ropa formal más moderna en Lumopolis en este momento. Me costó una fortuna solo alquilar.",
  ui_story_5051_50510101_28_dialog_content = "Y no sé nada de ropa, así que la pagué sin pensar...",
  ui_story_5051_50510101_29_dialog_content = "Suspiro, si tan solo Carleen estuvieran alrededor, ella sabría qué hacer.",
  ui_story_5051_50510101_30_dialog_content = "Últimamente no he podido contactar con ella. Me pregunto dónde podría haber ido.",
  ui_story_5051_50510101_31_dialog_content = "Eh... perdóname...",
  ui_story_5051_50510101_32_dialog_content = "¡Oh, sí, también está el presente! Solo espero que sea lo suficientemente bueno...",
  ui_story_5051_50510101_33_dialog_content = "E-Disculpe...!",
  ui_story_5051_50510101_34_dialog_content = "¡¡¡Bwaaaa!!! ¡BB-Baba Yaga! ¡¿Qué estás haciendo aquí?!",
  ui_story_5051_50510101_35_dialog_content = "¡Oye!",
  ui_story_5051_50510101_36_dialog_content = "¡Lo siento!",
  ui_story_5051_50510101_37_dialog_content = "Espera, no eres Baba Yaga. Eres su otra personalidad, <color=#FFB400>Mia</color>! ¿Bien?",
  ui_story_5051_50510101_38_dialog_content = "Si, soy yo.",
  ui_story_5051_50510101_39_dialog_content = "Aunque para ser precisos, yo soy la personalidad dominante, no ella...",
  ui_story_5051_50510101_40_dialog_content = "Simplemente no soy tan fuerte como Baba Yaga, y tampoco puedo controlar mis propios poderes, así que tengo que confiar en ella para hacer las cosas.",
  ui_story_5051_50510101_41_dialog_content = "Lo siento si te asusté...",
  ui_story_5051_50510101_42_dialog_content = "¡No te preocupes por eso! Entonces, ¿necesitas algo?",
  ui_story_5051_50510101_X42_dialog_content = "Uh, así que escuché que vas a la Schwartz banquete del día de la familia, PlayerName.",
  ui_story_5051_50510101_X43_dialog_content = "¿Te importa... llevarme contigo?",
  ui_story_5051_50510101_X44_dialog_content = "¿Usted trae? Claro, pero ¿qué es lo que te hace querer ir a un banquete de repente?",
  ui_story_5051_50510101_X45_dialog_content = "Uh, me he estado sintiendo mucho mejor últimamente por tratamientos recientes.",
  ui_story_5051_50510101_43_dialog_content = "Bueno, recientemente me sometí a un tratamiento y ahora mi condición ha mejorado mucho.",
  ui_story_5051_50510101_44_dialog_content = "Tanto es así, que finalmente recordé algo importante...",
  ui_story_5051_50510101_45_dialog_content = "¿Qué sería eso?",
  ui_story_5051_50510101_46_dialog_content = "que soy... <color=#FFB400>la hermana mayor de carleen</color>.",
  ui_story_5051_50510101_47_dialog_content = "¡¿H-la hermana de Carleen?!",
  ui_story_5051_50510101_48_dialog_content = "¡¿Pero pensé que Lumopolis solo tenía una princesa?!",
  ui_story_5051_50510101_49_dialog_content = "Sin mencionar que ustedes dos realmente no... No, espera, si miro de cerca, puedo ver un parecido.",
  ui_story_5051_50510101_50_dialog_content = "Es difícil de creer, ¿no?",
  ui_story_5051_50510101_51_dialog_content = "Nadie está dispuesto a creer una palabra de lo que digo. incluso tío Istvan sólo se sentó allí en silencio cuando le dije.",
  ui_story_5051_50510101_52_dialog_content = "Pero es la verdad. Incluso ahora, fragmentos de recuerdos siguen pasando por mi mente.",
  ui_story_5051_50510101_53_dialog_content = "Algunos son tan claros como el día. Otros han sido casi olvidados...",
  ui_story_5051_50510101_54_dialog_content = "Mi madre, mi hermana... mi padre. Mi familia.",
  ui_story_5051_50510101_55_dialog_content = "Creo que mencionaste algo antes...",
  ui_story_5051_50510101_56_dialog_content = "Una vez dijiste que tu padre era un señor de la ciudad y que tu madre y tu hermana vivían en el palacio.",
  ui_story_5051_50510101_57_dialog_content = "Además de eso, tú y Baba Yaga siempre habéis prestado mucha atención a Carleen.",
  ui_story_5051_50510101_58_dialog_content = "Pero como sueles olvidar todo lo que dices, no tenía forma de saber si estabas diciendo la verdad o no...",
  ui_story_5051_50510101_59_dialog_content = "Aún así, me alegro de que tu tratamiento esté funcionando y de que te encuentres mucho mejor. Mia.",
  ui_story_5051_50510101_60_dialog_content = "Escuché que Lumopolis estaba organizando un banquete para Schwartz Dia familiar.",
  ui_story_5051_50510101_61_dialog_content = "Por lo que puedo juntar, es una ocasión muy especial e importante.",
  ui_story_5051_50510101_62_dialog_content = "me imagino a mi hermana Carleen lo más probable es que esté allí.",
  ui_story_5051_50510101_X62_dialog_content = "Me gustaría ir a la fiesta y ver por mí mismo si estas emociones persistentes son reales.",
  ui_story_5051_50510101_X63_dialog_content = "O tal vez solo un vistazo de ella desde lejos sería suficiente...",
  ui_story_5051_50510101_63_dialog_content = "quiero asistir Quiero verla y probar si estos buenos recuerdos son realmente reales o no.",
  ui_story_5051_50510101_64_dialog_content = "Incluso si no puedo probar ninguna de estas cosas, siempre que pueda ver que ella está bien, incluso desde lejos, eso será lo suficientemente bueno para mí...",
  ui_story_5051_50510101_65_dialog_content = "PlayerName, eres uno de los amigos más cercanos de Carleen, así como una figura respetada en Lumopolis...",
  ui_story_5051_50510101_X65_dialog_content = "Por eso vine a verte...",
  ui_story_5051_50510101_X66_dialog_content = "Veo. ¡Vaya, estamos cortos de tiempo!",
  ui_story_5051_50510101_X67_dialog_content = "¿Tienes un vestido adecuado? Y un regalo también...",
  ui_story_5051_50510101_66_dialog_content = "¿Crees que podrías ayudarme?",
  ui_story_5051_50510101_67_dialog_content = "Es cierto que voy a ir al banquete hoy, pero no estoy seguro si puedo traer amigos conmigo.",
  ui_story_5051_50510101_68_dialog_content = "Hmm... ¿Tiene que ser hoy?",
  ui_story_5051_50510101_69_dialog_content = "(En lugar de encontrar al enviado de Northland aquí, terminé encontrando Mia en necesidad de ayuda.)",
  ui_story_5051_50510101_70_dialog_content = "(Pero, ¿realmente estará bien si la traigo como invitada tan repentinamente?)",
  ui_story_5051_50510101_71_dialog_content = "(El banquete del Día de la Familia parece un evento realmente importante. ¿No traería al azar a alguien que dice ser un Schwartz ser amable...)",
  ui_story_5051_50510101_72_dialog_content = "(¡No solo eso, todo el banquete se arruinará si Baba Yaga hace una aparición inesperada!)",
  ui_story_5051_50510101_73_dialog_content = "Te estoy causando problemas, ¿no?",
  ui_story_5051_50510101_74_dialog_content = "Lo lamento. Olvida que dije algo.",
  ui_story_5051_50510101_75_dialog_content = "No tengo derecho a presionarte con mis propias demandas egoístas.",
  ui_story_5051_50510101_76_dialog_content = "F-Vamos a pretender que esta conversación nunca sucedió.",
  ui_story_5051_50510101_77_dialog_content = "¡Ay, lo que sea! Vamos, Mia! ¡Vendrás conmigo al banquete del Día de la Familia!",
  ui_story_5051_50510101_78_dialog_content = "¿E-Eh? ¿Pero no sería demasiado problema para ti?",
  ui_story_5051_50510101_79_dialog_content = "Esta es la primera vez que realmente te abres a mí.",
  ui_story_5051_50510101_80_dialog_content = "Siempre que hay un problema, Baba Yaga suele ser quien lo maneja.",
  ui_story_5051_50510101_81_dialog_content = "¿Cómo podría rechazarte cuando claramente te estás esforzando tanto?",
  ui_story_5051_50510101_82_dialog_content = "¡Así que relájate! soy buen amigo de Carleen, así como mucha gente de Lumopolis.",
  ui_story_5051_50510101_83_dialog_content = "Si no podemos lograr nada hoy, ¡al menos podemos divertirnos mucho en el banquete!",
  ui_story_5051_50510101_84_dialog_content = "Además, ¡estoy seguro de que habrá muchas oportunidades en el futuro también!",
  ui_story_5051_50510101_85_dialog_content = "PlayerName... ¡Gracias!",
  ui_story_5051_50510101_86_dialog_content = "(Todavía tengo muchas preguntas sobre todo esto).",
  ui_story_5051_50510101_87_dialog_content = "(Pero Mia parece realmente decidido a hablar con Carleen. Como mínimo, debería presentarlos el uno al otro.)",
  ui_story_5051_50510101_88_dialog_content = "(Aún así, no puedo dejar de notar que ella solo quiere ver Carleen. ¿Por qué no preguntó por el Señor de la Ciudad...?)",
  ui_story_5051_50510101_89_dialog_content = "<size=45>¡Lo siento, llego tarde!</size>",
  ui_story_5051_50510101_90_dialog_content = "¡Oye!",
  ui_story_5051_50510101_91_dialog_content = "¡¿Quién eres?!",
  ui_story_5051_50510101_92_dialog_content = "¡Dios mío! ¡Umbraton está lleno de todo tipo de cosas extrañas e interesantes!",
  ui_story_5051_50510101_93_dialog_content = "Aunque para ser justos, me ha sorprendido casi todo desde que dejé Northland.",
  ui_story_5051_50510101_94_dialog_content = "Quedé tan encantado con las vistas a lo largo del camino, y antes de darme cuenta... ¡me perdí! ¡Jejeje!",
  ui_story_5051_50510101_95_dialog_content = "Pero esta bien. ¡Mi linda bolita de cristal siempre encuentra el camino!",
  ui_story_5051_50510101_96_dialog_content = "Claro, a veces podría llevarme por un precipicio...",
  ui_story_5051_50510101_97_dialog_content = "¡Pero viajar tiene que ver con la emoción y la emoción! Al menos eso es lo que señora Jeriah ¡dice!",
  ui_story_5051_50510101_98_dialog_content = "Ahora, ¿de qué estaba hablando hace un momento? ¡Oh cierto, Umbratón!",
  ui_story_5051_50510101_99_dialog_content = "Las calles de Umbraton parecen un caos complicado, pero siguen sus propios principios.",
  ui_story_5051_50510101_X99_dialog_content = "Las personas aquí que entienden esos principios saben exactamente dónde colocar sus tiendas para la prosperidad.",
  ui_story_5051_50510101_100_dialog_content = "Ah, eso lo escuché de los viajeros que encontré en el camino.",
  ui_story_5051_50510101_101_dialog_content = "Me encantaría aprender más en algún momento cuando esté libre... Oye, ¿qué es eso volador?",
  ui_story_5051_50510101_102_dialog_content = "Eh, perdóname...",
  ui_story_5051_50510101_103_dialog_content = "¿Quien eres otra vez?",
  ui_story_5051_50510101_104_dialog_content = "¡Vaya! ¡Qué tonta, olvidé presentarme!",
  ui_story_5051_50510101_105_dialog_content = "Mi nombre es <color=#FFB400>Jakine</color>. ¡Soy el enviado de Northland!",
  ui_story_5051_50510101_106_dialog_content = "Perdón por llegar un poco tarde, pero ya sabes lo que dicen: ¡los héroes más grandes siempre llegan elegantemente tarde!",
  ui_story_5051_50510101_107_dialog_content = "<size=45>... ¡Creo que has superado con creces lo que uno consideraría tarde \"a la moda\"!</size>",
  ui_story_5051_50510101_X107_dialog_content = "Bueno, ya sabes lo que dicen. ¡El protagonista siempre aparece el último!",
  ui_story_5051_50510101_X108_dialog_content = "¡Ejem, buenas noches, señores y señoras!",
  ui_story_5051_50510101_X109_dialog_content = "Esta noche, nos hemos reunido aquí bajo un mismo techo...",
  ui_story_5051_50510101_X110_dialog_content = "Para el banquete de una vez al año.",
  ui_story_5051_50510101_X111_dialog_content = "Disfrute de la suntuosa comida.",
  ui_story_5051_50510101_X112_dialog_content = "Pero a pesar de que las porciones eventualmente se sacian.",
  ui_story_5051_50510101_X113_dialog_content = "Y las libaciones se acabarán.",
  ui_story_5051_50510101_X114_dialog_content = "Todavía podemos mezclarnos y divertirnos.",
  ui_story_5051_50510101_X115_dialog_content = "Mientras disfruta del delicioso entretenimiento.",
  ui_story_5051_50510101_108_dialog_content = "Saludos, estimados invitados.",
  ui_story_5051_50510101_109_dialog_content = "Somos los Keating Coro,",
  ui_story_5051_50510101_110_dialog_content = "y ahora vamos a cantar una canción.",
  ui_story_5051_50510101_111_dialog_content = "Lo llamamos, \"Oda a Lumopolis\".",
  ui_story_5051_50510101_112_dialog_content = "¡Esperamos que lo disfrutes!",
  ui_story_5051_50510101_113_dialog_content = "¡El sol y las estrellas suben al cielo! ♪",
  ui_story_5051_50510101_114_dialog_content = "¡Brillando su luz en un trono tan alto! ♪",
  ui_story_5051_50510101_115_dialog_content = "¡Nuestro escudo inquebrantable! ♪",
  ui_story_5051_50510101_116_dialog_content = "¡Nuestra lanza imparable! ♪",
  ui_story_5051_50510101_117_dialog_content = "¡Gloria y nobleza, testamento de fe! ♪",
  ui_story_5051_50510101_118_dialog_content = "¡Esplendor rotundo, para ahuyentar la oscuridad! ♪",
  ui_story_5051_50510101_119_dialog_content = "¡Un castillo en lo alto que siempre permanecerá! ♪",
  ui_story_5051_50510101_120_dialog_content = "¡Una fuente de dulces recuerdos! ♪",
  ui_story_5051_50510101_121_dialog_content = "¡El objeto de nuestra alabanza! ♪",
  ui_story_5051_50510101_122_dialog_content = "Su resplandor vence a la oscuridad, ♪",
  ui_story_5051_50510101_123_dialog_content = "¡Y nos trae días interminables y felices! ♪",
  ui_story_5051_50510101_124_dialog_content = "¡Noche Blanca en lo alto! Gracias a todos.",
  ui_story_5051_50510101_125_dialog_content = "Wow, hermoso, que gran canción!",
  ui_story_5051_50510101_X125_dialog_content = "¡Estos niños tienen un talento especial para las artes!",
  ui_story_5051_50510101_126_dialog_content = "Realmente saben cómo limpiar y dar un buen espectáculo, ¿eh?",
  ui_story_5051_50510101_127_dialog_content = "Naturalmente. De lo contrario, ¿quién los invitaría a una ocasión tan importante como esta?",
  ui_story_5051_50510101_128_dialog_content = "Si tan solo pudieran comportarse así de bien todo el tiempo...",
  ui_story_5051_50510101_129_dialog_content = "...",
  ui_story_5051_50510101_130_dialog_content = "¿Mmm? oh, supongo Michael ¡está de acuerdo!",
  ui_story_5051_50510101_131_dialog_content = "\"Esplendor rotundo, para ahuyentar la oscuridad. Un castillo en lo alto que siempre permanecerá\".",
  ui_story_5051_50510101_132_dialog_content = "—La crisis de Darkover.",
  ui_story_5051_50510101_133_dialog_content = "Esa catástrofe de pesadilla no es más que una parte de nuestra historia ahora.",
  ui_story_5051_50510101_134_dialog_content = "La crisis de Darkover... Padre... Madre...",
  ui_story_5051_50510101_135_dialog_content = "¡Ay! ¡Detente, detente, detente! Se supone que este es un banquete feliz, ¡así que no más pensamientos sombríos!",
  ui_story_5051_50510101_136_dialog_content = "...",
  ui_story_5051_50510101_137_dialog_content = "¿Ver? ¡Incluso Michael asiente con la cabeza!",
  ui_story_5051_50510101_138_dialog_content = "Perdóname, Uriel. Me expresé mal hace un momento.",
  ui_story_5051_50510101_139_dialog_content = "Está bien, estoy acostumbrado a este tipo de dolor. A lo que no estoy acostumbrado es a los banquetes.",
  ui_story_5051_50510101_140_dialog_content = "¡S-Sí, no es broma! ¡Está tan sofocante aquí con toda esta gente!",
  ui_story_5051_50510101_141_dialog_content = "¡Vamos, vamos a tomar un helado!",
  ui_story_5051_50510101_142_dialog_content = "<size=30>No te quedes ahí parado, Michael! Ayúdame con Uriel!</size>",
  ui_story_5051_50510101_143_dialog_content = "...",
  ui_story_5051_50510101_144_dialog_content = "Madre mía, qué niños traviesos. Aparto la mirada por un segundo y no están a la vista.",
  ui_story_5051_50510101_145_dialog_content = "Pero el sufrimiento que ha traído sigue siendo tan indeleble y persistente como antes.",
  ui_story_5051_50510101_146_dialog_content = "Aquellos que sobrevivieron a la terrible experiencia no tienen forma de dejar ir ese dolor. Incluso los poderosos Cuatro Ángeles no son una excepción.",
  ui_story_5051_50510101_147_dialog_content = "Ven ahora, Irridon! ¿Por qué no te animas un poco?",
  ui_story_5051_50510101_148_dialog_content = "El banquete de esta noche no será largo.",
  ui_story_5051_50510101_149_dialog_content = "¡Sigue deprimiéndote así y te perderás el resto!",
  ui_story_5051_50510101_150_dialog_content = "Schwartz El Día de la Familia fue originalmente una conmemoración de los muchos logros de la Schwartz familia.",
  ui_story_5051_50510101_151_dialog_content = "En este día <color=#FFB400>hace doce años</color>, el señor de la ciudad actual superó una serie de situaciones peligrosas, en última instancia, demostrando la Schwartz el poder de la familia a todo Lumopolis.",
  ui_story_5051_50510101_152_dialog_content = "Pero desde la Crisis de Darkover, el banquete de celebración se ha reducido tanto en tamaño como en grandeza.",
  ui_story_5051_50510101_153_dialog_content = "Todavía recuerdo una época en que las bandas de música y los desfiles de carrozas eran la norma para esta festividad.",
  ui_story_5051_50510101_154_dialog_content = "¿Es eso así? No recuerdo todo eso claramente.",
  ui_story_5051_50510101_155_dialog_content = "Pero recuerdo que la gente se queja de Schwartz Día de la familia todos los años.",
  ui_story_5051_50510101_156_dialog_content = "¿Cuáles fueron sus palabras otra vez? Oh, claro.",
  ui_story_5051_50510101_157_dialog_content = "\"Una ocasión como esta exige una celebración adecuada, una que transmita la lealtad y el respeto de los jóvenes talentos de Lumopolis a su señor de la ciudad\", ¡o algo así!",
  ui_story_5051_50510101_158_dialog_content = "Es por eso que finalmente se conservó una versión menos ostentosa del banquete.",
  ui_story_5051_50510101_159_dialog_content = "Estoy completamente de acuerdo con la decisión del Señor de la Ciudad de mantener las cosas simples. En términos de costos laborales y monetarios, esta es una opción mucho más razonable.",
  ui_story_5051_50510101_160_dialog_content = "Pero una celebración les da a muchas personas trabajadoras la oportunidad de descansar un poco.",
  ui_story_5051_50510101_161_dialog_content = "¡Y para ponerse al día con los últimos chismes!",
  ui_story_5051_50510101_162_dialog_content = "Eso no es necesario.",
  ui_story_5051_50510101_163_dialog_content = "¿Podemos entrar ahora?",
  ui_story_5051_50510101_164_dialog_content = "¡Por supuesto que somos!",
  ui_story_5051_50510101_165_dialog_content = "Por cierto, ¿por qué no entramos mientras cantaba el coro?",
  ui_story_5051_50510101_166_dialog_content = "Todo el mundo disfrutaba en silencio de la actuación del coro, así que no quería distraer a nadie irrumpiendo. Habría sido descortés.",
  ui_story_5051_50510101_167_dialog_content = "¿Eh? ¿Es eso una cosa?",
  ui_story_5051_50510101_168_dialog_content = "Bueno... sí... interrumpir una actuación es bastante grosero.",
  ui_story_5051_50510101_169_dialog_content = "Mia, si estuvieras usando este atuendo cuando me dijiste que eras la hermana mayor de Carleen...",
  ui_story_5051_50510101_170_dialog_content = "Te hubiera creído totalmente en un instante.",
  ui_story_5051_50510101_171_dialog_content = "¡Te ves exactamente como una princesa de Lumopolis ahora mismo!",
  ui_story_5051_50510101_172_dialog_content = "E-Esto es solo un vestido normal. Solo me estoy vistiendo para lucir el papel para el banquete...",
  ui_story_5051_50510101_173_dialog_content = "¡Eso es tres veces ahora! ¡Has dicho exactamente lo mismo tres veces de camino aquí!",
  ui_story_5051_50510101_174_dialog_content = "¿Podrías dejar de mirarla con los ojos como un asqueroso?",
  ui_story_5051_50510101_175_dialog_content = "¡Yo no estaba comiéndome con los ojos! ¡Estoy tan asombrado, eso es todo!",
  ui_story_5051_50510101_176_dialog_content = "¡No lo compro! Además, ¿no le prometiste a esa otra chica que la llevarías al banquete? ¿La del vestido morado?",
  ui_story_5051_50510101_177_dialog_content = "¡¿Cómo pudiste dejarla por otra chica tan fácilmente?!",
  ui_story_5051_50510101_178_dialog_content = "¿De qué estás hablando? La chica del vestido morado en el Colossus estaba Mia! ¡Ahora solo lleva un vestido blanco!",
  ui_story_5051_50510101_179_dialog_content = "¿Me estás tomando el pelo? ¡Ni siquiera podía decirlo! ¡¿Qué tipo de Luminática mágica usó?!",
  ui_story_5051_50510101_180_dialog_content = "¡¿Eh?! ¿P-Por qué te estás acercando tanto, de repente...?",
  ui_story_5051_50510101_181_dialog_content = "¡Estuviste con nosotros todo el tiempo! ¡¿Cómo pudiste no darte cuenta?!",
  ui_story_5051_50510101_182_dialog_content = "¡Jejeje, supongo que estaba demasiado distraído con las vistas de Lumopolis!",
  ui_story_5051_50510101_183_dialog_content = "¿No deberíamos entrar ahora, ustedes dos...?",
  ui_story_5051_50510101_184_dialog_content = "S-Sí, tienes razón.",
  ui_story_5051_50510101_185_dialog_content = "Deberíamos revisar nuestros dones, solo para estar seguros. Todos nos acordamos de traer uno, ¿verdad?",
  ui_story_5051_50510101_186_dialog_content = "¡Pero por supuesto! ¡Como enviado de la Reina, traje un regalo inolvidable!",
  ui_story_5051_50510101_187_dialog_content = "También traje uno, pero...",
  ui_story_5051_50510101_188_dialog_content = "(Un tarro de miel de diente de león podría estar demasiado mal para este tipo de evento...)",
  ui_story_5051_50510101_189_dialog_content = "(Es el mejor lote del año, pero no parece encajar en esta mansión).",
  ui_story_5051_50510101_190_dialog_content = "Ese tarro de miel se ve increíble. Apuesto a que sabría genial con una taza de té.",
  ui_story_5051_50510101_191_dialog_content = "¿Quién sabe? ¡Incluso podría comenzar una nueva tendencia entre los nobles!",
  ui_story_5051_50510101_192_dialog_content = "(Mia vio a través de mí! ¡Incluso ya está tratando de consolarme!)",
  ui_story_5051_50510101_193_dialog_content = "Solo espero que al Señor de la Ciudad le guste. De todos modos, ¡estoy listo cuando ustedes lo estén! ¡Vamos!",
  ui_story_5051_50510101_194_dialog_content = "A todos nuestros respetados invitados, bienvenidos al evento de este año. Schwartz Dia familiar.",
  ui_story_5051_50510101_195_dialog_content = "Por favor prepare sus invitaciones y regístrese aquí.",
  ui_story_5051_50510101_196_dialog_content = "Invitación, invitación... ¡tengo la mía justo aquí! ¡Ahora solo firma mi nombre!",
  ui_story_5051_50510101_197_dialog_content = "¿Enviado de Northland? Sí, parece que estás en la lista.",
  ui_story_5051_50510101_198_dialog_content = "Por la seguridad de quienes lo rodean, le pido que mantenga a su mascota bajo estrecha supervisión. Disfruta del banquete.",
  ui_story_5051_50510101_199_dialog_content = "¡No es un problema! Whisper se porta perfectamente bien, ¿no es así?",
  ui_story_5051_50510101_200_dialog_content = "¡Silbido!",
  ui_story_5051_50510101_X200_dialog_content = "Por favor, disfrute de las festividades de esta noche.",
  ui_story_5051_50510101_X201_dialog_content = "Por supuesto. ¡Gracias!",
  ui_story_5051_50510101_201_dialog_content = "Aquí está mi invitación.",
  ui_story_5051_50510101_202_dialog_content = "PlayerName de Eraveil. Nos sentimos honrados de tenerlo aquí hoy.",
  ui_story_5051_50510101_203_dialog_content = "Gracias por dedicar una noche de su tiempo para unirse a nosotros para Schwartz Dia familiar. Por favor, diviértete esta noche.",
  ui_story_5051_50510101_204_dialog_content = "Nuestros sirvientes están a su entera disposición, si necesita algo. Estaremos encantados de ofrecerle sólo nuestro mejor servicio.",
  ui_story_5051_50510101_205_dialog_content = "Oye, ¿qué da? ¿Por qué te tratan como a la realeza? ¡Pensé que era el enviado de Northland!",
  ui_story_5051_50510101_206_dialog_content = "¡Y yo soy el último Caelestite!",
  ui_story_5051_50510101_207_dialog_content = "(¡No tenía idea de que era tan respetado por aquí!)",
  ui_story_5051_50510101_208_dialog_content = "Perdóneme, señorita, pero ¿quién podría ser usted? ¿Tienes una invitación?",
  ui_story_5051_50510101_209_dialog_content = "!",
  ui_story_5051_50510101_210_dialog_content = "(Mia se siente lo suficientemente cómoda con Jakine y yo para hablar con nosotros, pero ella todavía es demasiado tímida para hablar con extraños).",
  ui_story_5051_50510101_211_dialog_content = "(Ella ha estado actuando de manera extraña desde que llegamos, como si tuviera miedo de las personas reunidas aquí hoy).",
  ui_story_5051_50510101_212_dialog_content = "¡Ella es mi amiga!",
  ui_story_5051_50510101_213_dialog_content = "Veo. Cualquier amigo tuyo no necesita invitación.",
  ui_story_5051_50510101_214_dialog_content = "Por favor entra.",
  ui_story_5051_50510101_215_dialog_content = "(¿Realmente tenía que decirlo de esa manera? ¿O es solo la forma en que la gente habla en la clase alta?)",
  ui_story_5051_50510101_216_dialog_content = "Gracias, PlayerName...",
  ui_story_5051_50510101_217_dialog_content = "Pedazo de pastel! Te entendí.",
  ui_story_5051_50510101_218_dialog_content = "¡Tch! Todos están tan ocupados adulando PlayerName que se han olvidado de mí!",
  ui_story_5051_50510101_219_dialog_content = "Perdóname, pero eres señorita Jakine, el enviado de Northland?",
  ui_story_5051_50510101_220_dialog_content = "¡Así es! Soy el único, el mensajero más nuevo de la Reina del Norte, Jakine!",
  ui_story_5051_50510101_221_dialog_content = "Veo. Así que los rumores eran ciertos: la nueva enviada de Northland tiene el mismo hermoso cabello carmesí que su predecesora.",
  ui_story_5051_50510101_222_dialog_content = "Espera, te has encontrado <color=#FFB400>Booz</color> ¿antes? Esa es mi mamá, ¿sabes?",
  ui_story_5051_50510101_223_dialog_content = "Excelente...",
  ui_story_5051_50510101_224_dialog_content = "Permítame presentarme. Soy Caleb, un noble de Lumopolis. Al igual que usted, estoy aquí por invitación de Lord Schwartz.",
  ui_story_5051_50510101_225_dialog_content = "Iba justo de camino a verlo. ¿Te importaría acompañarme?",
  ui_story_5051_50510101_226_dialog_content = "Bueno...",
  ui_story_5051_50510101_227_dialog_content = "Podríamos hablar de tu madre en el camino, si quieres.",
  ui_story_5051_50510101_228_dialog_content = "R-¿En serio? ¡Genial!",
  ui_story_5051_50510101_X225_dialog_content = "¿Tiene usted el honor? ¿Te importa poner eso en un lenguaje sencillo?",
  ui_story_5051_50510101_X226_dialog_content = "Jajaja... En pocas palabras, el Señor de la Ciudad me envió específicamente para ti.",
  ui_story_5051_50510101_X227_dialog_content = "¡¿Él envió gente para que viniera a escoltarme?!",
  ui_story_5051_50510101_X228_dialog_content = "¡Lo sabía! ¿Cómo podría un enviado de Northland no tener influencia?",
  ui_story_5051_50510101_X229_dialog_content = "¡Espera, déjame decirle a mis amigos que vinieron conmigo!",
  ui_story_5051_50510101_229_dialog_content = "¡Jejeje! Échale un vistazo, PlayerName! ¡Este simpático noble me llevará a ver al Señor de la Ciudad! ¡A-Dios!",
  ui_story_5051_50510101_230_dialog_content = "Espera, ¿dónde estás? Y ella se ha ido, así como así.",
  ui_story_5051_50510101_231_dialog_content = "Ella realmente es otra cosa. ¿Cómo podía huir con un extraño así, cuando Queen Bethlehem me pidió específicamente que la acompañara?",
  ui_story_5051_50510101_X231_dialog_content = "(Bueno, solo vine aquí porque no quería rechazar la invitación).",
  ui_story_5051_50510101_X232_dialog_content = "(Pero desde Mia cuenta conmigo para acercarme a su familia, no puedo decepcionarla).",
  ui_story_5051_50510101_X233_dialog_content = "¿Estás bien, Mia?",
  ui_story_5051_50510101_232_dialog_content = "yo, eh...",
  ui_story_5051_50510101_233_dialog_content = "(Oh no, este lugar está lleno de nobles de Lumopolis. Parece que Mia ya está en su límite).",
  ui_story_5051_50510101_234_dialog_content = "¿Qué tal si encontramos un lugar tranquilo por ahora?",
  ui_story_5051_50510101_235_dialog_content = "Pero todavía tengo que ver Carleen...",
  ui_story_5051_50510101_236_dialog_content = "¡No te preocupes! Por ahora, quédate aquí y descansa. ¡Te prometo que la llevaré a verte pronto!",
  ui_story_5051_50510101_237_dialog_content = "PlayerName...",
  ui_story_5051_50510101_238_dialog_content = "Hay una sala de recepción a la izquierda...",
  ui_story_5051_50510101_239_dialog_content = "¡A la izquierda! ¡Entiendo!",
  ui_story_5051_50510101_240_dialog_content = "La puerta se abre hacia el otro lado. No sirve de nada tirar de eso...",
  ui_story_5051_50510101_241_dialog_content = "¡Correcto! ¡Y allá vamos!",
  ui_story_5051_50510101_X238_dialog_content = "Hay tres puertas. La puerta de la sala de recepción tiene dos jarrones blancos al lado...",
  ui_story_5051_50510101_X239_dialog_content = "Cuando Carleen era joven, sin darse cuenta rayó el marco de la puerta...",
  ui_story_5051_50510101_X240_dialog_content = "Gire a la izquierda por la puerta... Tiene razón, hay tres puertas aquí.",
  ui_story_5051_50510101_X241_dialog_content = "La que tiene dos jarrones blancos junto a ella es... la puerta más a la izquierda.",
  ui_story_5051_50510101_X242_dialog_content = "¡Sí, es la sala de recepción seguro!",
  ui_story_5051_50510101_X243_dialog_content = "(Hay un rasguño bastante discreto en la parte interior de la puerta, al igual que Mia dicho.)",
  ui_story_5051_50510101_242_dialog_content = "(Mia parece terriblemente familiarizado con este lugar. Es como si ella hubiera estado aquí antes.)",
  ui_story_5051_50510101_243_dialog_content = "(¿Podría ser realmente una princesa de Lumopolis...?)",
  ui_story_5051_50510201_1_dialog_content = "La interpretación del coro de la Oda a Lumopolis ya ha terminado.",
  ui_story_5051_50510201_2_dialog_content = "El resto de las actuaciones de esta noche son en su mayoría canciones y bailes presentados por jóvenes nobles talentosos.",
  ui_story_5051_50510201_3_dialog_content = "Muchos de nuestros distinguidos invitados esperan que usted haga acto de presencia y los disfrute.",
  ui_story_5051_50510201_4_dialog_content = "A varios de ellos también les gustaría hacer cambios en el programa de esta noche.",
  ui_story_5051_50510201_5_dialog_content = "\"El solo de instrumento de mi hijo debería ser el final\", \"El baile de mi hija debe posponerse hasta que encontremos un fondo adecuado para él\", y así sucesivamente.",
  ui_story_5051_50510201_6_dialog_content = "Ya me he ocupado de estas solicitudes de una manera adecuada. ¿Le importaría echar un vistazo?",
  ui_story_5051_50510201_7_dialog_content = "Está bien, confío en ti.",
  ui_story_5051_50510201_8_dialog_content = "Gracias por encargarse de la planificación y seguridad del banquete en ausencia de Carleen.",
  ui_story_5051_50510201_9_dialog_content = "Se supone que es deber de Carleen organizar el Día de la Familia.",
  ui_story_5051_50510201_10_dialog_content = "Pero todos estos años, ella siempre ha optado por ignorarlo.",
  ui_story_5051_50510201_11_dialog_content = "Para mí, hoy es el día en que mamá falleció.",
  ui_story_5051_50510201_12_dialog_content = "No pude estar con ella durante sus últimos momentos, así que no me quedaré en la ciudad ahora.",
  ui_story_5051_50510201_13_dialog_content = "Dice lo mismo todos los años y luego desaparece de Lumopolis.",
  ui_story_5051_50510201_14_dialog_content = "Aunque no estuvo con ella por mucho tiempo, la pérdida de su madre todavía la duele hasta el día de hoy.",
  ui_story_5051_50510201_15_dialog_content = "¿Es su creencia que la Señora Carleen le falta madurez?",
  ui_story_5051_50510201_16_dialog_content = "Por el contrario, todo esto tiene sus raíces en errores tontos que cometí en mi juventud.",
  ui_story_5051_50510201_17_dialog_content = "Simplemente estoy cosechando lo que sembré.",
  ui_story_5051_50510201_18_dialog_content = "Te culpas demasiado a ti mismo.",
  ui_story_5051_50510201_19_dialog_content = "Sólo somos mortales, mi señor. Todo lo que podemos hacer es esforzarnos por alcanzar la grandeza con la pequeña cantidad de tiempo que se nos da.",
  ui_story_5051_50510201_20_dialog_content = "Solo necesita mirar el estado actual de Lumopolis para ver lo que ha logrado.",
  ui_story_5051_50510201_21_dialog_content = "Sin usted, incluso los mejores guías no tendrían forma de presentar la gloria de Lumopolis a sus numerosos visitantes.",
  ui_story_5051_50510201_22_dialog_content = "No podría haberlo dicho mejor yo mismo, Ms. Blanc!",
  ui_story_5051_50510201_23_dialog_content = "O, a juzgar por tu atuendo, ¿debería llamarte la venerable Sra. Rot?",
  ui_story_5051_50510201_24_dialog_content = "Hola, Duque Otto. El banquete de hoy es una celebración del Señor. Schwartz y sus muchos logros.",
  ui_story_5051_50510201_25_dialog_content = "Mi papel es pequeño y no merece ningún elogio. Puedes dirigirte a mí como quieras.",
  ui_story_5051_50510201_26_dialog_content = "¿Pequeño, dices? ¡Jajaja! Tienes bastante sentido del humor, Sra. Rot de la Guardia Nocturna.",
  ui_story_5051_50510201_27_dialog_content = "Perdóneme por llegar tarde, mi señor. Ruego por no haber interrumpido tus recuerdos.",
  ui_story_5051_50510201_28_dialog_content = "No hay necesidad de observar las formalidades habituales esta noche. Solo necesitas disfrutar del banquete.",
  ui_story_5051_50510201_29_dialog_content = "Pero eso no funcionará en absoluto, mi señor. Después de todo, esta noche conmemora tus grandes contribuciones a nuestra feria Lumopolis.",
  ui_story_5051_50510201_30_dialog_content = "Una pena que las personas más cercanas a ti no lo vean así.",
  ui_story_5051_50510201_31_dialog_content = "Esto debe ser lo que significa estar \"solo en la cima de la montaña\".",
  ui_story_5051_50510201_32_dialog_content = "Pero tú también debes conocer el sentimiento, Otto.",
  ui_story_5051_50510201_33_dialog_content = "Después de todo, has sacrificado mucho a lo largo de los años por el bien de la familia Troy y el Consejo de Ancianos.",
  ui_story_5051_50510201_34_dialog_content = "Me halagas, mi señor. Mis logros no son nada comparados con los tuyos.",
  ui_story_5051_50510201_35_dialog_content = "Mi hijo dará un discurso después de que termine la actuación actual. Se sentiría honrado si estuvieras allí para escucharlo.",
  ui_story_5051_50510201_36_dialog_content = "Lamentablemente, un invitado de honor ha solicitado una audiencia conmigo.",
  ui_story_5051_50510201_37_dialog_content = "Sin embargo, estoy seguro de que el pequeño espectáculo de talentos de su hijo no pasará desapercibido para los invitados de esta noche.",
  ui_story_5051_50510201_38_dialog_content = "Por ahora, se requiere mi presencia en otro lugar.",
  ui_story_5051_50510201_39_dialog_content = "Mi señor, un sirviente está aquí con el invitado que solicitó verlo.",
  ui_story_5051_50510201_40_dialog_content = "También estábamos hablando de eso. Por favor disfruta del banquete, Otto.",
  ui_story_5051_50510201_41_dialog_content = "Muy bien, mi señor.",
  ui_story_5051_50510201_42_dialog_content = "... ¡Es por eso que siempre digo que los dragones son una raza tan mágica!",
  ui_story_5051_50510201_43_dialog_content = "Caben en la palma de tu mano cuando son jóvenes, ¡pero luego crecen hasta ser tan grandes como un coloso!",
  ui_story_5051_50510201_44_dialog_content = "Ahora que lo pienso, los dragones y los colosos se parecen un poco. ¿Podrían estar relacionados de alguna manera?",
  ui_story_5051_50510201_45_dialog_content = "ejem, señorita Jakine?",
  ui_story_5051_50510201_46_dialog_content = "Sí, ¿qué es?",
  ui_story_5051_50510201_47_dialog_content = "Me dijeron que su predecesora, Lady Boaz, era toda una maestra de la adivinación.",
  ui_story_5051_50510201_48_dialog_content = "Siempre me han cautivado las artes de adivinación de Northland. ¿Tienes algún conocimiento sobre el tema, por casualidad?",
  ui_story_5051_50510201_49_dialog_content = "¡Por supuesto que sí! De hecho, soy un maestro de—",
  ui_story_5051_50510201_50_dialog_content = "*Ejem* S-sí, incursiono un poco en la adivinación.",
  ui_story_5051_50510201_51_dialog_content = "Reina Bethlehem me envió aquí específicamente para reponer el <color=#FFB400>Cristal de memoria eterna</color> con agua del lago Mirror.",
  ui_story_5051_50510201_52_dialog_content = "Creo que he oído hablar de este objeto antes.",
  ui_story_5051_50510201_53_dialog_content = "Pero, ¿por qué este Cristal de la Memoria Eterna requiere agua del Lago Mirror?",
  ui_story_5051_50510201_54_dialog_content = "Tenía la impresión de que era simplemente un recipiente para almacenar Lumina...",
  ui_story_5051_50510201_55_dialog_content = "saludos, señorita Jakine. Te he encontrado por fin.",
  ui_story_5051_50510201_56_dialog_content = "¡Oh hola!",
  ui_story_5051_50510201_57_dialog_content = "<size=30>¡Psst! ¿Quién se supone que es esta dama, Sr. Caleb?</size>",
  ui_story_5051_50510201_58_dialog_content = "Ha sido un largo tiempo, Ms. Blanc.",
  ui_story_5051_50510201_59_dialog_content = "Ha pasado bastante tiempo, sí. Creo que esta es la primera vez que te veo en el banquete del Día de la Familia. Gracias por honrarnos con su asistencia.",
  ui_story_5051_50510201_60_dialog_content = "Esto es Ms. Blanc. Piensa en ella como una asistente personal del mismísimo Señor de la Ciudad.",
  ui_story_5051_50510201_61_dialog_content = "Cierto...",
  ui_story_5051_50510201_62_dialog_content = "Extrañar Jakine, Caballero Schwartz te está esperando en la sala de recepción. Por aqui por favor.",
  ui_story_5051_50510201_63_dialog_content = "¡C-Cómo estás! Soy Jakine¡Enviado de la Reina Belén!",
  ui_story_5051_50510201_64_dialog_content = "¡Han pasado más de doce años desde que un emisario del norte vino a visitar Lumopolis!",
  ui_story_5051_50510201_65_dialog_content = "Por orden de Su Majestad, he venido a reponer el Cristal de la Eterna Memoria con <color=#FFB400>agua del lago espejo</color>.",
  ui_story_5051_50510201_66_dialog_content = "Gracias por venir aquí hoy, enviado de Northland.",
  ui_story_5051_50510201_67_dialog_content = "Su Majestad ya me ha informado de los detalles. En nombre de Lumopolis, les agradezco que hayan viajado tan lejos para llevar a cabo su misión.",
  ui_story_5051_50510201_68_dialog_content = "¡Todo en un día de trabajo! ¡Es mi responsabilidad, después de todo!",
  ui_story_5051_50510201_69_dialog_content = "Sra. Rot, ¿podría traernos el Cristal de la memoria eterna?",
  ui_story_5051_50510201_70_dialog_content = "Como desees.",
  ui_story_5051_50510201_71_dialog_content = "...",
  ui_story_5051_50510201_72_dialog_content = "Según recuerdo, le pedí específicamente a la Sra. Rot que recibiera al enviado de Northland hoy.",
  ui_story_5051_50510201_73_dialog_content = "¿Quizás te hiciste amigo del enviado durante el banquete, Caleb?",
  ui_story_5051_50510201_74_dialog_content = "Perdóname, mi señor.",
  ui_story_5051_50510201_75_dialog_content = "Como miembro de la familia Magnus, simplemente pensé que tenía un deber que cumplir. Después de todo, esto implica una <color=#FFB400>reliquia de mi hermana</color>.",
  ui_story_5051_50510201_76_dialog_content = "No tenía idea de que te opondrías a mi presencia de esta manera.",
  ui_story_5051_50510201_77_dialog_content = "(¿Una reliquia de su hermana? ¿La familia Magnus? ¿De qué están hablando estos tipos? ¡¿Y por qué la atmósfera se siente tan incómoda de repente?!)",
  ui_story_5051_50510201_78_dialog_content = "(Cometí un error, PlayerName, Mia...)",
  ui_story_5051_50510201_X78_dialog_content = "(No debería haber ido solo para completar esta misión... ¡Que alguien venga a salvarme!)",
  ui_story_5051_50510201_79_dialog_content = "Mi señor, invité al Sr. Caleb aquí hoy.",
  ui_story_5051_50510201_80_dialog_content = "Deseaba buscar su audiencia sobre cierto asunto. Como estará bastante ocupado más tarde esta noche, pensé que era mejor dejarlo venir aquí y decir lo que piensa.",
  ui_story_5051_50510201_81_dialog_content = "Como miembro de tu familia, merece ser prioritario, me imagino.",
  ui_story_5051_50510201_82_dialog_content = "Sra. Rot... A veces pienso que es demasiado buena en su trabajo.",
  ui_story_5051_50510201_83_dialog_content = "Gracias por tu elogio.",
  ui_story_5051_50510201_84_dialog_content = "Aquí está el Cristal de la Memoria Eterna. Gracias de nuevo por tu ayuda.",
  ui_story_5051_50510201_85_dialog_content = "¡Está bien, déjamelo a mí!",
  ui_story_5051_50510201_86_dialog_content = "(¡Estoy salvado! Oh, gracias, Ms. Blanc!)",
  ui_story_5051_50510201_87_dialog_content = "Sr. Caleb, cierto invitado nos dio este vino de Umbraton esta noche.",
  ui_story_5051_50510201_88_dialog_content = "Tiene un efecto calmante muy especial. Por favor, toma un vaso.",
  ui_story_5051_50510201_89_dialog_content = "...Gracias.",
  ui_story_5051_50510201_90_dialog_content = "Si no me equivoco, Caleb, tu razón para venir aquí hoy es el Cristal de la Memoria Eterna. ¿Estoy en lo correcto?",
  ui_story_5051_50510201_91_dialog_content = "este especial <color=#FFB400>dispositivo de grabación</color> nos fue dado a Joshua y a mí por la Reina del Norte como un regalo.",
  ui_story_5051_50510201_92_dialog_content = "Hace doce años, fue mi esposa, tu hermana, quien lo activó por su cuenta.",
  ui_story_5051_50510201_93_dialog_content = "Pero todo lo que contiene son algunos recuerdos dispersos de ese año.",
  ui_story_5051_50510201_94_dialog_content = "Simplemente me ocupé de él después de que ella falleciera, pero no tenía intención de quedármelo para mí.",
  ui_story_5051_50510201_95_dialog_content = "Si la Reina lo quiere de vuelta, no me opondría.",
  ui_story_5051_50510201_96_dialog_content = "... ¿Los recuerdos de su esposa e hijas realmente significan tan poco para usted?",
  ui_story_5051_50510201_97_dialog_content = "¡H-Su Majestad nunca dijo nada sobre recuperarlo, ya sabes!",
  ui_story_5051_50510201_98_dialog_content = "Además, el mundo dentro del cristal está alimentado por la Lumina de la persona que lo activó. Reina Bethlehem no le serviria!",
  ui_story_5051_50510201_99_dialog_content = "¿El mundo dentro del cristal?",
  ui_story_5051_50510201_100_dialog_content = "¡Así es! ¡El Cristal de la Memoria Eterna no es un dispositivo de grabación ordinario!",
  ui_story_5051_50510201_101_dialog_content = "Hay un completamente <color=#FFB400>mundo real</color> preservado dentro de él!",
  ui_story_5051_50510201_102_dialog_content = "Pero, ¿cómo es posible?",
  ui_story_5051_50510201_103_dialog_content = "Supongo que no está tan familiarizado con eso, Sr. Caleb.",
  ui_story_5051_50510201_104_dialog_content = "¡Déjame explicarte cómo funciona!",
  ui_story_5051_50510201_105_dialog_content = "Primero, el Cristal de la Memoria Eterna requiere una cantidad suficiente de agua del Lago Mirror para funcionar correctamente.",
  ui_story_5051_50510201_106_dialog_content = "Una vez listo, el cristal debe activarse infundiéndolo con Lumina del usuario.",
  ui_story_5051_50510201_107_dialog_content = "Posteriormente, el cristal comenzará a registrar todo lo que sucede en <color=#FFB400>un solo dia</color>, dentro de un cierto radio.",
  ui_story_5051_50510201_108_dialog_content = "Está preservado en el Cristal de la Memoria Eterna, para siempre en bucle en una recreación sin fin.",
  ui_story_5051_50510201_109_dialog_content = "¡Al infundirlo con Lumina una vez más, los usuarios pueden ingresar al mundo del cristal y experimentar la memoria ellos mismos!",
  ui_story_5051_50510201_110_dialog_content = "Y así es básicamente como funciona el Cristal de la Memoria Eterna y su universo de bolsillo.",
  ui_story_5051_50510201_111_dialog_content = "¡Pero hay una trampa! El cristal es extremadamente frágil...",
  ui_story_5051_50510201_112_dialog_content = "Una vez dentro, los usuarios deben mantenerse ocultos y evitar a toda costa interactuar con cualquier persona o cosa.",
  ui_story_5051_50510201_113_dialog_content = "<size=42>De lo contrario, ¡incluso el más pequeño de los cambios en la historia establecida podría resultar en una catástrofe inimaginable!</size>",
  ui_story_5051_50510201_114_dialog_content = "Así que así son los enigmáticos Lumináticos de Northland...",
  ui_story_5051_50510201_115_dialog_content = "<size=30>Qué odiosamente complicado.</size>",
  ui_story_5051_50510201_116_dialog_content = "¡Uf! ¡Ahí vamos, el cristal ahora está lleno de agua y listo para funcionar!",
  ui_story_5051_50510201_117_dialog_content = "Aquí tienes, Señor Schwartz.",
  ui_story_5051_50510201_118_dialog_content = "¡Puedes usarlo cuando quieras ahora!",
  ui_story_5051_50510201_119_dialog_content = "Tiene mi gratitud, enviado.",
  ui_story_5051_50510201_120_dialog_content = "Pero desafortunadamente... La persona que lo activó ya no está con nosotros.",
  ui_story_5051_50510201_121_dialog_content = "Antes de que nos dejara, nadie estaba dispuesto a volver a visitar el pasado registrado en el cristal.",
  ui_story_5051_50510201_122_dialog_content = "Y ahora que se ha ido, no tengo derecho a revolcarme en mi propio remordimiento una vez más.",
  ui_story_5051_50510201_123_dialog_content = "Me temo que nadie es capaz de activarlo de nuevo.",
  ui_story_5051_50510201_124_dialog_content = "Err...",
  ui_story_5051_50510201_125_dialog_content = "¡E-Eso está bien! Como practicante de adivinación de Northland, ¡estoy seguro de que puedo encontrar otra forma de usarlo!",
  ui_story_5051_50510201_126_dialog_content = "Déjame ver... El conjuro es algo así...",
  ui_story_5051_50510201_127_dialog_content = "...",
  ui_story_5051_50510201_128_dialog_content = "Déjame ver, el conjuro es algo así...",
  ui_story_5051_50510201_129_dialog_content = "Joshua, ¿no acordamos aprender juntos a usar el Cristal de la Memoria Eterna?",
  ui_story_5051_50510201_130_dialog_content = "Sé cuánto te gusta aprender, pero cuando te precipitas en cosas como esta, no puedo evitar sentirme un poco abandonado.",
  ui_story_5051_50510201_131_dialog_content = "¿Oh? No tenía idea de que podía hacerte sentir tan solo.",
  ui_story_5051_50510201_132_dialog_content = "Pensé que era el único que tenía que sufrir tal emoción.",
  ui_story_5051_50510201_133_dialog_content = "Perdoname mi Amor. He estado tan ocupado con mi trabajo que te he olvidado a ti ya las niñas.",
  ui_story_5051_50510201_134_dialog_content = "Jejeje Sólo estoy bromeando contigo.",
  ui_story_5051_50510201_135_dialog_content = "Solo gracias a tu esfuerzo tenemos la paz y la prosperidad necesarias para sentir todo tipo de emociones.",
  ui_story_5051_50510201_136_dialog_content = "Alegría, emoción, amor... Y también soledad.",
  ui_story_5051_50510201_137_dialog_content = "Pero ahora, tengo este regalo de la Reina del Norte.",
  ui_story_5051_50510201_138_dialog_content = "Si alguna vez me siento solo, siempre puedo ir a buscarte dentro de este Cristal de la Eterna Memoria.",
  ui_story_5051_50510201_139_dialog_content = "Josué...",
  ui_story_5051_50510201_140_dialog_content = "Entonces, ¿por favor déjame activarlo?",
  ui_story_5051_50510201_141_dialog_content = "Muy bien, querida. Mientras te haga feliz.",
  ui_story_5051_50510201_142_dialog_content = "¿Ya decidiste qué día quieres grabar?",
  ui_story_5051_50510201_143_dialog_content = "<color=#FFB400>Verónica</color> ¿cumpleaños? ¿O tal vez la primera actuación de Carleen? O quizás...",
  ui_story_5051_50510201_144_dialog_content = "¡Es un secreto!",
  ui_story_5051_50510201_145_dialog_content = "¿No me lo dirás, por favor? Prefiero no hacer el ridículo cuando decidas activarlo.",
  ui_story_5051_50510201_146_dialog_content = "¡Cielos, no sabía que el Señor de la Ciudad de Lumopolis fuera capaz de hacer el ridículo!",
  ui_story_5051_50510201_147_dialog_content = "Por supuesto que lo soy... ¿Recuerdas cuando accidentalmente pisé el juguete de Carleen y lo rompí?",
  ui_story_5051_50510201_148_dialog_content = "No pensé que le importara mucho en ese momento, ya que apenas reaccionó cuando sucedió. Poco sabía que pasó el resto del día llorando en su habitación...",
  ui_story_5051_50510201_149_dialog_content = "Oh, sí, te recuerdo parado frente a su puerta con un juguete nuevo, sin atreverte a entrar. La expresión de tu rostro asustó a más de unos pocos de nuestros sirvientes.",
  ui_story_5051_50510201_150_dialog_content = "¿Hay otros casos que se te ocurran?",
  ui_story_5051_50510201_151_dialog_content = "... Hubo una vez que dejé la corona de rosas que Verónica me regaló en la sala de recepción.",
  ui_story_5051_50510201_152_dialog_content = "Estaba tan ocupado con una invitada ese día que descuidadamente dejé su regalo sobre la mesa, sin darme cuenta de que pensó que no me gustaba y lo tiré a un lado...",
  ui_story_5051_50510201_153_dialog_content = "Y luego ordenaste a los jardineros que plantaran un jardín entero de rosas solo para ella.",
  ui_story_5051_50510201_154_dialog_content = "Desafortunadamente, la preocupación de nuestra hija por su entrenamiento la dejó sin tiempo ni interés para tejer coronas de flores nunca más...",
  ui_story_5051_50510201_155_dialog_content = "(suspiros)",
  ui_story_5051_50510201_156_dialog_content = "No hiciste el ridículo entonces, mi dulce Daniel.",
  ui_story_5051_50510201_157_dialog_content = "Este mundo es vasto y complejo, y estamos muy limitados en las cosas que podemos ver y hacer.",
  ui_story_5051_50510201_158_dialog_content = "Es por eso que creo que este Cristal de la Memoria Eterna es algo tan maravilloso... Nos ofrece la oportunidad de registrar esos momentos en nuestras vidas y atesorarlos mientras vivamos.",
  ui_story_5051_50510201_159_dialog_content = "Los recuerdos pueden ser tan poco fiables, pero con este cristal, nuestro verdadero ser se conservará por toda la eternidad.",
  ui_story_5051_50510201_160_dialog_content = "Bien, mal, bien, mal... Llegará un día en que nuestra familia se sienta perdida y confundida.",
  ui_story_5051_50510201_161_dialog_content = "Cuando llegue ese día, este cristal nos mostrará la <color=#FFB400>respuestas que necesitamos</color>. Estoy seguro de ello.",
  ui_story_5051_50510201_162_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_5051_50510201_163_dialog_content = "...",
  ui_story_5051_50510201_164_dialog_content = "Tú ahí, escondido en las sombras. Muéstrate.",
  ui_story_5051_50510201_165_dialog_content = "yo-soy yo, PlayerName! ¡Disculpa por interrumpir! Jajaja...",
  ui_story_5051_50510201_166_dialog_content = "Déjame ver si entiendo esto correctamente.",
  ui_story_5051_50510201_167_dialog_content = "Querías presentarle tu regalo al Señor de la Ciudad, así que irrumpiste en su sala de recepción sin preguntar.",
  ui_story_5051_50510201_168_dialog_content = "Pero cuando Señor Schwartz y sus invitados entraron en la habitación, instintivamente te escondiste en lugar de saludar a nadie.",
  ui_story_5051_50510201_169_dialog_content = "Desde entonces, has estado escuchando a escondidas detrás de las cortinas.",
  ui_story_5051_50510201_170_dialog_content = "¿Es eso correcto?",
  ui_story_5051_50510201_171_dialog_content = "Er, sí, eso es correcto. Lo siento...",
  ui_story_5051_50510201_172_dialog_content = "(Quiero decir, solo lo hice porque la primera reacción de Mia fue esconderse, así que simplemente la seguí...)",
  ui_story_5051_50510201_173_dialog_content = "(Probablemente no deberíamos haberla traído aquí tan pronto... No está en condiciones de conocer gente nueva en este momento).",
  ui_story_5051_50510201_174_dialog_content = "Aprecio tu honestidad y buenas intenciones, joven.",
  ui_story_5051_50510201_175_dialog_content = "Pero no es justo escuchar a escondidas.",
  ui_story_5051_50510201_176_dialog_content = "No dejes que vuelva a suceder, ¿entendido?",
  ui_story_5051_50510201_177_dialog_content = "Comprendido. Gracias Señor...",
  ui_story_5051_50510201_178_dialog_content = "Ahora bien, tengo otra pregunta para ti.",
  ui_story_5051_50510201_179_dialog_content = "¿La otra persona que acecha en las sombras también es amiga tuya?",
  ui_story_5051_50510201_180_dialog_content = "Si no, la Sra. Rot se deshará de ellos sin dudarlo.",
  ui_story_5051_50510201_X177_dialog_content = "Bueno, entonces permítame hacerle otra pregunta.",
  ui_story_5051_50510201_X178_dialog_content = "¿El ratón que se esconde debajo de la mesa es amigo tuyo?",
  ui_story_5051_50510201_X179_dialog_content = "Si no, lo espantaré.",
  ui_story_5051_50510201_181_dialog_content = "¡Ajajaja! ¡E-Ella es!",
  ui_story_5051_50510201_182_dialog_content = "Ven afuera, Mia. No tengas miedo, todas estas son buenas personas.",
  ui_story_5051_50510201_183_dialog_content = "¡E-Espera! Mi velo... ¡No puedo encontrar mi velo!",
  ui_story_5051_50510201_184_dialog_content = "¿Un noble de Lumopolis? Pero ella se ve...",
  ui_story_5051_50510201_185_dialog_content = "Vaya...?",
  ui_story_5051_50510201_186_dialog_content = "...",
  ui_story_5051_50510201_187_dialog_content = "¿Es esta otra de sus sorpresas para mí, Sra. Rot?",
  ui_story_5051_50510201_188_dialog_content = "No importa, solo limpia mi agenda antes de que suceda algo más.",
  ui_story_5051_50510201_189_dialog_content = "Lo siento mucho, mi señor. Iré a cancelar el resto de sus citas para el día.",
  ui_story_5051_50510201_190_dialog_content = "Por favor, hazlo.",
  ui_story_5051_50510201_191_dialog_content = "Así que si uso este... y lo combino con este... ¡Bingo!",
  ui_story_5051_50510201_192_dialog_content = "¡Creo que encontré el encantamiento exacto que necesitamos ahora mismo!",
  ui_story_5051_50510201_193_dialog_content = "Eso no será necesario. Por favor regrese al banquete con PlayerName y diviértanse.",
  ui_story_5051_50510201_194_dialog_content = "Los tres debemos hablar en privado...",
  ui_story_5051_50510201_195_dialog_content = "Ejem, Jakine, vamos primero—Jakine?",
  ui_story_5051_50510201_196_dialog_content = "¡Ad praeteritum! ¡Ad praeteritum! ¡Ad praeteritum!",
  ui_story_5051_50510201_197_dialog_content = "¡Revivamos los días dorados del pasado!",
  ui_story_5051_50510201_198_dialog_content = "<size=45>¡Abrahadabra!</size>",
  ui_story_5051_50510201_199_dialog_content = "¿Qué en el...?",
  ui_story_5051_50510201_200_dialog_content = "<size=45>¡¿Q-Qué está pasando?!</size>",
  ui_story_5051_50510201_201_dialog_content = "Ayúdame... PlayerName...",
  ui_story_5051_50510201_202_dialog_content = "Mia! ¡¡Toma mi mano!!",
  ui_story_5051_50510201_203_dialog_content = "¡Okay...!",
  ui_story_5051_50510201_204_dialog_content = "Uf... ¿Eh?",
  ui_story_5051_50510201_205_dialog_content = "Dónde estoy...?",
  ui_story_5051_50510201_206_dialog_content = "¡G-gracias a Dios, finalmente estás despierto!",
  ui_story_5051_50510201_207_dialog_content = "Mia, ¿Dónde estamos?",
  ui_story_5051_50510201_208_dialog_content = "Yo tampoco lo sé... ¡Pero tenemos que correr! ¡Llegan los eclipses!",
  ui_story_5051_50510201_209_dialog_content = "—!!!",
  ui_story_5051_50510201_210_dialog_content = "¿Eclipsitos?",
  ui_story_5051_50510201_211_dialog_content = "Por aquí, Mia! ¡Apurarse!",
  ui_story_5051_50510201_212_dialog_content = "P-pero PlayerName, de esa manera también—",
  ui_story_5051_50510201_213_dialog_content = "—!!!",
  ui_story_5051_50510201_214_dialog_content = "¡¡Estamos rodeados!!",
  ui_story_5051_50510201_215_dialog_content = "¡B-Baba Yaga! ¡¡Baba Yaga, ayuda!!",
  ui_story_5051_50510201_216_dialog_content = "Baba Yaga? ¿Por qué no dices nada...?",
  ui_story_5051_50510201_217_dialog_content = "Diablos... Hagas lo que hagas, Mia, no te vayas de mi lado!",
  ui_story_5051_50510201_218_dialog_content = "¡Adelante, asquerosos Eclipsitas!",
  ui_story_5051_50510201_219_dialog_content = "<size=45>¡Gahhhh!</size>",
  ui_story_5051_50510201_220_dialog_content = "por favor no...",
  ui_story_5051_50510201_221_dialog_content = "No...",
  ui_story_5051_50510201_222_dialog_content = "<size=45>no te atrevas a lastimar PlayerName!!!</size>",
  ui_story_5051_50510201_223_dialog_content = "¿¡Graagh!?",
  ui_story_5051_50510201_224_dialog_content = "METRO-Mia...?",
  ui_story_5051_50510201_225_dialog_content = "Uf... uf...",
  ui_story_5051_50510201_226_dialog_content = "¿Acaso... acabo de usar... Luminatics?",
  ui_story_5051_50510201_227_dialog_content = "No tenía idea de que también podrías usar Luminatics, Mia!",
  ui_story_5051_50510201_228_dialog_content = "Solía ser capaz de... Pero eso fue hace mucho tiempo. Desde entonces no he podido...",
  ui_story_5051_50510201_229_dialog_content = "—!!!",
  ui_story_5051_50510201_230_dialog_content = "¿Más eclipses? ¿Cuántos de ellos hay?",
  ui_story_5051_50510201_231_dialog_content = "¿Aún puedes pelear?",
  ui_story_5051_50510201_232_dialog_content = "no sé...",
  ui_story_5051_50510201_233_dialog_content = "Pero si no peleo, estarás en peligro.",
  ui_story_5051_50510201_234_dialog_content = "¡Tengo que protegerte!",
  ui_story_5051_50510201_235_dialog_content = "Puedes hacerlo, Mia!",
  ui_story_5051_50510201_236_dialog_content = "¡Mientras puedas usar Luminatics, puedo aumentar tu poder!",
  ui_story_5051_50510201_237_dialog_content = "¡Confía en mí y confía en ti mismo!",
  ui_story_5051_50510201_238_dialog_content = "Confía en ti... ¿Y en mí?",
  ui_story_5051_50510201_239_dialog_content = "¡Está bien! ¡Lo haré lo mejor que pueda!",
  ui_story_5051_50510301_1_dialog_content = "¿Están bien?",
  ui_story_5051_50510301_2_dialog_content = "Estoy bien. Aunque todavía me siento conmocionado...",
  ui_story_5051_50510301_3_dialog_content = "¡Creo que tengo un poco más de confianza ahora!",
  ui_story_5051_50510301_4_dialog_content = "No te lastimaste en toda la pelea, ¿verdad?",
  ui_story_5051_50510301_5_dialog_content = "¡De nada, así que no te preocupes por mí!",
  ui_story_5051_50510301_6_dialog_content = "Tengo que decir, Mia, eso fue impresionante! No mucha gente puede luchar contra tantos Eclipsites por su cuenta.",
  ui_story_5051_50510301_7_dialog_content = "R-¿En serio? Pero todo fue gracias a ti, creo.",
  ui_story_5051_50510301_8_dialog_content = "El poder de la Última Caelestita es realmente algo...",
  ui_story_5051_50510301_9_dialog_content = "Hablando de eso, no he sido capaz de sentir a nadie a nuestro alrededor desde que me desperté.",
  ui_story_5051_50510301_10_dialog_content = "¿Dónde diablos estamos? ¿Y adónde fueron todos los demás?",
  ui_story_5051_50510301_11_dialog_content = "¡Mira allá, a lo lejos! Es <color=#FFB400>Lumópolis</color>!",
  ui_story_5051_50510301_12_dialog_content = "Entonces, ¿esto significa que estamos en el <color=#FFB400>afueras de Lumópolis</color>?",
  ui_story_5051_50510301_13_dialog_content = "¿Cómo terminamos aquí...?",
  ui_story_5051_50510301_14_dialog_content = "¿Podría ser este el mundo dentro del <color=#FFB400>Cristal de memoria eterna</color>?",
  ui_story_5051_50510301_15_dialog_content = "¡Creo que probablemente tengas razón!",
  ui_story_5051_50510301_16_dialog_content = "¡Ad praeteritum! ¡Ad praeteritum! ¡Ad praeteritum!",
  ui_story_5051_50510301_17_dialog_content = "¡Revivamos los días dorados del pasado!",
  ui_story_5051_50510301_18_dialog_content = "¡Abrahadabra!",
  ui_story_5051_50510301_19_dialog_content = "Ahora recuerdo... supongo Jakine realmente es un maestro de la adivinación, después de todo.",
  ui_story_5051_50510301_20_dialog_content = "Pero aun así, parece que esta vez se adelantó demasiado.",
  ui_story_5051_50510301_21_dialog_content = "Sí...",
  ui_story_5051_50510301_22_dialog_content = "La recuerdo mencionando algo más también.",
  ui_story_5051_50510301_23_dialog_content = "“Una vez dentro, los usuarios deben mantenerse ocultos y evitar a toda costa interactuar con cualquier persona o cosa”.",
  ui_story_5051_50510301_24_dialog_content = "\"¡De lo contrario, incluso los cambios más pequeños en la historia establecida podrían resultar en una catástrofe inimaginable!\"",
  ui_story_5051_50510301_25_dialog_content = "Oh no... ¡Acabamos de pelearnos con un grupo de Eclipsites!",
  ui_story_5051_50510301_26_dialog_content = "¿Estaremos bien...?",
  ui_story_5051_50510301_27_dialog_content = "<size=45>Aaaah!!</size>",
  ui_story_5051_50510301_28_dialog_content = "¡E-Alguien está en problemas!",
  ui_story_5051_50510301_29_dialog_content = "Quién es ese...?",
  ui_story_5051_50510301_30_dialog_content = "¡Capitán! Hay demasiados eclipses, no podemos aguantar mucho más...",
  ui_story_5051_50510301_31_dialog_content = "¡Concéntrense, hombres! Incluso si tus compañeros soldados caen ante tus ojos, ¡no te atrevas a soltar tus armas!",
  ui_story_5051_50510301_32_dialog_content = "¡¡¡Maldita sea todo!!!",
  ui_story_5051_50510301_33_dialog_content = "Un vehículo de carga defendido por soldados de Lumopolis... ¡Y están siendo atacados por Eclipsites!",
  ui_story_5051_50510301_34_dialog_content = "Pero, ¿por qué hay tantos eclipses fuera de Lumopolis? ¡¿Qué está pasando?!",
  ui_story_5051_50510301_35_dialog_content = "¡N-Tenemos que ir a rescatarlos!",
  ui_story_5051_50510301_36_dialog_content = "¡Esperar! Jakine ¡Dijo que no podemos interferir con nada una vez dentro del Cristal de la Memoria Eterna!",
  ui_story_5051_50510301_37_dialog_content = "¡Si tomamos esos eclipses, no se sabe cuáles serán las consecuencias!",
  ui_story_5051_50510301_38_dialog_content = "Pero...",
  ui_story_5051_50510301_39_dialog_content = "¡Resiste hasta que te arrastren a tu tumba!",
  ui_story_5051_50510301_40_dialog_content = "—?!",
  ui_story_5051_50510301_41_dialog_content = "Los soldados de Lumopolis están a salvo ahora, señor. Podemos retirarnos en cualquier momento.",
  ui_story_5051_50510301_42_dialog_content = "Todavía no entiendo por qué estamos rescatando a los leales perros de Schwartz, considerando que a él le importa un carajo si vivimos o morimos.",
  ui_story_5051_50510301_43_dialog_content = "Incluso en unas vacaciones como esta, no nos ofreció ni un trozo de comida ni un lugar para descansar. Simplemente tomó nuestros regalos y nos echó a todos.",
  ui_story_5051_50510301_44_dialog_content = "¿Qué clase de Señor de la Ciudad es ese?",
  ui_story_5051_50510301_45_dialog_content = "No dejes que esos pequeños desaires nublen tu visión. Cuando sea el momento adecuado, la respuesta será clara para usted.",
  ui_story_5051_50510301_46_dialog_content = "Es <color=#FFB400>Tío Istvan</color>...!",
  ui_story_5051_50510301_47_dialog_content = "Espera, eso es Istvan?! ¡Se ve tan joven!",
  ui_story_5051_50510301_48_dialog_content = "¿Qué...?",
  ui_story_5051_50510301_49_dialog_content = "<color=#e8d9bb>Rumble—¡Choque!</color>",
  ui_story_5051_50510301_50_dialog_content = "(¿Trueno? ¿Va a haber tormenta en medio de un día despejado?)",
  ui_story_5051_50510301_51_dialog_content = "PlayerName! ¡¡Estar atento!!",
  ui_story_5051_50510301_52_dialog_content = "¡¿No me digas que hay más Eclipsitas?!",
  ui_story_5051_50510301_53_dialog_content = "¡Simplemente no hay fin para estos monstruos!",
  ui_story_5051_50510302_1_dialog_content = "Jajaja...",
  ui_story_5051_50510302_2_dialog_content = "Espero que no haya más de ellos. estoy en mi limite...",
  ui_story_5051_50510302_3_dialog_content = "Princesa <color=#FFB400>Verónica</color>! ¿Estás bien?",
  ui_story_5051_50510302_4_dialog_content = "¡Princesa Verónica! ¡Es realmente la princesa Verónica!",
  ui_story_5051_50510302_5_dialog_content = "¡¿Por qué estaría aquí, Su Alteza?!",
  ui_story_5051_50510302_6_dialog_content = "Yo, eh, estoy bien.",
  ui_story_5051_50510302_7_dialog_content = "Es bueno escuchar.",
  ui_story_5051_50510302_8_dialog_content = "Pero debo decir que esa demostración de fuerza y valentía no era propia de ti en absoluto.",
  ui_story_5051_50510302_9_dialog_content = "No me atreví a asumir tu identidad antes. Por favor, perdone mi ignorancia, Su Alteza.",
  ui_story_5051_50510302_10_dialog_content = "¡P-Por favor no digas eso!",
  ui_story_5051_50510302_11_dialog_content = "Hoy es solo una ocasión especial, eso es todo.",
  ui_story_5051_50510302_12_dialog_content = "(¿Eh? ¿Para qué me miras? Mia?)",
  ui_story_5051_50510302_13_dialog_content = "No podría estar más de acuerdo, por eso me confunde que estés aquí en primer lugar.",
  ui_story_5051_50510302_14_dialog_content = "Por otra parte... No me corresponde a mí preocuparme por esas cosas. Tenga más cuidado al poner un pie fuera de la ciudad, Su Alteza.",
  ui_story_5051_50510302_15_dialog_content = "G-Gracias por su preocupación.",
  ui_story_5051_50510302_16_dialog_content = "Caballero Schwartz y acabo de terminar nuestra reunión hace algún tiempo. Estábamos tan ocupados que no tuve tiempo de charlar con Lady Joshua.",
  ui_story_5051_50510302_17_dialog_content = "Por favor, dale mis más sinceras disculpas.",
  ui_story_5051_50510302_18_dialog_content = "Y si es posible... Por favor, pídele a tu padre que me dé su respuesta tan pronto como pueda.",
  ui_story_5051_50510302_19_dialog_content = "Muy bien... Me aseguraré de entregarles sus mensajes. Gracias de nuevo por toda su ayuda.",
  ui_story_5051_50510302_20_dialog_content = "Simplemente estoy haciendo lo correcto, Su Alteza. No son necesarias las gracias.",
  ui_story_5051_50510302_21_dialog_content = "(Entonces Mia realmente es una princesa!)",
  ui_story_5051_50510302_22_dialog_content = "Perdóname, joven.",
  ui_story_5051_50510302_23_dialog_content = "¿Yo?",
  ui_story_5051_50510302_24_dialog_content = "Sí tú. Solo puedo suponer que eres un amigo cercano de Su Alteza, ¿correcto?",
  ui_story_5051_50510302_25_dialog_content = "No cualquiera puede reclamar el honor de ser protegido por ella, ya sabes.",
  ui_story_5051_50510302_26_dialog_content = "Debe confiar en su propio poder para tener éxito en la vida.",
  ui_story_5051_50510302_27_dialog_content = "En lugar de esconderse detrás de otra persona.",
  ui_story_5051_50510302_28_dialog_content = "E-Está bien...",
  ui_story_5051_50510302_29_dialog_content = "Uh, perdóname, pero ¿nos hemos conocido en algún lugar antes?",
  ui_story_5051_50510302_30_dialog_content = "¡Jajaja! No esperaba escuchar eso como tu comentario de apertura, amigo mío.",
  ui_story_5051_50510302_31_dialog_content = "La respuesta es no.",
  ui_story_5051_50510302_32_dialog_content = "Pero si alguna vez deseas volver a encontrarte, siéntete libre de visitarme en Umbraton.",
  ui_story_5051_50510302_33_dialog_content = "Pronto, se convertirá en un imperio de sombras.",
  ui_story_5051_50510302_34_dialog_content = "Las sombras nos rodean a todos, pero si puedes o no sobrevivir en ellas depende de tu propia fuerza.",
  ui_story_5051_50510302_35_dialog_content = "Las sombras nos envuelven a todos... Cuanta razón tienes.",
  ui_story_5051_50510302_36_dialog_content = "Estoy seguro de que Umbraton se convertirá en un lugar mucho mejor bajo su liderazgo, tío... quiero decir, Sr. Istvan.",
  ui_story_5051_50510302_37_dialog_content = "Me siento honrado de recibir tales palabras de elogio de usted, milady.",
  ui_story_5051_50510302_38_dialog_content = "Se está haciendo tarde. Deberíamos estar en camino ahora.",
  ui_story_5051_50510302_39_dialog_content = "Hasta el próximo encuentro, Princesa Verónica. Tú también, mi interesante joven amigo.",
  ui_story_5051_50510302_40_dialog_content = "Cuídate... Ya sabes, esto Istvan parece mucho mejor que el que conozco.",
  ui_story_5051_50510302_41_dialog_content = "No voy a mentir, se siente bastante intrigante.",
  ui_story_5051_50510302_42_dialog_content = "Así es, recuerdo al tío Istvan siendo mucho más alegre en el pasado también.",
  ui_story_5051_50510302_43_dialog_content = "Pero con todo lo que ha pasado desde entonces... No sorprende que todo el mundo haya cambiado tanto.",
  ui_story_5051_50510302_44_dialog_content = "Así que realmente eres la princesa Verónica, ¿no?",
  ui_story_5051_50510302_45_dialog_content = "Cuando Istvan te llamó así, respondiste como si fuera lo más normal del mundo. Fue completamente diferente de sus respuestas habituales y tímidas.",
  ui_story_5051_50510302_46_dialog_content = "¿D-De veras?",
  ui_story_5051_50510302_47_dialog_content = "Todavía no he sido capaz de juntar todos mis recuerdos. Solo puedo recordar cositas del pasado en este momento.",
  ui_story_5051_50510302_48_dialog_content = "Pero por alguna razón, cuando vi al yo más joven del tío Istvan...",
  ui_story_5051_50510302_49_dialog_content = "Es como si mi cuerpo recordara el discurso y la etiqueta correctos antes de que mi mente pudiera ponerse al día.",
  ui_story_5051_50510302_50_dialog_content = "Lo siento, sé que eso no tiene mucho sentido.",
  ui_story_5051_50510302_51_dialog_content = "¡No te preocupes por eso! Vinimos a encontrar respuestas sobre su pasado, y ha sucedido mucho más de lo que esperábamos. Es normal que te sientas un poco confundido.",
  ui_story_5051_50510302_52_dialog_content = "¿Podrías contarme más sobre la princesa Verónica en tus recuerdos? Mia?",
  ui_story_5051_50510302_53_dialog_content = "No hay problema.",
  ui_story_5051_50510302_54_dialog_content = "Verónica era una <color=#FFB400>princesa</color> de Lumopolis, así como de Lord Schwartz <color=#FFB400>hija mayor</color>.",
  ui_story_5051_50510302_55_dialog_content = "Pero hace muchos años, Lumopolis declaró al resto del mundo que había <color=#FFB400>falleció</color>...",
  ui_story_5051_50510302_56_dialog_content = "¿Falleció? ¿Pero por qué?",
  ui_story_5051_50510302_57_dialog_content = "Porque ella había empañado el Schwartz la reputación de la familia.",
  ui_story_5051_50510302_58_dialog_content = "Como resultado de su desgracia, Verónica perdió el derecho a seguir viviendo.",
  ui_story_5051_50510302_59_dialog_content = "¿Reputación? ¿Desgracia? ¿Son esas cosas lo suficientemente importantes como para costarle la vida a alguien?",
  ui_story_5051_50510302_60_dialog_content = "Así es como opera la nobleza. Para ellos, nada es más importante que mantener su reputación...",
  ui_story_5051_50510302_61_dialog_content = "Sabes sobre <color=#FFB400>Invocaciones de Lumina</color>, bien PlayerName?",
  ui_story_5051_50510302_62_dialog_content = "Aparte de Baba Yaga, recuerdo tener otro amigo aterrador llamado Hippoca.",
  ui_story_5051_50510302_63_dialog_content = "Él era mi Lumina Summoning. De niño, quería volverme más fuerte más que cualquier otra cosa, así que entrené y entrené tan duro como pude...",
  ui_story_5051_50510302_64_dialog_content = "Y el resultado de mi entrenamiento fue Hippoca.",
  ui_story_5051_50510302_65_dialog_content = "Pero a todos les desagradaba su aspecto. Una araña con cabeza de caballo... Todos lo llamaban monstruo.",
  ui_story_5051_50510302_66_dialog_content = "Pero el que más lo odiaba... era mi padre. Siempre decía que Hippoca traía críticas injustificadas a nuestra familia.",
  ui_story_5051_50510302_67_dialog_content = "Que Hippoca era un mal augurio y que nunca debería haber existido... Al poco tiempo, también comencé a temerle.",
  ui_story_5051_50510302_68_dialog_content = "Hippoca era la manifestación de mis propios poderes, pero lo rechacé debido a la desaprobación de todos.",
  ui_story_5051_50510302_69_dialog_content = "Al final, perdí la capacidad de usar Luminatics.",
  ui_story_5051_50510302_70_dialog_content = "Y Baba Yaga, que comparte algunas similitudes con Hippoca, heredó mis poderes perdidos.",
  ui_story_5051_50510302_71_dialog_content = "En cierto modo, obtuve exactamente lo que merecía.",
  ui_story_5051_50510302_72_dialog_content = "Pobre princesa Verónica...",
  ui_story_5051_50510302_73_dialog_content = "Pero dado que todos aquí todavía te llaman por ese nombre, ¿significa esto...?",
  ui_story_5051_50510302_74_dialog_content = "¡Su Alteza! ¿Cómo podríamos pagarte por salvarnos la vida?",
  ui_story_5051_50510302_75_dialog_content = "N-No fue nada, de verdad.",
  ui_story_5051_50510302_76_dialog_content = "¿Todos están bien?",
  ui_story_5051_50510302_77_dialog_content = "Tranquilícese, Su Alteza. Gracias a ti, solo sufrimos heridas leves y estamos listos para continuar en cualquier momento.",
  ui_story_5051_50510302_78_dialog_content = "Usted y su amigo pueden viajar con nosotros de regreso a la ciudad, si lo desean.",
  ui_story_5051_50510302_79_dialog_content = "Eso sería maravilloso, gracias.",
  ui_story_5051_50510302_80_dialog_content = "Uh, perdóname, pero ¿podrías decirme qué año es?",
  ui_story_5051_50510302_81_dialog_content = "¿Qué año? Es <color=#FFB400>Calendario matutino año 1988</color>. ¿Por qué lo preguntas?",
  ui_story_5051_50510302_82_dialog_content = "(¿1988? Entonces eso significa... Esto es <color=#FFB400>doce años en el pasado</color>!)",
  ui_story_5051_50510302_83_dialog_content = "(Si es así, Eraveil ya habría sido destruido).",
  ui_story_5051_50510302_84_dialog_content = "(Esto significa que todavía no encontraré a ninguno de mis parientes dentro de este Cristal de la Memoria Eterna...)",
  ui_story_5051_50510302_85_dialog_content = "Hay algo mal, PlayerName?",
  ui_story_5051_50510302_86_dialog_content = "No es nada. Mia, ¿podrías venir aquí un segundo?",
  ui_story_5051_50510302_87_dialog_content = "¿Q-Qué es?",
  ui_story_5051_50510302_88_dialog_content = "Parece que el mundo dentro del cristal es <color=#FFB400>Lumopolis de hace doce años</color>.",
  ui_story_5051_50510302_89_dialog_content = "Si mi corazonada es correcta, los otros que estaban en la sala de recepción con nosotros también deberían haber sido transportados aquí.",
  ui_story_5051_50510302_90_dialog_content = "Sé Jakine dijo que se supone que no debemos interferir con el mundo que nos rodea.",
  ui_story_5051_50510302_91_dialog_content = "Pero no creo que tengamos elección. Ya no tenemos forma de escondernos aquí, y no puedo sentir a los demás con mis habilidades psíquicas.",
  ui_story_5051_50510302_92_dialog_content = "Deberíamos usar tu condición de princesa para encontrarlos y buscar un camino de regreso.",
  ui_story_5051_50510302_93_dialog_content = "...",
  ui_story_5051_50510302_94_dialog_content = "¿Qué te pasa, Mia?",
  ui_story_5051_50510302_95_dialog_content = "eh, PlayerName?",
  ui_story_5051_50510302_96_dialog_content = "¿E-Estaría bien si fuera a ver a mi madre por última vez antes de irnos?",
  ui_story_5051_50510302_97_dialog_content = "Cuando me escondía debajo de la mesa antes, los escuché decir que ella había fallecido mientras yo no estaba.",
  ui_story_5051_50510302_98_dialog_content = "Quería volver a Lumopolis para verla a ella ya mi hermana pequeña. Tenía tanto que quería compartir con ellos.",
  ui_story_5051_50510302_99_dialog_content = "Quería mostrarles que ya había crecido y que soy más valiente que antes, y contarles todo sobre los amigos que hice fuera de la ciudad.",
  ui_story_5051_50510302_100_dialog_content = "Y... quería decirle a mi madre que la extrañaba todos los días...",
  ui_story_5051_50510302_101_dialog_content = "Pero es muy tarde.",
  ui_story_5051_50510302_102_dialog_content = "... Tu madre es la esposa del Señor de la Ciudad.",
  ui_story_5051_50510302_103_dialog_content = "¡Si logramos encontrarla, estoy seguro de que podrá ayudarnos a regresar al mundo real!",
  ui_story_5051_50510302_104_dialog_content = "Hacerle una visita sería lo mejor para todos, ¿verdad?",
  ui_story_5051_50510302_105_dialog_content = "Oh, PlayerName? Parece que solo estás torciendo las cosas para que funcionen a nuestro favor...",
  ui_story_5051_50510302_106_dialog_content = "Jejeje, pero tiene sentido, ¿no?",
  ui_story_5051_50510302_107_dialog_content = "¡Puedes agradecer a todos nuestros amigos en Colossus por enseñarme cómo hacer esto!",
  ui_story_5051_50510302_108_dialog_content = "O-Está bien, entonces seguiré tu ejemplo.",
  ui_story_5051_50510302_109_dialog_content = "De alguna manera, esto se siente como si te estuviera dando un mal ejemplo, Mia...",
  ui_story_5051_50510302_110_dialog_content = "Perdóname, pero... ¿estás listo para irte? Estamos en un horario apretado.",
  ui_story_5051_50510302_111_dialog_content = "¡Ay, perdón por eso! ¡Estamos listos para ir cuando tú lo estés!",
  ui_story_5051_50510302_112_dialog_content = "Parece que tu equipo tiene prisa. ¿Podría decirnos qué está transportando?",
  ui_story_5051_50510302_113_dialog_content = "No es nada particularmente delicado, solo algunos artículos especiales que deben entregarse con anticipación. A saber...",
  ui_story_5051_50510302_114_dialog_content = "Artículos que se necesitan para este año <color=#FFB400>Schwartz Dia familiar</color>.",
  ui_story_5051_50510302_115_dialog_content = "(Schwartz ¿Dia familiar? Eso es demasiada coincidencia.)",
  ui_story_5051_50510302_116_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_5051_50510302_117_dialog_content = "Más truenos...",
  ui_story_5051_50510302_118_dialog_content = "¿Pasa algo?",
  ui_story_5051_50510302_119_dialog_content = "No nada. ¡Deberíamos irnos antes de que empiece a llover!",
  ui_story_5051_50510302_120_dialog_content = "¿Lluvia? No tenía idea de que iba a llover hoy. De todos modos, partiremos inmediatamente.",
  ui_story_5051_50510302_121_dialog_content = "<anim type=Shake><size=32>... Sch...</size></anim>",
  ui_story_5051_50510302_122_dialog_content = "<anim type=Shake><size=32>... Schwartz...</size></anim>",
  ui_story_5051_50510302_123_dialog_content = "<anim type=Shake><size=32>...</size></anim>",
  ui_story_5051_50510402_1_dialog_content = "...",
  ui_story_5051_50510402_2_dialog_content = "Hmph... Así que también hay eclipses al acecho en lugares como este.",
  ui_story_5051_50510402_3_dialog_content = "¿Desde cuándo Lumopolis se convirtió en un caldo de cultivo para estos miserables monstruos?",
  ui_story_5051_50510402_4_dialog_content = "¡Uf! ¡Estoy salvado!",
  ui_story_5051_50510402_5_dialog_content = "¡Gracias, Sr. Caleb! Si no hubiera sido porque apareciste justo a tiempo, habría sido la cena para esos Eclipsites...",
  ui_story_5051_50510402_6_dialog_content = "¡No, espera, haz ese almuerzo! Todavía es de día, después de todo.",
  ui_story_5051_50510402_7_dialog_content = "Estoy un poco confundido acerca de eso, también.",
  ui_story_5051_50510402_8_dialog_content = "Claramente era de noche cuando todavía estábamos en el palacio, señorita. Jakine.",
  ui_story_5051_50510402_9_dialog_content = "Pero ahora es de día y nos encontramos en medio de un bosque.",
  ui_story_5051_50510402_10_dialog_content = "¿Será que hemos sido transportados al Cristal de la Memoria Eterna?",
  ui_story_5051_50510402_11_dialog_content = "¡Así es! Aunque para ser completamente honesto, ¡no pensé que juntar un montón de encantamientos funcionaría tan bien!",
  ui_story_5051_50510402_12_dialog_content = "Tal vez soy un genio, después de todo...",
  ui_story_5051_50510402_13_dialog_content = "(Oh, sí, solo un genio podría haber hecho algo así...)",
  ui_story_5051_50510402_14_dialog_content = "A juzgar por esas estructuras en la distancia, parece que estamos en algún lugar en las afueras de Lower Lumopolis.",
  ui_story_5051_50510402_15_dialog_content = "En cuanto a esa caja, que acabas de aplastar al sentarte sobre ella—",
  ui_story_5051_50510402_16_dialog_content = "La etiqueta indica que fue preparado específicamente para Schwartz Dia familiar.",
  ui_story_5051_50510402_17_dialog_content = "¡Sí, y me asustó tontamente justo ahora!",
  ui_story_5051_50510402_18_dialog_content = "Parecía lo suficientemente resistente, ¡pero se rompió tan pronto como puse mi peso sobre él!",
  ui_story_5051_50510402_19_dialog_content = "¡¿Cómo se suponía que iba a saber que un montón de Eclipsites se acabarían?!",
  ui_story_5051_50510402_20_dialog_content = "¿Qué está pasando aquí? ¡¿No me digas que a la gente de Lumopolis le gusta tener estas cosas como mascotas?!",
  ui_story_5051_50510402_21_dialog_content = "Puedo asegurarles que mi gente no tiene absolutamente ningún interés en criar bestias violentas y sin mente como estas.",
  ui_story_5051_50510402_22_dialog_content = "Eclipsitos preparados solo para Schwartz Día de la familia... Ya veo. Esto debe ser Lumopolis de hace doce años.",
  ui_story_5051_50510402_23_dialog_content = "Cajas de almacenamiento de Eclipsites en un transporte lleno de mercancías para el Schwartz familia... Un movimiento audaz por parte de los culpables detrás de este ataque.",
  ui_story_5051_50510402_24_dialog_content = "Espera... ¿Eso significa que los Eclipsites lograron invadir Lumopolis hace doce años?",
  ui_story_5051_50510402_25_dialog_content = "Así es. Si bien no sé con certeza cómo ve el resto del mundo nuestro bastión en el cielo...",
  ui_story_5051_50510402_26_dialog_content = "En realidad, no es tan impenetrable como parece.",
  ui_story_5051_50510402_27_dialog_content = "Oh, Sr. Caleb...",
  ui_story_5051_50510402_28_dialog_content = "¿Viste a alguien más antes de que nos encontráramos?",
  ui_story_5051_50510402_29_dialog_content = "No. De hecho, acababa de despertarme cuando nuestros caminos se cruzaron.",
  ui_story_5051_50510402_30_dialog_content = "Oh. Jajaja... Bueno, se suponía que el encantamiento nos teletransportaría a todos al mismo lugar.",
  ui_story_5051_50510402_31_dialog_content = "Además de eso, los Eclipsites aquí no deberían haber sido capaces de notarnos.",
  ui_story_5051_50510402_32_dialog_content = "¡Parece que cometí un pequeño error, después de todo!",
  ui_story_5051_50510402_33_dialog_content = "... Extrañar Jakine, siento que debo preguntarte algo.",
  ui_story_5051_50510402_34_dialog_content = "A-Ejem! ¡Pero no te preocupes! ¡Asumiré toda la responsabilidad y me aseguraré de que todos regresen sanos y salvos!",
  ui_story_5051_50510402_35_dialog_content = "Eso no es lo que iba a preguntar.",
  ui_story_5051_50510402_36_dialog_content = "La Lumina de la persona que activó este Cristal de la Memoria Eterna... ¿Está por aquí?",
  ui_story_5051_50510402_37_dialog_content = "¡Sí, por supuesto que lo es!",
  ui_story_5051_50510402_38_dialog_content = "¿Sabes dónde, exactamente?",
  ui_story_5051_50510402_39_dialog_content = "¿Q-Quieres saber dónde está? Déjeme ver...",
  ui_story_5051_50510402_40_dialog_content = "\"El Cristal de la Memoria Eterna debe activarse con la Lumina de su dueño. Es la fuente de poder que mantiene el mundo dentro del cristal\".",
  ui_story_5051_50510402_41_dialog_content = "<size=30>¿Es eso realmente todo?</size>",
  ui_story_5051_50510402_42_dialog_content = "¡A-Ejem! En mi opinión profesional, ¡el Lumina utilizado para alimentar este mundo entero probablemente esté alojado en algún lugar extremadamente importante!",
  ui_story_5051_50510402_43_dialog_content = "Y el lugar más importante en el que puedo pensar—",
  ui_story_5051_50510402_44_dialog_content = "¡Es el Cristal de la Memoria Eterna dentro de este mundo!",
  ui_story_5051_50510402_45_dialog_content = "Supongo que tiene sentido...",
  ui_story_5051_50510402_46_dialog_content = "Tengo otra pregunta. Si Lumina es lo que sostiene este mundo, entonces, naturalmente, algún día tendría que agotarse, ¿no?",
  ui_story_5051_50510402_47_dialog_content = "Ya han pasado doce años desde que se activó este cristal. ¿Cuánto tiempo más tiene?",
  ui_story_5051_50510402_48_dialog_content = "¡Oh, no hay necesidad de preocuparse por eso!",
  ui_story_5051_50510402_49_dialog_content = "¡Mientras un cristal se reponga con agua del lago Mirror una vez cada doce años, su Lumina no se desvanecerá por mucho, mucho tiempo!",
  ui_story_5051_50510402_50_dialog_content = "Sin embargo, alterar el orden de las cosas en el mundo de un cristal puede acelerar fácilmente su consumo de Lumina.",
  ui_story_5051_50510402_51_dialog_content = "En casos extremos, una sola acción puede hacer que agote toda su Lumina en un instante.",
  ui_story_5051_50510402_52_dialog_content = "¡Si eso sucede, no puedo garantizar que sobreviviremos!",
  ui_story_5051_50510402_53_dialog_content = "¿Es esto lo que quiso decir con una \"catástrofe inimaginable\"?",
  ui_story_5051_50510402_54_dialog_content = "Sí, más o menos. Naturalmente, también puede haber otras consecuencias no deseadas...",
  ui_story_5051_50510402_55_dialog_content = "¡Es por eso que necesitamos encontrar a los demás de inmediato!",
  ui_story_5051_50510402_56_dialog_content = "No podemos quedarnos mucho tiempo en lugares donde no podemos ocultarnos.",
  ui_story_5051_50510402_57_dialog_content = "Tiene toda la razón, por eso dejo esta importante tarea en sus \"capaces\" manos, señorita. Jakine.",
  ui_story_5051_50510402_58_dialog_content = "Tengo otros asuntos que atender. Toda la suerte.",
  ui_story_5051_50510402_59_dialog_content = "¡¿Eh?! ¡Espera, no puedes tirarme esto encima y marcharte así!",
  ui_story_5051_50510402_60_dialog_content = "Además, ¿no acabo de decir que tenemos que tener cuidado? ¡Cambiar incluso la cosa más pequeña en este mundo podría significar un desastre para todos nosotros!",
  ui_story_5051_50510402_61_dialog_content = "Lo hiciste, y no tengo intención de romper las reglas. Los demás, sin embargo, requieren su estrecha supervisión.",
  ui_story_5051_50510402_62_dialog_content = "Todavía queda un poco de Lumina en este mundo. Preferiría mantenerlo así hasta que estemos a salvo.",
  ui_story_5051_50510402_63_dialog_content = "Uf, ¿no estás escuchando? Tú mismo lo dijiste: ¡esto es Lumopolis! ¡¿Qué vas a hacer si te encuentras con tu yo del pasado?!",
  ui_story_5051_50510402_64_dialog_content = "No te preocupes por eso. En este día, estaba escoltando a mi sobrina a Umbraton, junto con varios de nuestros caballeros. No estaba cerca de la ciudad.",
  ui_story_5051_50510402_65_dialog_content = "¿Seguramente el alcance del Cristal de la Memoria Eterna no llega tan lejos?",
  ui_story_5051_50510402_66_dialog_content = "Bueno, eso también es un hecho...",
  ui_story_5051_50510402_67_dialog_content = "Planeo entrar en la ciudad disfrazado de invitado. Iré a buscarte una vez que haya tenido la oportunidad de ver a alguien.",
  ui_story_5051_50510402_68_dialog_content = "¿Entonces estás dispuesto a arriesgar todas nuestras vidas solo para ver a esta persona?",
  ui_story_5051_50510402_69_dialog_content = "Precisamente. Si bien nunca podemos volver verdaderamente al pasado, ¿con qué frecuencia tenemos la oportunidad de recuperar lo que se perdió?",
  ui_story_5051_50510402_70_dialog_content = "Por favor, reúna a los demás lo más rápido que pueda, señorita. Jakine. Despedida.",
  ui_story_5051_50510402_71_dialog_content = "¡Esperar! ¡Ni siquiera me has dicho dónde se supone que nos encontraremos más tarde!",
  ui_story_5051_50510402_72_dialog_content = "Genial, ya se fue...",
  ui_story_5051_50510402_73_dialog_content = "¿Qué pasó con esa persona tan refinada y caballerosa? ¿Fue todo solo un acto?",
  ui_story_5051_50510402_74_dialog_content = "¡¿Cómo podía ser tan egoísta y desconsiderado en un momento como este?!",
  ui_story_5051_50510402_75_dialog_content = "Ahhh, ¡estoy tan enojado que podría escupir!",
  ui_story_5051_50510402_76_dialog_content = "Suspiro... \"La oportunidad de recuperar lo que se perdió\", ¿eh?",
  ui_story_5051_50510402_77_dialog_content = "Me pregunto si tendré ese tipo de oportunidad también.",
  ui_story_5051_50510402_78_dialog_content = "Mamá... Hace doce años, viniste a Lumopolis para entregar este Cristal de la Memoria Eterna al Señor de la Ciudad, y luego regresaste directamente a Northland.",
  ui_story_5051_50510402_79_dialog_content = "Papá siempre decía que nunca podría entenderte. Dejar atrás a tu familia para practicar la adivinación, huir a las montañas sin siquiera despedirte.",
  ui_story_5051_50510402_80_dialog_content = "Pero Su Majestad dice que eres un genio y ascendiste más allá de nuestras limitaciones mundanas... En ese sentido, supongo que no nos parecemos en nada.",
  ui_story_5051_50510402_81_dialog_content = "Me pregunto qué dirías si nos viéramos aquí.",
  ui_story_5051_50510402_82_dialog_content = "... ¡¿Qué estoy pensando?!",
  ui_story_5051_50510402_83_dialog_content = "Enfocar, Jakine! Estás aquí como enviado de Northland, ¿recuerdas?",
  ui_story_5051_50510402_84_dialog_content = "¡No puedes confiar en nadie más que en ti mismo ahora mismo! ¡Es tu trabajo sacar a todos de aquí a salvo!",
  ui_story_5051_50510402_85_dialog_content = "*inhala exhala*",
  ui_story_5051_50510402_86_dialog_content = "¡Está bien! Enviado de las Tierras del Norte Jakine está listo para rodar!",
  ui_story_5051_50510501_1_dialog_content = "(No hay muchos lugares donde Schwartz podría haber escondido el Cristal de la Memoria Eterna. Si no me equivoco, debería estar en algún lugar de su casa).",
  ui_story_5051_50510501_2_dialog_content = "(El banquete del Día de la Familia de este año fue mucho más grande, por lo que la mayoría de los guardias se colocaron allí para ayudar a mantener el orden).",
  ui_story_5051_50510501_3_dialog_content = "(Una vez que comience la ceremonia festiva, debería poder colarme a través de una de las áreas menos vigiladas).",
  ui_story_5051_50510501_4_dialog_content = "(Hasta entonces, solo necesito mantener un perfil bajo y esperar pacientemente).",
  ui_story_5051_50510501_5_dialog_content = "(El jardín de allí debería estar bastante vacío...)",
  ui_story_5051_50510501_6_dialog_content = "(Iris... Un símbolo de buenas noticias, así como de añoranza.)",
  ui_story_5051_50510501_7_dialog_content = "(Recuerdo que mi hermana plantó estos solo para su hija mayor).",
  ui_story_5051_50510501_8_dialog_content = "... Sé que vuestro tiempo está por terminar, pequeños.",
  ui_story_5051_50510501_9_dialog_content = "Pero, ¿podrías guardar tus flores por unos días más?",
  ui_story_5051_50510501_10_dialog_content = "Mi hija estará pronto en casa. Me encantaría que tuviera la oportunidad de ver tu belleza.",
  ui_story_5051_50510501_11_dialog_content = "Ella solía ser tan aficionada a las flores. Estoy seguro de que volvería a sonreír al verte.",
  ui_story_5051_50510501_12_dialog_content = "¿Eres... eres realmente tú...?",
  ui_story_5051_50510501_13_dialog_content = "<color=#FFB400>Josué</color>...?",
  ui_story_5051_50510501_14_dialog_content = "¡Oh!",
  ui_story_5051_50510501_15_dialog_content = "Hola, señor.",
  ui_story_5051_50510501_16_dialog_content = "¿Qué te trae a mi jardín en esta hermosa tarde?",
  ui_story_5051_50510501_17_dialog_content = "Er, perdóname por preguntar, pero...",
  ui_story_5051_50510501_18_dialog_content = "¿Nos conocemos?",
  ui_story_5051_50510501_19_dialog_content = "... Me temo que no. No soy más que un noble de bajo rango, que no merece tal honor.",
  ui_story_5051_50510501_20_dialog_content = "Pero aun así, es un placer conocerla, Lady Joshua.",
  ui_story_5051_50510501_21_dialog_content = "¿En serio?",
  ui_story_5051_50510501_22_dialog_content = "Podría haber jurado... No importa, mis ojos deben estar jugando una mala pasada.",
  ui_story_5051_50510501_23_dialog_content = "(Josué...)",
  ui_story_5051_50510501_24_dialog_content = "(Solo le estaba mintiendo a ese adivino de Northland acerca de ver a alguien).",
  ui_story_5051_50510501_25_dialog_content = "(En verdad, nunca esperé verte aquí).",
  ui_story_5051_50510501_26_dialog_content = "(Después de doce años, finalmente tengo la oportunidad de volver a hablar contigo).",
  ui_story_5051_50510501_27_dialog_content = "(Y sin embargo, solo puedo hacerlo fingiendo ser un extraño...)",
  ui_story_5051_50510501_28_dialog_content = "(Vine a este mundo para recuperar la Lumina que mi hermana dejó atrás).",
  ui_story_5051_50510501_29_dialog_content = "(Todo esto es solo una ilusión creada por los trucos secretos de Northland. No puedo dejar que me distraiga de mi objetivo).",
  ui_story_5051_50510501_30_dialog_content = "(¡Necesito poner fin a esta farsa, de una vez por todas...!)",
  ui_story_5051_50510501_31_dialog_content = "¿Estás bien? Parece que te duele...",
  ui_story_5051_50510501_32_dialog_content = "Mis disculpas.",
  ui_story_5051_50510501_33_dialog_content = "Simplemente estoy incrédulo ante mi propia buena fortuna, que he sido bendecido con la oportunidad de conocerte.",
  ui_story_5051_50510501_34_dialog_content = "Vaya, esa es una mentira bastante halagadora.",
  ui_story_5051_50510501_35_dialog_content = "Las lágrimas en las esquinas de tus ojos dicen lo contrario. ¿Te duele en alguna parte, por casualidad? ¿O tal vez tu dolor reside en tu corazón?",
  ui_story_5051_50510501_36_dialog_content = "No deberías soportarlo todo tú solo, lo sabes.",
  ui_story_5051_50510501_37_dialog_content = "...",
  ui_story_5051_50510501_38_dialog_content = "¡Dije que estoy bien!",
  ui_story_5051_50510501_39_dialog_content = "¡Solo tengo algo en mi ojo!",
  ui_story_5051_50510501_40_dialog_content = "Qué saben ellos de todos modos... ¡Todos en esa academia son idiotas! ¡Los profesores, los alumnos, todos ellos!",
  ui_story_5051_50510501_41_dialog_content = "Siempre diciendo cosas como: \"Puede que seas inteligente, Caleb, pero sin tus padres, te has vuelto altivo y arrogante\".",
  ui_story_5051_50510501_42_dialog_content = "<size=30>¿Y qué si ya no tengo a mis padres? La única persona que necesito es mi hermana...</size>",
  ui_story_5051_50510501_43_dialog_content = "¡Algún día, voy a cambiar todo sobre este lugar! ¡Solo espera!",
  ui_story_5051_50510501_44_dialog_content = "Yo creo en ti, Caleb.",
  ui_story_5051_50510501_45_dialog_content = "Nunca has sido de los que alardean. Sé que puedes lograr cualquier cosa que te propongas.",
  ui_story_5051_50510501_46_dialog_content = "¿De verdad crees en mí?",
  ui_story_5051_50510501_47_dialog_content = "Por supuesto que sí.",
  ui_story_5051_50510501_48_dialog_content = "Gracias... Dime algo, Joshua. Si alguna vez llega un día en que nadie tiene que preocuparse por la comida o la seguridad nunca más...",
  ui_story_5051_50510501_49_dialog_content = "¿Significa eso que ya no tendrás que seguir ayudando a Daniel?",
  ui_story_5051_50510501_50_dialog_content = "Hmm... Si bien es cierto que nuestras vidas serían mucho más simples si eso sucediera, tengo el deber de estar con él. Él es mi marido, después de todo.",
  ui_story_5051_50510501_51_dialog_content = "...",
  ui_story_5051_50510501_52_dialog_content = "Pero si ese día llegara, prometo que lo ayudaré con toda su investigación y asistiré a cada una de sus presentaciones. ¿Como suena eso?",
  ui_story_5051_50510501_53_dialog_content = "¿En serio?",
  ui_story_5051_50510501_54_dialog_content = "En serio.",
  ui_story_5051_50510501_55_dialog_content = "Entonces... ¡Entonces presentaré mi investigación por todo el mundo!",
  ui_story_5051_50510501_56_dialog_content = "Solías decir que querías viajar por el mundo todo el tiempo, pero no has hablado de eso desde que te casaste.",
  ui_story_5051_50510501_57_dialog_content = "Así que voy a hacer todo lo posible para que tu sueño se haga realidad.",
  ui_story_5051_50510501_58_dialog_content = "Oh, parece que me han engañado de nuevo. ¿Qué voy a hacer contigo, Caleb?",
  ui_story_5051_50510501_59_dialog_content = "¡Ya prometiste que vendrías a todas mis presentaciones! ¡No retrocedas en tu palabra ahora!",
  ui_story_5051_50510501_60_dialog_content = "Sé que sé. Es un trato, entonces.",
  ui_story_5051_50510501_61_dialog_content = "Yo... solo tengo algo en mi ojo.",
  ui_story_5051_50510501_62_dialog_content = "No me parece. Solo mírate, arrugando la nariz para ocultar tu tristeza.",
  ui_story_5051_50510501_63_dialog_content = "Te pareces a mi hermano menor...",
  ui_story_5051_50510501_64_dialog_content = "Posee un intelecto mucho más allá de su edad, pero no es diferente a un niño pequeño y dulce en muchos sentidos.",
  ui_story_5051_50510501_65_dialog_content = "Por ejemplo, cada vez que llora, miente diciendo que tiene algo en el ojo.",
  ui_story_5051_50510501_66_dialog_content = "... Oh, pero ¿dónde están mis modales?",
  ui_story_5051_50510501_67_dialog_content = "Por favor, perdóneme por hablarle tan casualmente, señor. Es que me recordabas mucho a mi hermano.",
  ui_story_5051_50510501_68_dialog_content = "Debería estar avergonzado de haberte tratado tan irrespetuosamente.",
  ui_story_5051_50510501_69_dialog_content = "N-No hay necesidad de disculparse...",
  ui_story_5051_50510501_70_dialog_content = "Aún así, se siente tan extraño. Los dos están tan separados en edad...",
  ui_story_5051_50510501_71_dialog_content = "Y sin embargo, de alguna manera, puedo sentir su presencia sobre ti.",
  ui_story_5051_50510501_72_dialog_content = "De todos modos, me gustaría enmendar mi rudeza en este momento. Únase a nosotros como invitado de honor para nuestro banquete esta noche.",
  ui_story_5051_50510501_73_dialog_content = "Si alguien cuestiona su presencia en nuestra mesa, solo necesita mencionar mi nombre.",
  ui_story_5051_50510501_74_dialog_content = "Y si te encuentras en algún problema, siempre puedes acudir a mí.",
  ui_story_5051_50510501_75_dialog_content = "Nadie debe soportar ningún tipo de sufrimiento por su cuenta.",
  ui_story_5051_50510501_76_dialog_content = "Gracias por su amable oferta, pero siento que debo rechazarla. Vine aquí por negocios y, en primer lugar, no tenía intención de asistir al banquete.",
  ui_story_5051_50510501_77_dialog_content = "Es solo que estas flores me trajeron a la mente algunos buenos recuerdos, y no pude evitar quedarme un rato. Perdóneme por molestarlo, Su Alteza.",
  ui_story_5051_50510501_78_dialog_content = "Con su permiso, debo irme ahora... Cuídese, Lady Joshua.",
  ui_story_5051_50510501_79_dialog_content = "Oh, parece que tienes bastante prisa...",
  ui_story_5051_50510501_80_dialog_content = "May ¿Al menos sé tu nombre?",
  ui_story_5051_50510501_81_dialog_content = "Aunque las personas son diferentes en este mundo...",
  ui_story_5051_50510501_82_dialog_content = "Lumopolis es siempre el mismo.",
  ui_story_5051_50510501_83_dialog_content = "Es cierto. La santidad y la estabilidad son los sellos distintivos de Lumopolis, así como la fuente de la fe de su gente.",
  ui_story_5051_50510501_84_dialog_content = "Es por eso que la gente se ha sacrificado tanto a lo largo de los años para proteger su pureza... Al final, ver su majestuosidad en el cielo hace que todo valga la pena.",
  ui_story_5051_50510501_85_dialog_content = "Por favor presente sus pases de entrada. ¡Eso significa que tú, chico!",
  ui_story_5051_50510501_86_dialog_content = "Oh, yo...",
  ui_story_5051_50510501_87_dialog_content = "Lo siento, es un amigo mío.",
  ui_story_5051_50510501_88_dialog_content = "¿P-princesa Verónica?",
  ui_story_5051_50510501_89_dialog_content = "¡Perdone mi ignorancia, Su Alteza! ¡Ve siempre derecho!",
  ui_story_5051_50510501_90_dialog_content = "No es problema en absoluto. Gracias por velar por nuestra bella ciudad.",
  ui_story_5051_50510501_91_dialog_content = "¡E-Es mi honor!",
  ui_story_5051_50510501_92_dialog_content = "¡Uf! ¡Tener una princesa cerca seguro viene muy bien!",
  ui_story_5051_50510501_93_dialog_content = "La última vez que me detuvieron en las puertas, también tuve que usar el nombre de Carleen para pasar...",
  ui_story_5051_50510501_94_dialog_content = "Está bien, PlayerName. Eres una buena persona, por eso todos siempre están dispuestos a ayudarte.",
  ui_story_5051_50510501_95_dialog_content = "R-¿En serio? Jejeje, no puedo evitar sentirme un poco avergonzado...",
  ui_story_5051_50510501_96_dialog_content = "¡Ay, eso me recuerda! ¡Espera un segundo!",
  ui_story_5051_50510501_97_dialog_content = "Perdóname, pero ¿has visto a nuestros amigos pasar por las puertas hoy? Uno de ellos es un señor mayor de aspecto serio con cabello blanco y un parche en el ojo, el otro es un joven noble con cabello rubio y ojos violetas...",
  ui_story_5051_50510501_98_dialog_content = "¡Ah, y también había un maestro de adivinación pelirrojo de Northland con ellos! ¿Sabes si están en Lumopolis?",
  ui_story_5051_50510501_99_dialog_content = "No he visto los dos primeros, lo siento.",
  ui_story_5051_50510501_100_dialog_content = "Pero ayer llegó un enviado de Northland y parece encajar con su descripción.",
  ui_story_5051_50510501_101_dialog_content = "(¿Un enviado de Northland? Ese debe ser el predecesor de Jakine).",
  ui_story_5051_50510501_102_dialog_content = "Comprendido. ¡Gracias por tu tiempo!",
  ui_story_5051_50510501_103_dialog_content = "Está todo bien, PlayerName?",
  ui_story_5051_50510501_104_dialog_content = "Solo le pregunté al guardia si había visto a los demás, pero parece que no.",
  ui_story_5051_50510501_105_dialog_content = "Supongo que tendremos que encontrarlos nosotros mismos.",
  ui_story_5051_50510501_106_dialog_content = "—!!!",
  ui_story_5051_50510501_107_dialog_content = "¡Eclipsitos! ¡¿Cómo entraron en la carga?!",
  ui_story_5051_50510501_108_dialog_content = "¡¿Aquí también hay eclipses?!",
  ui_story_5051_50510501_109_dialog_content = "¡N-No te preocupes, yo me encargaré de ellos...!",
  ui_story_5051_50510502_1_dialog_content = "¿Cuál es la situación?",
  ui_story_5051_50510502_2_dialog_content = "Capitán <color=#FFB400>Mímica</color>! ¡Varios eclipses estaban ocultos dentro de un envío recibido recientemente y nos emboscaron al ser descubiertos!",
  ui_story_5051_50510502_3_dialog_content = "El vendedor a cargo del envío ya fue detenido para ser interrogado. No se han reportado víctimas.",
  ui_story_5051_50510502_4_dialog_content = "Y en el día del banquete del Día de la Familia, de todos los días.",
  ui_story_5051_50510502_5_dialog_content = "Que me entreguen a los sospechosos. Por cometer un crimen tan atroz, yo mismo los escoltaré al Salón de la Justicia.",
  ui_story_5051_50510502_6_dialog_content = "¡Sí señor!",
  ui_story_5051_50510502_7_dialog_content = "¿Qué pasa con los eclipses? ¿Todos ellos han sido eliminados?",
  ui_story_5051_50510502_8_dialog_content = "¡Sí, señor! ¡Ni uno solo logró escapar!",
  ui_story_5051_50510502_9_dialog_content = "¡Y todo fue gracias a la Princesa Verónica, nada menos!",
  ui_story_5051_50510502_10_dialog_content = "¡La princesa Verónica fue absolutamente increíble!",
  ui_story_5051_50510502_11_dialog_content = "Pero pensé princesa Carleen ¿Estaba el guerrero entre los dos?",
  ui_story_5051_50510502_12_dialog_content = "¡No no no! ¡Esa era la princesa Verónica hace un momento, sin duda!",
  ui_story_5051_50510502_13_dialog_content = "No tenía idea de que ella también fuera tan talentosa. El Schwartz La familia está verdaderamente bendecida de tener hijos tan talentosos...",
  ui_story_5051_50510502_14_dialog_content = "<size=30>Oh, PlayerName? Todo el mundo sigue mirando... Está empezando a asustarme.</size>",
  ui_story_5051_50510502_15_dialog_content = "Eso es porque eres el héroe de todos, Mia!",
  ui_story_5051_50510502_16_dialog_content = "¡Limpiaste el piso con esos Eclipsites como lo has estado haciendo toda tu vida!",
  ui_story_5051_50510502_17_dialog_content = "¿Era... realmente tan impresionante?",
  ui_story_5051_50510502_18_dialog_content = "¡Por supuesto que lo estabas!",
  ui_story_5051_50510502_19_dialog_content = "Oh, está bien... Gracias...",
  ui_story_5051_50510502_20_dialog_content = "Buen trabajo, todos. Puede dejar al sospechoso con nosotros ahora.",
  ui_story_5051_50510502_21_dialog_content = "Comprendido. Gracias por su ayuda.",
  ui_story_5051_50510502_22_dialog_content = "(Espera un segundo...)",
  ui_story_5051_50510502_23_dialog_content = "(Es eso <color=#FFB400>Sharona</color>?!)",
  ui_story_5051_50510502_24_dialog_content = "¡Tú allí! ¿Quién eres y por qué me miras así?",
  ui_story_5051_50510502_25_dialog_content = "Si necesita ayuda, solo tiene que preguntar. Puede que solo sea un caballero de reserva, pero estoy obligado a prestar mi ayuda, de todos modos.",
  ui_story_5051_50510502_26_dialog_content = "Si no tiene más asuntos que atender aquí, le sugiero que se ponga en camino ahora.",
  ui_story_5051_50510502_27_dialog_content = "(¡Mierda, ella me vio! ¡Tenemos que salir de aquí antes de interferir demasiado con el pasado!)",
  ui_story_5051_50510502_28_dialog_content = "(Sin embargo, si esto fue hace doce años, ¿no significa eso Sharona solo tiene catorce años? Supongo que siempre ha sido así de seria, eh.)",
  ui_story_5051_50510502_29_dialog_content = "N-No es nada, lo siento. Tus ojos parecían un poco familiares, eso es todo.",
  ui_story_5051_50510502_30_dialog_content = "¿Mis ojos, dices? Que cliché.",
  ui_story_5051_50510502_31_dialog_content = "Deberías guardar ese tipo de conversación para alguien que realmente quiera escucharla.",
  ui_story_5051_50510502_32_dialog_content = "Jaja... De nuevo, siento molestarte.",
  ui_story_5051_50510502_33_dialog_content = "Si nuestros caminos se vuelven a cruzar, quizás tenga más tiempo para escuchar tus locas divagaciones.",
  ui_story_5051_50510502_34_dialog_content = "Siéntete libre de seguir esperando que llegue ese día, forastero.",
  ui_story_5051_50510502_35_dialog_content = "No te preocupes, ¡sé que algún día nos volveremos a encontrar!",
  ui_story_5051_50510502_36_dialog_content = "(¡Después de todo, resulta que soy muy buen amigo del futuro tú!)",
  ui_story_5051_50510502_37_dialog_content = "Hmph. Lunático...",
  ui_story_5051_50510502_38_dialog_content = "Oye, mira eso, Sharona entabló una conversación en su patrulla!",
  ui_story_5051_50510502_39_dialog_content = "Ella es solo una adolescente, es parte del curso.",
  ui_story_5051_50510502_40_dialog_content = "Tienes razón. Suele ser tan precoz que duele verla tan tensa.",
  ui_story_5051_50510502_41_dialog_content = "Suspiro, me encantaría escabullirme para ver el desfile...",
  ui_story_5051_50510502_42_dialog_content = "<size=45>¡Caballeros!</size>",
  ui_story_5051_50510502_43_dialog_content = "Hoy es un tiempo alegre de celebración para toda nuestra ciudad. Como miembros de la prestigiosa familia Kartima, se nos ha confiado la seguridad de nuestra gente.",
  ui_story_5051_50510502_44_dialog_content = "Como tal, ¡deben comportarse con dignidad y profesionalismo al cumplir con sus órdenes!",
  ui_story_5051_50510502_45_dialog_content = "...",
  ui_story_5051_50510502_46_dialog_content = "(Jajaja... Incluso después de todos estos años, parece que Sharona no ha cambiado nada).",
  ui_story_5051_50510502_47_dialog_content = "eh, PlayerName? El Sr. Mime dice que puede acompañarnos a ver a mi madre.",
  ui_story_5051_50510502_48_dialog_content = "N-No deberíamos perder más el tiempo hablando con esa chica. Vamos.",
  ui_story_5051_50510502_49_dialog_content = "(Vaya, supongo que dejé que el ambiente festivo sacara lo mejor de mí...)",
  ui_story_5051_50510502_50_dialog_content = "(Todavía estamos en grave peligro. No puedo seguir bajando la guardia así).",
  ui_story_5051_50510502_51_dialog_content = "Lo siento, estaba siendo descuidado en este momento. Haré todo lo posible por no hablar con nadie más si no es necesario.",
  ui_story_5051_50510502_52_dialog_content = "Eso no es lo que quise decir. Es solo... Uf, realmente no sé cómo describir este sentimiento.",
  ui_story_5051_50510502_53_dialog_content = "Mi pecho se siente apretado, y mi corazón... me duele un poco.",
  ui_story_5051_50510502_54_dialog_content = "Oh no, ¿estás bien? ¡Ah, si tan solo pudiera usar mis poderes ahora mismo!",
  ui_story_5051_50510502_55_dialog_content = "Entonces podría mirar dentro de tu mente y ver si estás bien...",
  ui_story_5051_50510502_56_dialog_content = "¡N-De ninguna manera! ¡Por favor, no mires dentro de mi mente ahora mismo...!",
  ui_story_5051_50510502_57_dialog_content = "Oh, PlayerName! ¡Por lo inteligente que eres, a veces puedes ser muy denso!",
  ui_story_5051_50510502_58_dialog_content = "Genial. Oh, tengo que pedirles un favor a los Lumo Knights. ¡Vuelvo enseguida!",
  ui_story_5051_50510502_59_dialog_content = "¿Eh? PlayerName?",
  ui_story_5051_50510502_60_dialog_content = "¡Hola! Sr. Mime, ¿supongo?",
  ui_story_5051_50510502_61_dialog_content = "El uno y el mismo. ¿Necesitas algo?",
  ui_story_5051_50510502_62_dialog_content = "Estoy buscando a mis tres amigos. Todos somos invitados de la princesa Verónica, pero nos separamos de camino aquí.",
  ui_story_5051_50510502_63_dialog_content = "¿Sería posible que tú y tus caballeros nos ayudarais a encontrarlos? Aquí hay una descripción de cómo se ven...",
  ui_story_5051_50510502_64_dialog_content = "Muy bien, haremos lo que podamos. Todavía tengo que informar al Señor de la Ciudad, así que si me disculpan.",
  ui_story_5051_50510502_65_dialog_content = "Gracias, Sr. Mimo.",
  ui_story_5051_50510502_66_dialog_content = "Uh, cuando veas a mi padre más tarde, ¿no puedes mencionar a mi amigo y lo que pasó...?",
  ui_story_5051_50510502_67_dialog_content = "Si eso es todo lo que me pides, entonces no veo ningún problema en hacer lo que deseas.",
  ui_story_5051_50510502_68_dialog_content = "Sin embargo, mis caballeros siguen siendo responsables de patrullar la ciudad durante las vacaciones. A cambio, debo pedirte que tú y tus amigos eviten causar problemas hoy.",
  ui_story_5051_50510502_69_dialog_content = "Entiendo. Te prometo que nos portaremos lo mejor posible.",
  ui_story_5051_50510502_70_dialog_content = "¿Ya terminaste? Mia?",
  ui_story_5051_50510502_71_dialog_content = "¡Sí! Solo me aseguré de que el Sr. Mime no le mencionara a mi padre en su informe.",
  ui_story_5051_50510502_72_dialog_content = "Después de todo, se supone que debo estar en un montón de problemas hoy. Si se enteraba de que estaba de vuelta en la ciudad, se pondría furioso...",
  ui_story_5051_50510502_73_dialog_content = "¿Verónica?",
  ui_story_5051_50510502_74_dialog_content = "Madre...?",
  ui_story_5051_50510502_75_dialog_content = "¡Madre!",
  ui_story_5051_50510502_76_dialog_content = "¡Ay, mi niña! ¿Qué pasa?",
  ui_story_5051_50510502_77_dialog_content = "Madre... ¡Realmente eres tú! Oh, te extraño tanto, madre...",
  ui_story_5051_50510502_78_dialog_content = "Yo tambien, querido. Pero no te preocupes, ya estoy aquí.",
  ui_story_5051_50510502_79_dialog_content = "Déjame echarte un vistazo. ¿Los Lumo Knights te lastimaron durante tu entrenamiento?",
  ui_story_5051_50510502_80_dialog_content = "O tal vez... ¿Te peleaste con uno de tus amigos?",
  ui_story_5051_50510502_81_dialog_content = "(¡Me está mirando directamente a mí! ¡La mamá de Mia piensa que yo le hice eso! ¡No, no, lo entendiste todo mal! ¡No fui yo!)",
  ui_story_5051_50510502_82_dialog_content = "No madre, PlayerName nunca haría algo así. Él me trajo aquí para verte...",
  ui_story_5051_50510502_83_dialog_content = "Veo. Parece que has hecho un muy buen amigo, mi amor.",
  ui_story_5051_50510502_84_dialog_content = "¿Mmm? ¿Qué pasó con tus rodillas, Verónica? ¿Qué son estos patrones...?",
  ui_story_5051_50510502_85_dialog_content = "¡Estoy bien, madre! ¡En realidad! He...",
  ui_story_5051_50510502_86_dialog_content = "Me he vuelto mucho más valiente que antes.",
  ui_story_5051_50510502_87_dialog_content = "Así que ahora... ¡ahora no tienes que preocuparte por mí!",
  ui_story_5051_50510502_88_dialog_content = "¿Es eso así? Esa carita triste que tienes no es muy convincente, ¿sabes?",
  ui_story_5051_50510502_89_dialog_content = "Ven, vamos a lavarte la cara mientras me cuentas lo valiente que eres ahora.",
  ui_story_5051_50510601_1_dialog_content = "(Las señoras entraron...)",
  ui_story_5051_50510601_2_dialog_content = "(La mamá de Mia me sonrió cuando se fueron, probablemente insinuándome que esperara aquí).",
  ui_story_5051_50510601_3_dialog_content = "(¿Qué es eso de nuevo? ¿\"Nunca mires a una dama preparándose\"? Así que tengo que esperar).",
  ui_story_5051_50510601_4_dialog_content = "(He conocido Istvan y Sharona en el camino, y ahora la madre de Mia...)",
  ui_story_5051_50510601_5_dialog_content = "(Todos conversaron con nosotros como si fueran la persona real).",
  ui_story_5051_50510601_6_dialog_content = "(El Cristal de la Eterna Memoria es simplemente maravilloso...)",
  ui_story_5051_50510601_7_dialog_content = "(Pero nunca fue diseñado para que interactuáramos con ellos).",
  ui_story_5051_50510601_8_dialog_content = "(Entonces, contactos como este deben estar poniendo a prueba los límites del cristal).",
  ui_story_5051_50510601_9_dialog_content = "(Suspiro, es difícil evaluar si la situación es buena o mala. Espero que encontremos Jakine y otros pronto...)",
  ui_story_5051_50510601_10_dialog_content = "Tú allí.",
  ui_story_5051_50510601_11_dialog_content = "Esta es la propiedad privada de la Schwartz familia.",
  ui_story_5051_50510601_12_dialog_content = "¿Cómo te las arreglaste para colarte aquí?",
  ui_story_5051_50510601_13_dialog_content = "¿Eh? ¿Quién está ahí?",
  ui_story_5051_50510601_14_dialog_content = "¡Mira hacia abajo, tonto insolente! Carleen te esta hablando!",
  ui_story_5051_50510601_15_dialog_content = "<size=45>Carleen?!</size>",
  ui_story_5051_50510601_16_dialog_content = "¿Te atreves a dirigirte a mí por mi nombre?",
  ui_story_5051_50510601_17_dialog_content = "Por mucho que no disfrute hacer alarde de la nobleza de uno, por este motivo, menospreciarme equivale a menospreciar a la Casa. Schwartz!",
  ui_story_5051_50510601_18_dialog_content = "Escabullirse en nuestra tierra en Schwartz Dia familiar...",
  ui_story_5051_50510601_19_dialog_content = "... y exhibiendo tanta rudeza y mancillando a un miembro. ¡Sufrirás las consecuencias!",
  ui_story_5051_50510601_20_dialog_content = "Espera, ¡me pillaron desprevenido!",
  ui_story_5051_50510601_21_dialog_content = "Por favor, déjame explicarte, princesa. Carleen!",
  ui_story_5051_50510601_22_dialog_content = "¿Adivina quién?",
  ui_story_5051_50510601_23_dialog_content = "<size=45>¡Guau!</size>",
  ui_story_5051_50510601_24_dialog_content = "¡¿Q-Qué?!",
  ui_story_5051_50510601_25_dialog_content = "¡¿Incluso traes un cómplice, intruso despreciable?!",
  ui_story_5051_50510601_26_dialog_content = "¿Eh? Sí...",
  ui_story_5051_50510601_27_dialog_content = "Así es, estamos trabajando juntos para conseguirte, pequeño Carleen!",
  ui_story_5051_50510601_28_dialog_content = "¡D-Despreciable! ¿Dónde está mi lanza? ¡Oye, suéltame, no puedo encontrar mi encaje!",
  ui_story_5051_50510601_29_dialog_content = "Espera un segundo... me suenas familiar, ¿eres Veronica?",
  ui_story_5051_50510601_30_dialog_content = "¡Ajá! ¡No, definitivamente no soy Verónica!",
  ui_story_5051_50510601_31_dialog_content = "¡Por favor, no intentes engañarme con un disfraz vocal tan pobre! ¡Ya no soy un niño!",
  ui_story_5051_50510601_32_dialog_content = "¿Estás seguro, pequeño? Carleen?",
  ui_story_5051_50510601_33_dialog_content = "Heh, a pesar de una madurez más allá de su edad, Carleen todavía entrará en pánico cuando sus ojos estén cubiertos.",
  ui_story_5051_50510601_34_dialog_content = "¿Madre? ¿Estás aquí también, madre? ¡Pídele a Verónica que me libere!",
  ui_story_5051_50510601_35_dialog_content = "¿Oh? ¿Por qué me vuelves a llamar Madre? Me encantaría que me llames mami o no te ayudaré.",
  ui_story_5051_50510601_36_dialog_content = "¡¿P-Por qué?!",
  ui_story_5051_50510601_37_dialog_content = "Eso es lo que obtienes por ser malo con el invitado, Carleen.",
  ui_story_5051_50510601_38_dialog_content = "Estás siendo tan desagradable con alguien que conoces por primera vez, eso no es muy agradable.",
  ui_story_5051_50510601_39_dialog_content = "¡Todo es culpa tuya, intruso desvergonzado! ¡¿Qué has hecho para seducir a mi hermana y a mi madre?!",
  ui_story_5051_50510601_40_dialog_content = "¡Nada, yo no hice nada!",
  ui_story_5051_50510601_41_dialog_content = "Jejeje, me pregunto cuánto tiempo puedes aguantar.",
  ui_story_5051_50510601_42_dialog_content = "Boo-hoo, lamento haber sido malo. ¡Déjame en paz, por favor!",
  ui_story_5051_50510601_43_dialog_content = "Jejeje, no he bromeado Carleen así durante mucho tiempo. Estoy sin aliento de tanto reírme...",
  ui_story_5051_50510601_44_dialog_content = "Hmph... Mala Verónica...",
  ui_story_5051_50510601_45_dialog_content = "Ahí tienes, Verónica. Estás en tu mejor momento cuando te ríes.",
  ui_story_5051_50510601_46_dialog_content = "Pero Carleen sigue gruñón... ¿Debería hacerte cosquillas?",
  ui_story_5051_50510601_47_dialog_content = "¡N-No, no hay necesidad!",
  ui_story_5051_50510601_48_dialog_content = "Así debería ser la familia. Ahora solo si Daniel está aquí también...",
  ui_story_5051_50510601_49_dialog_content = "Lo siento por la molestia.",
  ui_story_5051_50510601_50_dialog_content = "Escuché que Verónica te llamó PlayerName. May ¿Me dirijo a usted igualmente?",
  ui_story_5051_50510601_51_dialog_content = "No hay problema, llámame como quieras.",
  ui_story_5051_50510601_52_dialog_content = "De manera similar a como te dirigiste a Veronica como Mia?",
  ui_story_5051_50510601_53_dialog_content = "¿Qué? Oh...",
  ui_story_5051_50510601_54_dialog_content = "(Su madre escuchó la conversación entre Mia ¡¿y yo?!)",
  ui_story_5051_50510601_X54_dialog_content = "Bueno, madre, en realidad... PlayerName es un amigo que hice en Umbraton...",
  ui_story_5051_50510601_56_dialog_content = "Está bien, yo también corría bajo un alias cuando era joven.",
  ui_story_5051_50510601_57_dialog_content = "Entiendo. Siempre hay lugar para secretos inofensivos, sin importar quién sea.",
  ui_story_5051_50510601_58_dialog_content = "Gracias Madre...",
  ui_story_5051_50510601_59_dialog_content = "Ah, ya veo. Tan pequeño Mia vi a nuestro amigo aquí como un valiente caballero de brillante armadura.",
  ui_story_5051_50510601_60_dialog_content = "Cuya presencia es suficiente para devolver a casa a una princesa perdida, ¿verdad?",
  ui_story_5051_50510601_61_dialog_content = "Oh Madre...",
  ui_story_5051_50510601_62_dialog_content = "¿Así que eres la guardia real de mi hermana? ¿Pero estás seguro de que puedes protegerla con tu cuerpo flacucho y cobarde?",
  ui_story_5051_50510601_63_dialog_content = "Te equivocaste, pequeño Carleen. ¡No es un guardia real, sino posiblemente el Príncipe Encantador!",
  ui_story_5051_50510601_64_dialog_content = "¡Mamá! PlayerName ¡Es solo un amigo que conocí en Umbraton!",
  ui_story_5051_50510601_65_dialog_content = "Una persona amable, paciente que me ha ayudado mucho, eso es todo...",
  ui_story_5051_50510601_66_dialog_content = "¿Secretos inofensivos? no lo entiendo...",
  ui_story_5051_50510601_67_dialog_content = "¡Entrega tus secretos, despreciable intruso!",
  ui_story_5051_50510601_68_dialog_content = "eh, mi nombre es PlayerName...",
  ui_story_5051_50510601_69_dialog_content = "(¡Ella me pisa el pie...!)",
  ui_story_5051_50510601_70_dialog_content = "(Este joven Carleen también es seria y precoz, pero su rostro es más animado y enérgico en general.)",
  ui_story_5051_50510601_71_dialog_content = "(Su madre falleció, su hermana desapareció, y la relación con su padre... Ella ha pasado por muchas penas.)",
  ui_story_5051_50510601_72_dialog_content = "(Sin todo eso, Carleen probablemente sonreiría más.)",
  ui_story_5051_50510601_73_dialog_content = "(Y tal vez todavía me pisotearía cuando esté enojada).",
  ui_story_5051_50510601_74_dialog_content = "¿Por qué me estas mirando? ¿Deseas otro pisotón?",
  ui_story_5051_50510601_75_dialog_content = "No, en absoluto. Por favor perdóname princesa Carleen.",
  ui_story_5051_50510601_76_dialog_content = "Lo siento, Carleen sale tan contundente solo porque no sabe cómo expresarse correctamente. Ella no quiere decir malicia.",
  ui_story_5051_50510601_77_dialog_content = "¿Eres capaz de recuperar todos los recuerdos de tu familia, Mi... Veronica?",
  ui_story_5051_50510601_78_dialog_content = "Sí. Después de reencontrarse con mamá y Carleen, los recuerdos volvieron a inundarme.",
  ui_story_5051_50510601_79_dialog_content = "Carleen y me encantaba columpiarnos juntos en el jardín...",
  ui_story_5051_50510601_80_dialog_content = "¿Nunca nos cansaremos de jugar a Guess Who?",
  ui_story_5051_50510601_81_dialog_content = "Los recuerdos, las emociones, la alegría... Son todos reales, después de todo...",
  ui_story_5051_50510601_82_dialog_content = "¿En serio? ¡Eso es maravilloso!",
  ui_story_5051_50510601_83_dialog_content = "(Pero Mia aún no ha mencionado a su padre, y fue bastante incómodo cuando se encontraron en la sala de recepción).",
  ui_story_5051_50510601_84_dialog_content = "(¿Podría ser que ella tiene una relación tibia con él como Carleen?)",
  ui_story_5051_50510601_85_dialog_content = "¿Puedo ofrecerle un aperitivo o una bebida? Está disponible en el pasillo.",
  ui_story_5051_50510601_86_dialog_content = "Vamos, Verónica, vamos a tomar un bocadillo.",
  ui_story_5051_50510601_87_dialog_content = "Oh, no me tires tan fuerte...",
  ui_story_5051_50510601_88_dialog_content = "No te quedes ahí parado, PlayerName, Ven con nosotros.",
  ui_story_5051_50510601_89_dialog_content = "Jaja... Es raro que toda la familia esté junta y no debería entrometerme.",
  ui_story_5051_50510601_90_dialog_content = "Está bien, niño.",
  ui_story_5051_50510601_91_dialog_content = "Estoy muy familiarizada con esa mirada en tus ojos.",
  ui_story_5051_50510601_92_dialog_content = "Puede parecer decidido, pero también está manchado con las miradas de un niño perdido.",
  ui_story_5051_50510601_93_dialog_content = "No viviste en penurias en Umbraton, ¿verdad?",
  ui_story_5051_50510601_94_dialog_content = "¡No! En realidad, no soy de Umbraton. Soy...",
  ui_story_5051_50510601_95_dialog_content = "(No, no puedo decir la verdad. Caelestite es una sociedad cerrada, muy pocos extraños sabían algo sobre nosotros).",
  ui_story_5051_50510601_96_dialog_content = "(Entonces, mencionar que soy un Caelestita solo estresaría aún más al cristal).",
  ui_story_5051_50510601_97_dialog_content = "Solo soy tu anónimo Joe Average.",
  ui_story_5051_50510601_98_dialog_content = "No tengo familia, así que me gusta viajar y hacer nuevos amigos.",
  ui_story_5051_50510601_99_dialog_content = "¿Viajar? También me gusta viajar. Una pena que no tenga la oportunidad ahora.",
  ui_story_5051_50510601_100_dialog_content = "¿Estás contento con tu vida ahora, niño?",
  ui_story_5051_50510601_101_dialog_content = "Sí, me siento muy feliz.",
  ui_story_5051_50510601_102_dialog_content = "Es bueno escuchar.",
  ui_story_5051_50510601_103_dialog_content = "Eres amiga de Veronica y una niña amable.",
  ui_story_5051_50510601_104_dialog_content = "Siéntase libre de sentirse como en casa durante su estancia aquí.",
  ui_story_5051_50510601_105_dialog_content = "Gracias mi Señora...",
  ui_story_5051_50510601_106_dialog_content = "Mi nombre es Josué y puedes llamarme así.",
  ui_story_5051_50510601_107_dialog_content = "Sí. Bueno, me sentiría mejor dirigiéndome a usted como Lady Joshua.",
  ui_story_5051_50510601_108_dialog_content = "¿Fuiste a una misión secreta en Umbraton con Lumo Knights, Veronica?",
  ui_story_5051_50510601_109_dialog_content = "¿Qué clase de misión es esa? ¿Y cómo lucháis tú y Lumo Knights? ¿Me puedes decir al respecto?",
  ui_story_5051_50510601_110_dialog_content = "Bueno...",
  ui_story_5051_50510601_111_dialog_content = "Sí, Verónica, ¿puedes explicármelo?",
  ui_story_5051_50510601_112_dialog_content = "<size=45>¡Padre!</size>",
  ui_story_5051_50510601_113_dialog_content = "No me opondría si tuvieras la destreza de un guerrero para ofrecerte como voluntario para una batalla.",
  ui_story_5051_50510601_114_dialog_content = "Pero volviste a desertar de tu puesto y regresaste a casa para participar en la fiesta.",
  ui_story_5051_50510601_115_dialog_content = "¿Cómo va a expiar la farsa, especialmente en el día de la conmemoración?",
  ui_story_5051_50510601_116_dialog_content = "...",
  ui_story_5051_50510601_117_dialog_content = "Me acordé de Verónica, querida.",
  ui_story_5051_50510601_118_dialog_content = "Hoy es el día en que todos los miembros de House Schwartz reunirnos, entonces, ¿no debería estar aquí con nosotros?",
  ui_story_5051_50510601_119_dialog_content = "Joshua, tal como dijiste, es House Schwartz, no una familia.",
  ui_story_5051_50510601_120_dialog_content = "Casa Schwartz nunca ha tenido la precedencia de un niño mimado y nunca la tendrá.",
  ui_story_5051_50510601_121_dialog_content = "Sí, somos una casa, pero mucho más una familia.",
  ui_story_5051_50510601_122_dialog_content = "¿Cómo podemos mantener una casa si ni siquiera podemos mantener los corazones de los más cercanos a nosotros?",
  ui_story_5051_50510601_123_dialog_content = "(Es eso Schwartz?)",
  ui_story_5051_50510601_124_dialog_content = "(No es menos impresionante en el futuro, pero definitivamente envejeció con los años y es totalmente diferente a esto).",
  ui_story_5051_50510601_125_dialog_content = "(La tensión es tan espesa y Mia no parece que ella quiera estar aquí... ¡Y mis poderes psíquicos eligen ahora abandonarme!)",
  ui_story_5051_50510601_126_dialog_content = "Discúlpame.",
  ui_story_5051_50510601_127_dialog_content = "(Ms. Blanc! ¡Con el mismo vestido que vi antes! Así que ella también estaba trabajando para el Señor de la Ciudad hace doce años.)",
  ui_story_5051_50510601_128_dialog_content = "¿Quién eres?",
  ui_story_5051_50510601_129_dialog_content = "¿A mí? soy amiga de veronica...",
  ui_story_5051_50510601_130_dialog_content = "¿Amigo?",
  ui_story_5051_50510601_131_dialog_content = "Daniel.",
  ui_story_5051_50510601_132_dialog_content = "Bien. Trate a la persona como un invitado de honor, Sra. Rot.",
  ui_story_5051_50510601_133_dialog_content = "Está bien...",
  ui_story_5051_50510601_134_dialog_content = "El Consejo de Ancianos aún espera su presencia, mi señor.",
  ui_story_5051_50510601_135_dialog_content = "Ya que trajiste a Veronica de vuelta, Joshua, cuídala.",
  ui_story_5051_50510601_136_dialog_content = "No permita que ella y su amiga planteen ningún otro problema.",
  ui_story_5051_50510601_137_dialog_content = "No hay problema, cuidaré de estos niños.",
  ui_story_5051_50510601_138_dialog_content = "Entonces, ¿qué tal si dejas de ser tan malo tú mismo?",
  ui_story_5051_50510601_139_dialog_content = "Está bien.",
  ui_story_5051_50510601_140_dialog_content = "El desfile está a punto de comenzar. Prepara a los niños.",
  ui_story_5051_50510601_141_dialog_content = "Suspiro...",
  ui_story_5051_50510601_142_dialog_content = "¿Te sientes bien, Verónica?",
  ui_story_5051_50510601_143_dialog_content = "Tu padre no está enojado contigo, solo tiene mucho sobre su mesa hoy.",
  ui_story_5051_50510601_144_dialog_content = "Yo... Yo...",
  ui_story_5051_50510601_145_dialog_content = "Está bien ahora, mi niña...",
  ui_story_5051_50510601_146_dialog_content = "Verónica...",
  ui_story_5051_50510601_147_dialog_content = "Hay tiempo antes del desfile, milady. Todavía tienes la oportunidad de ponerte al día con tu familia, déjame el resto a mí.",
  ui_story_5051_50510601_148_dialog_content = "Gracias, Sra. Rot.",
  ui_story_5051_50510601_149_dialog_content = "Solo haciendo mi trabajo.",
  ui_story_5051_50510601_150_dialog_content = "En cuanto a ti, ven conmigo para aclimatarte con el proceso del desfile y prepararte para los próximos eventos.",
  ui_story_5051_50510601_151_dialog_content = "Tenga la seguridad de que Lady Joshua es experta en consolar a los demás. La princesa Verónica está en buenas manos.",
  ui_story_5051_50510601_152_dialog_content = "Está bien. Gracias, Ms. Blanc.",
  ui_story_5051_50510601_153_dialog_content = "Ms. Blanc? No esperaba que nadie me llamara por ese nombre aquí.",
  ui_story_5051_50510601_154_dialog_content = "May Pregunto ¿cómo supiste de ese nombre?",
  ui_story_5051_50510601_155_dialog_content = "(Entonces Ms. Blanc no pasó por eso hace doce años?)",
  ui_story_5051_50510601_156_dialog_content = "(Ahora que lo pienso, el Señor de la Ciudad en el mundo real también la llamó Sra. Rot).",
  ui_story_5051_50510601_157_dialog_content = "(Ese tiene que ser el nombre cuando ella está trabajando para el Señor de la Ciudad... Entonces, ¿cómo voy a pasar esto?)",
  ui_story_5051_50510601_158_dialog_content = "Esta bien. Así como yo tengo mis secretos que guardar, tú tienes los tuyos. Eso es justo.",
  ui_story_5051_50510601_159_dialog_content = "Usted es un invitado de honor que me ha sido confiado personalmente por el Señor de la Ciudad, por lo tanto, es mi deber asegurarme de que su día sea placentero.",
  ui_story_5051_50510601_160_dialog_content = "Sin embargo, espero que me llame Sra. Rot mientras tanto para acelerar mis obligaciones.",
  ui_story_5051_50510601_161_dialog_content = "Claro, Sra. Rot, no voy a causarle problemas.",
  ui_story_5051_50510601_162_dialog_content = "Gracias por su comprensión. Por aqui por favor.",
  ui_story_5051_50510701_1_dialog_content = "¡Invenir eum! ¡Invenir eum! ¡Invenir eum!",
  ui_story_5051_50510701_2_dialog_content = "Por favor, dime, ¿dónde está la persona en mente en este momento?",
  ui_story_5051_50510701_3_dialog_content = "<size=45>¡Abrahadabra!</size>",
  ui_story_5051_50510701_4_dialog_content = "¡Ajá, adelante!",
  ui_story_5051_50510701_5_dialog_content = "Escuché que otra unidad de caballeros fue transferida a Umbraton.",
  ui_story_5051_50510701_6_dialog_content = "¿Qué? ¿Qué están haciendo en Umbraton?",
  ui_story_5051_50510701_7_dialog_content = "Luchando contra la invasión de Eclipsite, supongo. Después de todo, Umbraton está bajo la defensa de Lumopolis.",
  ui_story_5051_50510701_8_dialog_content = "Entonces, ¿por qué no vamos?",
  ui_story_5051_50510701_9_dialog_content = "¿Eres estúpido? Somos los caballeros de <color=#FFB400>kártima</color>. ¡No podemos ir a un basurero así!",
  ui_story_5051_50510701_10_dialog_content = "¡Shh, mantenlo abajo! no dejes Sharona atraparnos holgazaneando de nuevo.",
  ui_story_5051_50510701_11_dialog_content = "Kartima sigue siendo el mejor. Estamos en pie de igualdad con el Señor de la Ciudad.",
  ui_story_5051_50510701_12_dialog_content = "Entiendo...",
  ui_story_5051_50510701_13_dialog_content = "Entiendo...",
  ui_story_5051_50510701_14_dialog_content = "¿Hey Quién eres tú?",
  ui_story_5051_50510701_15_dialog_content = "¡Persona sospechosa! ¡Rápido, atrápala!",
  ui_story_5051_50510701_16_dialog_content = "Lo siento, lugar equivocado. ¡Adiós!",
  ui_story_5051_50510701_17_dialog_content = "¡Abrahadabra!",
  ui_story_5051_50510701_18_dialog_content = "¿Dónde estoy ahora?",
  ui_story_5051_50510701_19_dialog_content = "Irridon Obtuve el primer lugar del semestre otra vez...",
  ui_story_5051_50510701_20_dialog_content = "Irridon no solo es bonita y buena estudiante, también goza de prestigio ante los instructores de Dawn Academia.",
  ui_story_5051_50510701_21_dialog_content = "Estoy verde de envidia.",
  ui_story_5051_50510701_22_dialog_content = "Tal vez incluso se salte grados y se gradúe directamente más tarde.",
  ui_story_5051_50510701_23_dialog_content = "Ella es demasiado perfecta.",
  ui_story_5051_50510701_24_dialog_content = "Irridon? ¿Quién es ese?",
  ui_story_5051_50510701_25_dialog_content = "¿Quién es esa chica con el atuendo extraño? Sin embargo, su cabello rojo es deslumbrante.",
  ui_story_5051_50510701_26_dialog_content = "¿Qué clase de disfraz es ese? ¡Tendré que denunciarla ante el Salón de Justicia!",
  ui_story_5051_50510701_27_dialog_content = "Vaya, lugar equivocado otra vez, lo siento!",
  ui_story_5051_50510701_28_dialog_content = "Abra... hadabra...",
  ui_story_5051_50510701_29_dialog_content = "¿Esto es... un restaurante?",
  ui_story_5051_50510701_30_dialog_content = "Pero no veo a nadie aquí.",
  ui_story_5051_50510701_31_dialog_content = "<color=#e8d9bb>Gruñido-</color>",
  ui_story_5051_50510701_32_dialog_content = "Entonces, bola de cristal, me trajiste aquí porque sabías que tenía hambre, ¿verdad?",
  ui_story_5051_50510701_33_dialog_content = "¡Pero es más urgente encontrar a todos! ¡Sin mencionar que es inútil comer en el cristal!",
  ui_story_5051_50510701_34_dialog_content = "¡Una vez más!",
  ui_story_5051_50510701_35_dialog_content = "¡Invenir eum! ¡Invenir eum! ¡Invenir eum!",
  ui_story_5051_50510701_36_dialog_content = "Por favor, dime, ¿dónde está la persona en mente en este momento?",
  ui_story_5051_50510701_37_dialog_content = "¡Abrahadabra!",
  ui_story_5051_50510701_38_dialog_content = "<size=45>Jajajajajaja!</size>",
  ui_story_5051_50510701_39_dialog_content = "¡¿Q-Quién está ahí?! ¡Te ríes demasiado fuerte y me asustaste!",
  ui_story_5051_50510701_40_dialog_content = "Tus habilidades de adivinación son *hipo* pobre, niña.",
  ui_story_5051_50510701_41_dialog_content = "¡Cómo te atreves a llamar a mi adivinación coja!",
  ui_story_5051_50510701_42_dialog_content = "¡Lo aprendí de mi madre, y ella fue la mejor maestra de adivinación de todos los tiempos!",
  ui_story_5051_50510701_43_dialog_content = "No me digas que nunca has oído hablar de <color=#FFB400>Booz</color> de Northland!",
  ui_story_5051_50510701_44_dialog_content = "¿Boras? Eso suena familiar... *hipo*",
  ui_story_5051_50510701_45_dialog_content = "¡Así que lo que! Cojo sigue siendo cojo. ¡Deberías admitirlo!",
  ui_story_5051_50510701_46_dialog_content = "¡Qué grosero! Te mostrare-!",
  ui_story_5051_50510701_47_dialog_content = "*hipo* Hablas mucho para alguien que no puede respaldarlo.",
  ui_story_5051_50510701_48_dialog_content = "¿Qué tal si vemos de quién es la adivinación más precisa?",
  ui_story_5051_50510701_49_dialog_content = "¡Estás en!",
  ui_story_5051_50510701_50_dialog_content = "Por favor paguen su cheque, señoras.",
  ui_story_5051_50510701_51_dialog_content = "¿Eh? Uh, no tengo dinero conmigo... *hipo*",
  ui_story_5051_50510701_52_dialog_content = "¿Y tú?",
  ui_story_5051_50510701_53_dialog_content = "¿A mí? No la conozco, ¿por qué debería pagar?",
  ui_story_5051_50510701_54_dialog_content = "Si no puede pagar, espere aquí a que los guardias lo detengan.",
  ui_story_5051_50510701_55_dialog_content = "¿Qué? ¡De ninguna manera, tengo cosas importantes que hacer!",
  ui_story_5051_50510701_56_dialog_content = "¡Dijiste algo! ¡Tú empezaste todo esto!",
  ui_story_5051_50510701_57_dialog_content = "Uff.",
  ui_story_5051_50510701_58_dialog_content = "Ella se quedó dormida...",
  ui_story_5051_50510701_59_dialog_content = "Paga o vete con los guardias, tu eliges.",
  ui_story_5051_50510701_60_dialog_content = "Está bien... ¿Cuánto es?",
  ui_story_5051_50510701_61_dialog_content = "127,938 Nightium.",
  ui_story_5051_50510701_62_dialog_content = "<size=45>¡¿Cuánto cuesta?!</size>",
  ui_story_5051_50510701_63_dialog_content = "Esta dama bebió muchas de nuestras mejores reservas, y ya se incluye un descuento de vacaciones.",
  ui_story_5051_50510701_64_dialog_content = "Maldiciones... Mi presupuesto de viaje... Mi caché...",
  ui_story_5051_50510701_65_dialog_content = "(Pero todo esto en el Cristal de la memoria eterna probablemente no sea real, así que aún debería tener mi dinero después de irme, ¿verdad?)",
  ui_story_5051_50510701_66_dialog_content = "Aquí tienes...",
  ui_story_5051_50510701_67_dialog_content = "Gracias.",
  ui_story_5051_50510701_68_dialog_content = "Oye, acabo de pagar por ti. Ahora ya no tienes excusas.",
  ui_story_5051_50510701_69_dialog_content = "¡Lucharé por el honor de mi madre hoy!",
  ui_story_5051_50510701_70_dialog_content = "Oye, ¿dónde está ella...?",
  ui_story_5051_50510701_71_dialog_content = "Por aquí... *hipo*",
  ui_story_5051_50510701_72_dialog_content = "¡Alto!",
  ui_story_5051_50510701_73_dialog_content = "¡No intentes escapar entre la multitud!",
  ui_story_5051_50510701_74_dialog_content = "Muy bien, aquí está...",
  ui_story_5051_50510701_75_dialog_content = "¡Te tengo!",
  ui_story_5051_50510701_76_dialog_content = "No solo me obligaron a pagar por ti, ahora intentaste huir...",
  ui_story_5051_50510701_77_dialog_content = "Veamos a dónde puedes correr ahora.",
  ui_story_5051_50510701_78_dialog_content = "¿Por qué debería correr? Mira, el que estás mirando está allí.",
  ui_story_5051_50510701_79_dialog_content = "¿El que estoy buscando...?",
  ui_story_5051_50510701_80_dialog_content = "¡Mira, el desfile viene por aquí!",
  ui_story_5051_50510701_81_dialog_content = "¿Ves lo impresionante que es el Señor de la Ciudad?",
  ui_story_5051_50510701_82_dialog_content = "y princesa Carleen ¡y la princesa Verónica también están con él!",
  ui_story_5051_50510701_83_dialog_content = "¡Señora Josué!",
  ui_story_5051_50510701_84_dialog_content = "Viva la Casa Schwartz!",
  ui_story_5051_50510701_85_dialog_content = "Mira hacia arriba, Verónica, todos te están saludando.",
  ui_story_5051_50510701_86_dialog_content = "Si claro.",
  ui_story_5051_50510701_87_dialog_content = "Relájate, toma mi mano.",
  ui_story_5051_50510701_88_dialog_content = "(Mia todavía parece bastante nervioso.)",
  ui_story_5051_50510701_89_dialog_content = "(El desfile continuará por un tiempo. ¿Ella aguantará...?)",
  ui_story_5051_50510701_90_dialog_content = "(Nunca imaginé Schwartz El Día de la Familia sería una gran celebración en ese entonces).",
  ui_story_5051_50510701_91_dialog_content = "(Aunque el banquete fue lo suficientemente extravagante, todavía no podía compararse con esta celebración hace doce años).",
  ui_story_5051_50510701_92_dialog_content = "(¿Qué sucedió durante los doce años para cambiar eso?)",
  ui_story_5051_50510701_93_dialog_content = "(Además, los Eclipsites con los que me encontré hoy en la puerta ciertamente no fueron transportados por accidente).",
  ui_story_5051_50510701_94_dialog_content = "(Alguien estaba aprovechando la festividad para contrabandear Eclipsites a Lumopolis).",
  ui_story_5051_50510701_95_dialog_content = "(¿Pueden los Lumo Knights manejarlo? ¿O se convertirá en un gran desastre al final?)",
  ui_story_5051_50510701_96_dialog_content = "(Bueno, espero que no ponga en peligro a nadie).",
  ui_story_5051_50510701_97_dialog_content = "(Hmm, ¿por qué tengo la sensación de que alguien me está mirando?)",
  ui_story_5051_50510701_98_dialog_content = "(No puede ser, ¿por qué mirarme cuando solo estoy de paseo?)",
  ui_story_5051_50510701_99_dialog_content = "(Y la Sra. Rot me advirtió que no deambulara y arruinara el desfile).",
  ui_story_5051_50510701_100_dialog_content = "(¡Deja de preguntarte!)",
  ui_story_5051_50510701_101_dialog_content = "Ey, PlayerName! Mia!",
  ui_story_5051_50510701_102_dialog_content = "Hmm, ¡la multitud es demasiado ruidosa para que me escuchen!",
  ui_story_5051_50510701_103_dialog_content = "Ah, deja de desperdiciar esfuerzos.",
  ui_story_5051_50510701_104_dialog_content = "Incluso si pudieran oírte, ¡no podrían simplemente dejar el desfile por ti!",
  ui_story_5051_50510701_105_dialog_content = "Supongo...",
  ui_story_5051_50510701_106_dialog_content = "Dime, ¿cómo supiste que eran los que estaba buscando?",
  ui_story_5051_50510701_107_dialog_content = "¿Y cómo supiste que iban a estar aquí?",
  ui_story_5051_50510701_108_dialog_content = "¿No me retaste a un concurso de adivinación?",
  ui_story_5051_50510701_109_dialog_content = "¡Acabo de ganar!",
  ui_story_5051_50510701_110_dialog_content = "...",
  ui_story_5051_50510701_111_dialog_content = "<size=45>¡Asombroso!</size>",
  ui_story_5051_50510701_112_dialog_content = "<size=45>¡Por favor, tómame como tu alumno!</size>",
  ui_story_5051_50510701_113_dialog_content = "Vaya, no tan fuerte. me estas dando dolor de cabeza...",
  ui_story_5051_50510701_114_dialog_content = "No tomo alumnos. Solo estoy aquí por algunos trabajos ocasionales y para ganar dinero con la bebida.",
  ui_story_5051_50510701_115_dialog_content = "Esta noche... mañana, ¿o tal vez pasado mañana? De todos modos, me iré cuando tenga suficiente para beber.",
  ui_story_5051_50510701_116_dialog_content = "¡Entonces, por favor, al menos dime tu nombre!",
  ui_story_5051_50510701_117_dialog_content = "(¡Para que pueda rastrearte después de que salga de este cristal!)",
  ui_story_5051_50510701_118_dialog_content = "Muy bien, ya que saltaste para la comida...",
  ui_story_5051_50510701_119_dialog_content = "Mi nombre es Booz.",
  ui_story_5051_50510701_120_dialog_content = "¿Ah?",
  ui_story_5051_50510701_121_dialog_content = "<color=#FFB400>Mamá</color>?",
  ui_story_5051_50510701_122_dialog_content = "Mi agradecimiento a todas las personas de Lumopolis reunidas aquí hoy para celebrar esta ocasión especial.",
  ui_story_5051_50510701_123_dialog_content = "La casa Schwartz es la joya de la corona de la ciudad, así como la fundación.",
  ui_story_5051_50510701_124_dialog_content = "Te defendimos con las afiladas espadas que forjaste para nosotros.",
  ui_story_5051_50510701_125_dialog_content = "Hoy estamos aquí para alabar las virtudes de House Schwartz ¡así como las de los ciudadanos de Lumopolis!",
  ui_story_5051_50510701_126_dialog_content = "Por la presente declaro el comienzo de Schwartz ¡Celebración del día de la familia!",
  ui_story_5051_50510701_127_dialog_content = "Ahora, ¡que comience la Ceremonia de Enfrentamiento!",
  ui_story_5051_50510701_128_dialog_content = "¡Maravilloso discurso de apertura, mi señor!",
  ui_story_5051_50510701_129_dialog_content = "...",
  ui_story_5051_50510701_130_dialog_content = "Esta prosperidad que estás viendo ahora es la representación de la destreza de Lumopolis.",
  ui_story_5051_50510701_131_dialog_content = "Solo Casa Schwartz es digno de tal gloria.",
  ui_story_5051_50510701_132_dialog_content = "Hay relatos de que la Princesa Verónica derrotó a los Eclipsites que intentaban infiltrarse en la ciudad el día de hoy.",
  ui_story_5051_50510701_133_dialog_content = "Puede que sea una aprendiz de caballero, pero eso ya es tan impresionante como un caballero oficial.",
  ui_story_5051_50510701_134_dialog_content = "Escuché que cuando los guardias corrieron a la escena, prácticamente no quedaba nada de los Eclipsites.",
  ui_story_5051_50510701_135_dialog_content = "Si no recuerdo mal, los Kartimas son responsables de la seguridad de las vacaciones, ¿no es así? no puedo creerlo...",
  ui_story_5051_50510701_136_dialog_content = "Es insignificante y no vale la pena mencionarlo.",
  ui_story_5051_50510701_137_dialog_content = "Supongo que Veronica también entendió eso, por eso no buscó mis elogios.",
  ui_story_5051_50510701_138_dialog_content = "...",
  ui_story_5051_50510701_139_dialog_content = "Es mucho más que insignificante.",
  ui_story_5051_50510701_140_dialog_content = "La historia se ha extendido por toda la ciudad.",
  ui_story_5051_50510701_141_dialog_content = "\"La princesa Verónica es más de lo que parece, resolviendo una crisis sin ayuda y sin esfuerzo\".",
  ui_story_5051_50510701_142_dialog_content = "Me imagino que a todos les encantaría ver lo brillante que pelea.",
  ui_story_5051_50510701_143_dialog_content = "Defender la justicia cuando hay errores que corregir es una virtud encomiable.",
  ui_story_5051_50510701_144_dialog_content = "Pero ella no debe desarrollar el hábito de alardear de sí misma a esta temprana edad.",
  ui_story_5051_50510701_145_dialog_content = "Darse el gusto con la fachada no la llevará a ninguna parte.",
  ui_story_5051_50510701_146_dialog_content = "¡Por favor, no la descartes así!",
  ui_story_5051_50510701_147_dialog_content = "La princesa Verónica ha mantenido un perfil bajo sin apenas fanfarria.",
  ui_story_5051_50510701_148_dialog_content = "En comparación, princesa Carleen ha sido promocionado como un gobernante pródigo desde la infancia.",
  ui_story_5051_50510701_149_dialog_content = "Princesa Carleen solo seguirá sobresaliendo en los años siguientes, mientras que el prestigio y la autoridad de ser la mayor de la Princesa Verónica solo...",
  ui_story_5051_50510701_150_dialog_content = "¡El asunto de la sucesión no depende de nosotros para criticarlo, Duque Troy!",
  ui_story_5051_50510701_151_dialog_content = "El Señor de la Ciudad ha demostrado ser perspicaz y valorar el talento.",
  ui_story_5051_50510701_152_dialog_content = "Debe haber suficientes pensamientos detrás de recordar a la princesa del frente.",
  ui_story_5051_50510701_153_dialog_content = "¡Sí, tienes razón, poniendo a alguien en la posición de tener éxito! Creo que la princesa Verónica estará mejor en la ciudad.",
  ui_story_5051_50510701_154_dialog_content = "Por favor, perdone mi insolencia, mi señor.",
  ui_story_5051_50510701_155_dialog_content = "Padre, yo...",
  ui_story_5051_50510701_156_dialog_content = "Ve a prepararte, Verónica.",
  ui_story_5051_50510701_157_dialog_content = "¿Qué, prepárate?",
  ui_story_5051_50510701_158_dialog_content = "De acuerdo con el horario, eres el siguiente.",
  ui_story_5051_50510701_159_dialog_content = "No hagas esperar a la gente.",
  ui_story_5051_50510701_160_dialog_content = "Si, vale...!",
  ui_story_5051_50510701_161_dialog_content = "Ambos han estado conmigo durante años, y parecen saber exactamente cómo pienso.",
  ui_story_5051_50510701_162_dialog_content = "Había planeado guardar a Veronica para el final y mostrar el poder de la nueva generación de House. Schwartz.",
  ui_story_5051_50510701_163_dialog_content = "Simplemente no esperaba que ustedes dos se dieran cuenta.",
  ui_story_5051_50510701_164_dialog_content = "Fue solo un comentario casual de mi parte, mi señor.",
  ui_story_5051_50510701_165_dialog_content = "Tengo muchas ganas de la primera salida de la Princesa Verónica.",
  ui_story_5051_50510701_166_dialog_content = "¿De verdad vas a hacer esto, Mia?",
  ui_story_5051_50510701_167_dialog_content = "...",
  ui_story_5051_50510701_168_dialog_content = "Creo que esta es una buena oportunidad para postularse.",
  ui_story_5051_50510701_169_dialog_content = "Se suponía que solo íbamos a ver a Lady Joshua, pero la presencia del Señor de la Ciudad nos obligó a venir aquí.",
  ui_story_5051_50510701_X169_dialog_content = "Perdimos la oportunidad de pedirle a Lady Joshua que nos ayudara a encontrar a nuestros amigos, pero no debemos seguir involucrándonos más.",
  ui_story_5051_50510701_170_dialog_content = "T-Tienes razón... es hora de que nos vayamos...",
  ui_story_5051_50510701_171_dialog_content = "La persona de arriba es solo una ilusión y no mi padre... Está bien negarse... No se enfadará...",
  ui_story_5051_50510701_X171_dialog_content = "Te he reiterado muchas veces, Verónica, que no necesitas entrenar para el combate, porque no tienes talento en ese dominio.",
  ui_story_5051_50510701_X172_dialog_content = "¿Por qué te da vergüenza saludar a los demás, Verónica? Tienes diez años y ya no eres un niño pequeño.",
  ui_story_5051_50510701_X173_dialog_content = "¿Unirse a Lumo Knights? ¡No espero que destaques, Verónica, solo que no preocupes a tu madre!",
  ui_story_5051_50510701_172_dialog_content = "Mia...?",
  ui_story_5051_50510701_173_dialog_content = "(Por que es Mia temblando ahora? ¿Tiene miedo de desafiar las órdenes de su padre?)",
  ui_story_5051_50510701_174_dialog_content = "(Si ese es el caso, solo la estresará más si la obligo a irse).",
  ui_story_5051_50510701_175_dialog_content = "(¡Y ella acaba de mejorar últimamente!)",
  ui_story_5051_50510701_176_dialog_content = "OK...",
  ui_story_5051_50510701_177_dialog_content = "¿Quieres unirte al duelo, Mia?",
  ui_story_5051_50510701_178_dialog_content = "¿M-Yo? Estoy bien de cualquier manera... ¿Crees que debería, PlayerName?",
  ui_story_5051_50510701_179_dialog_content = "Si pelear te impide temblar, deberías hacerlo.",
  ui_story_5051_50510701_180_dialog_content = "¿Qué? Oh no, mi condición...",
  ui_story_5051_50510701_181_dialog_content = "Tu mano es tan fría, Mia.",
  ui_story_5051_50510701_182_dialog_content = "Sí, desde que estoy en este cuerpo, me siento muy frío.",
  ui_story_5051_50510701_183_dialog_content = "Tu mano es muy cálida, PlayerName.",
  ui_story_5051_50510701_184_dialog_content = "Y puedo sentir consuelo y tranquilidad en el calor...",
  ui_story_5051_50510701_185_dialog_content = "Gracias, ya no tengo miedo.",
  ui_story_5051_50510701_X180_dialog_content = "Siento ser una carga para ti.",
  ui_story_5051_50510701_X181_dialog_content = "No, Mia, prometí llevarte al banquete y ver a tu familia, así que soy responsable de cuidarte.",
  ui_story_5051_50510701_X182_dialog_content = "Si pelear puede aliviar tus preocupaciones, ¡deberías hacerlo!",
  ui_story_5051_50510701_X183_dialog_content = "¡Todas las consecuencias están sobre mí!",
  ui_story_5051_50510701_X184_dialog_content = "(¡Todavía podemos correr después de la pelea, si nada más!)",
  ui_story_5051_50510701_X185_dialog_content = "Sé que eres una persona gentil, PlayerName... Pero por qué haces esto...",
  ui_story_5051_50510701_X186_dialog_content = "Porque somos amigos.",
  ui_story_5051_50510701_X187_dialog_content = "¿Que amigos?",
  ui_story_5051_50510701_X188_dialog_content = "Es natural que los amigos se apoyen unos en otros y se hagan felices.",
  ui_story_5051_50510701_X189_dialog_content = "...",
  ui_story_5051_50510701_X190_dialog_content = "Uh, ¿pensaste que eso era raro?",
  ui_story_5051_50510701_X191_dialog_content = "Jejeje, un poco...",
  ui_story_5051_50510701_X192_dialog_content = "¿Qué tiene eso de raro?",
  ui_story_5051_50510701_X193_dialog_content = "Porque nadie me ha tratado como un amigo más que Baba Yaga.",
  ui_story_5051_50510701_X194_dialog_content = "Todos me vieron como Su Alteza o Pobre Mia...",
  ui_story_5051_50510701_X195_dialog_content = "¿Puedo realmente entrar en la pelea, PlayerName?",
  ui_story_5051_50510701_X196_dialog_content = "¡Sí tu puedes!",
  ui_story_5051_50510701_X197_dialog_content = "Gracias, no te defraudaré.",
  ui_story_5051_50510701_X198_dialog_content = "Oh, los duelos también atraerán la atención de todos.",
  ui_story_5051_50510701_X199_dialog_content = "Puedes escanear la multitud en busca de mi padre y otros mientras tanto, PlayerName.",
  ui_story_5051_50510701_X200_dialog_content = "Entonces podemos encontrar a todos incluso sin la ayuda de mi madre.",
  ui_story_5051_50510701_X201_dialog_content = "A juzgar por eso, es una muy buena decisión pelear...",
  ui_story_5051_50510701_X202_dialog_content = "Así es, Mia! ¡Supongo que mi tonto optimismo se te está contagiando!",
  ui_story_5051_50510701_X203_dialog_content = "Así, Su Alteza, el duelo está por comenzar.",
  ui_story_5051_50510701_X204_dialog_content = "Claro, voy.",
  ui_story_5051_50510701_X205_dialog_content = "¡Me voy, entonces...!",
  ui_story_5051_50510701_X206_dialog_content = "Anda tu, Mia!",
  ui_story_5051_50510701_186_dialog_content = "Ir, Mia! Y si realmente no puedes ganar...",
  ui_story_5051_50510701_187_dialog_content = "Si por casualidad te quedas corto, me sumergiré.",
  ui_story_5051_50510701_188_dialog_content = "¿Qué? Y usted es...",
  ui_story_5051_50510701_189_dialog_content = "Saludos, Princesa Verónica, soy tu oponente.",
  ui_story_5051_50510701_190_dialog_content = "El Señor de la Ciudad me ha transmitido instrucciones para que entrene contigo mientras aseguro tu total seguridad.",
  ui_story_5051_50510701_191_dialog_content = "Elija una espada ceremonial aquí. Estas armas de entrenamiento asegurarán que no te lastimes accidentalmente.",
  ui_story_5051_50510701_192_dialog_content = "Además, como evento de apertura de Schwartz Día de la familia, no debes caer en la derrota.",
  ui_story_5051_50510701_193_dialog_content = "Todo lo que tienes que hacer es trabajar conmigo y derribarme cuando sea el momento adecuado.",
  ui_story_5051_50510701_194_dialog_content = "¿Trabajar contigo y derribarte cuando sea el momento adecuado?",
  ui_story_5051_50510701_195_dialog_content = "¿Quieres decir que no será un partido real?",
  ui_story_5051_50510701_196_dialog_content = "¿Solo un espectáculo como una obra de teatro?",
  ui_story_5051_50510701_197_dialog_content = "Te he reiterado muchas veces, Verónica, que no necesitas entrenar para el combate, porque no tienes talento en ese dominio.",
  ui_story_5051_50510701_198_dialog_content = "¿Por qué te da vergüenza saludar a los demás, Verónica? Tienes diez años y ya no eres un niño pequeño.",
  ui_story_5051_50510701_199_dialog_content = "¿Unirse a Lumo Knights? ¡No espero que destaques, Verónica, solo que no preocupes a tu madre!",
  ui_story_5051_50510701_200_dialog_content = "Animarse, Mia!",
  ui_story_5051_50510701_201_dialog_content = "PlayerName...",
  ui_story_5051_50510701_202_dialog_content = "No necesitas la rama de olivo de tu padre para probarte a ti mismo, Mia.",
  ui_story_5051_50510701_203_dialog_content = "El Señor de la Ciudad tiene una gran autoridad, pero eso no significa que pueda dirigir tu vida por ti.",
  ui_story_5051_50510701_204_dialog_content = "No sé qué tipo de pensamientos acaban de pasar por tu mente...",
  ui_story_5051_50510701_205_dialog_content = "¡Pero sé que no eres la persona que eras hace doce años!",
  ui_story_5051_50510701_206_dialog_content = "Yo...",
  ui_story_5051_50510701_207_dialog_content = "Estoy seguro de que odias el hecho de que esta victoria esté predeterminada.",
  ui_story_5051_50510701_208_dialog_content = "Así que demuéstrales a todos que puedes ganar solo.",
  ui_story_5051_50510701_209_dialog_content = "Pero mi oponente...",
  ui_story_5051_50510701_210_dialog_content = "Si no está dispuesto a pelear contigo de verdad, ¡oblígalo!",
  ui_story_5051_50510701_211_dialog_content = "¿Házle? ¿Empujarlo para que haga todo lo posible? ¿Pero puedo manejar eso?",
  ui_story_5051_50510701_212_dialog_content = "¡Por supuesto! ¿No dijeron que la historia de que acabaste con los Eclipsites antes de que aparecieran los caballeros ya estaba por toda la ciudad?",
  ui_story_5051_50510701_213_dialog_content = "Entonces, ¿cómo puede un guardia promedio ser un rival para ti?",
  ui_story_5051_50510701_214_dialog_content = "Ejem, uh, todavía estoy aquí...",
  ui_story_5051_50510701_215_dialog_content = "Oh, ups, lo siento...",
  ui_story_5051_50510701_216_dialog_content = "Ya que escuchaste todo eso, supongo que lo tendremos a la vista.",
  ui_story_5051_50510701_217_dialog_content = "Estás listo, Mia?",
  ui_story_5051_50510701_218_dialog_content = "Crees tanto en mí, PlayerName... ¡Esta es la primera vez que alguien ha creído tanto en mí!",
  ui_story_5051_50510701_219_dialog_content = "¡Estoy listo!",
  ui_story_5051_50510701_220_dialog_content = "Bien entonces-",
  ui_story_5051_50510701_221_dialog_content = "\"White Night Up High. ¡Valiente guerrero, por la presente te desafío a un duelo!\"",
  ui_story_5051_50510701_222_dialog_content = "\"Toma una espada o pierde tu honor\".",
  ui_story_5051_50510701_223_dialog_content = "\"¡Deberías aceptar mi desafío, constituye una declaración de no arrepentirse incluso en caso de muerte!\"",
  ui_story_5051_50510701_224_dialog_content = "Uh, ¿no está la muerte yendo un poco demasiado lejos...?",
  ui_story_5051_50510701_225_dialog_content = "Sí, por favor líbrame de una consecuencia de la que no puedo asumir la responsabilidad...",
  ui_story_5051_50510701_226_dialog_content = "B-Bueno, solo estoy repitiendo las líneas de las novelas...",
  ui_story_5051_50510701_227_dialog_content = "Suspiro... Está bien, te prometo que no caeré ni me rendiré fácilmente.",
  ui_story_5051_50510701_228_dialog_content = "Pero si no puedes derrotarme, igual cederé según las instrucciones, ya que solo estoy haciendo un trabajo.",
  ui_story_5051_50510701_229_dialog_content = "Eso será grandioso. ¡Gracias!",
  ui_story_5051_50510701_230_dialog_content = "Entonces, la espada ceremonial...",
  ui_story_5051_50510701_231_dialog_content = "Deberías tomar eso, Mia.",
  ui_story_5051_50510701_232_dialog_content = "Bien. Por favor, no te lastimes.",
  ui_story_5051_50510701_233_dialog_content = "pensé que Mia ¡podría lastimarte!",
  ui_story_5051_50510701_234_dialog_content = "¿Q-Qué?",
  ui_story_5051_50510701_235_dialog_content = "Eso es cierto.",
  ui_story_5051_50510701_236_dialog_content = "Sigues diciendo el nombre Mia...",
  ui_story_5051_50510701_237_dialog_content = "¿Es esta niña traviesa ante mí realmente la mansa princesa Verónica?",
  ui_story_5051_50510701_238_dialog_content = "¡P-Por qué, por supuesto! Mia es solo...",
  ui_story_5051_50510701_239_dialog_content = "Mia es solo un apodo entre nosotros!",
  ui_story_5051_50510701_240_dialog_content = "Oh, okay...",
  ui_story_5051_50510701_241_dialog_content = "Ya es hora. Te veré en el campo pronto, Su Alteza.",
  ui_story_5051_50510701_242_dialog_content = "Bueno. ¡Solo asegúrate de no guardarte nada hasta el final!",
  ui_story_5051_50510701_243_dialog_content = "Voy a...",
  ui_story_5051_50510701_244_dialog_content = "(¿No me enviaron solo a hacer un trabajo? ¿Por qué siento que acabo de ver un drama adolescente?)",
  ui_story_5051_50510802_1_dialog_content = "(Puedo escuchar a la multitud rugiendo incluso desde aquí).",
  ui_story_5051_50510802_2_dialog_content = "(Supongo que la celebración ha comenzado).",
  ui_story_5051_50510802_3_dialog_content = "(Hora de robar el Cristal de la Memoria Eterna...)",
  ui_story_5051_50510802_4_dialog_content = "Oye, tú ahí, detente.",
  ui_story_5051_50510802_5_dialog_content = "(¿Cómo es que todavía hay un guardia aquí?)",
  ui_story_5051_50510802_6_dialog_content = "Debo pedirle que limpie su identidad.",
  ui_story_5051_50510802_7_dialog_content = "¿Mi identidad? ¡Soy Sir Caleb Magnus! ¡No necesito demostrar quién soy!",
  ui_story_5051_50510802_8_dialog_content = "¡¿Señor Caleb Magnus...?!",
  ui_story_5051_50510802_9_dialog_content = "No, visitó a Lady Joshua hace unos días.",
  ui_story_5051_50510802_10_dialog_content = "¡Compartiste cierto parecido, pero su cabello es mucho más corto y tiene una constitución diferente!",
  ui_story_5051_50510802_11_dialog_content = "Ríndete, intruso, o lo haré...",
  ui_story_5051_50510802_12_dialog_content = "¡Tranquilo, antes de llamar la atención de otros soldados!",
  ui_story_5051_50510802_13_dialog_content = "(Esta es la segunda vez que sucede algo inesperado. Qué día tan difícil).",
  ui_story_5051_50510802_14_dialog_content = "(Debo conseguir el cristal antes de quedarme sin Lumina...)",
  ui_story_5051_50510802_15_dialog_content = "¡Compré bebidas!",
  ui_story_5051_50510802_16_dialog_content = "Oh, ahí estás.",
  ui_story_5051_50510802_17_dialog_content = "Oye, ¿cómo es que es para las resacas?",
  ui_story_5051_50510802_18_dialog_content = "Bueno, todavía estás enyesado y no quieres hablarme claro...",
  ui_story_5051_50510802_19_dialog_content = "Eso es porque acabas de abordarme con los ojos llorosos y me mojaste por todas partes.",
  ui_story_5051_50510802_20_dialog_content = "¡No me importa, quiero alcohol!",
  ui_story_5051_50510802_21_dialog_content = "Bien, bien. Compré eso también. Aquí.",
  ui_story_5051_50510802_22_dialog_content = "*Gulp* ¡Sí, buena bebida! ¡Tiene una buena patada!",
  ui_story_5051_50510802_23_dialog_content = "Entonces, ¿listo para contarme más sobre la adivinación?",
  ui_story_5051_50510802_24_dialog_content = "Claro, ¿qué quieres escuchar?",
  ui_story_5051_50510802_25_dialog_content = "¿Cuánto sabes sobre el hechizo para entrar al Cristal de la Eterna Memoria?",
  ui_story_5051_50510802_26_dialog_content = "¿Por qué los que entraron no solo no eran invisibles, sino que estaban dispersos por todo el mundo?",
  ui_story_5051_50510802_27_dialog_content = "Crystal... ¿Recuerdos eternos...?",
  ui_story_5051_50510802_28_dialog_content = "No es algo que debas saber, pequeña.",
  ui_story_5051_50510802_29_dialog_content = "¿Quién eres en serio?",
  ui_story_5051_50510802_30_dialog_content = "¿No te dije que soy Jakine, ¡¿su hija?!",
  ui_story_5051_50510802_31_dialog_content = "Jakine? ¿Estás bromeando?",
  ui_story_5051_50510802_32_dialog_content = "Es cierto que casi no vuelvo a casa, pero es imposible para Jakine que ni siquiera podía caminar...",
  ui_story_5051_50510802_33_dialog_content = "¡Ser tan alto en un abrir y cerrar de ojos!",
  ui_story_5051_50510802_34_dialog_content = "¡Yo soy el que piensa que todo esto es una broma!",
  ui_story_5051_50510802_35_dialog_content = "Pero mamá, ¿no eres una vidente misteriosa, sorprendente y trascendente?",
  ui_story_5051_50510802_36_dialog_content = "¿Por qué eres un gran borracho?",
  ui_story_5051_50510802_37_dialog_content = "¿A quién llamas gran borracho?",
  ui_story_5051_50510802_38_dialog_content = "Llámame *hipo* una mujer tan inescrutable como el viento del norte—¡Boaz!",
  ui_story_5051_50510802_39_dialog_content = "¿Qué tiene que ver eso con nada?",
  ui_story_5051_50510802_40_dialog_content = "Se supone que no debo decirte esto, pero eres todo lo que tengo ahora.",
  ui_story_5051_50510802_41_dialog_content = "Solo voy a decir esto una vez, ¡así que escucha bien!",
  ui_story_5051_50510802_42_dialog_content = "¿Ah?",
  ui_story_5051_50510802_43_dialog_content = "Mi madre es Booz, y ese eres tú.",
  ui_story_5051_50510802_44_dialog_content = "Tú creaste el Cristal de la Memoria Eterna, en el que nos encontramos en este mismo momento.",
  ui_story_5051_50510802_45_dialog_content = "Doce años a partir de ahora, el activador de Crystal ha fallecido.",
  ui_story_5051_50510802_46_dialog_content = "Para entrar en este mundo, compuse un hechizo de acuerdo con las notas que dejaste atrás.",
  ui_story_5051_50510802_47_dialog_content = "Pero una vez que llegué aquí, no solo no estaba camuflado, sino que me separé de mis amigos...",
  ui_story_5051_50510802_48_dialog_content = "¿Entonces qué hago ahora?",
  ui_story_5051_50510802_49_dialog_content = "Entiendo...",
  ui_story_5051_50510802_50_dialog_content = "¿Así que lo tienes?",
  ui_story_5051_50510802_51_dialog_content = "¡Veo a tu mamá y no solo compartí el mismo nombre, sino que también plagió mi trabajo!",
  ui_story_5051_50510802_52_dialog_content = "Se supone que mi nombre trae suerte a la gente, pero tu madre... no del todo.",
  ui_story_5051_50510802_53_dialog_content = "Por qué tú-",
  ui_story_5051_50510802_54_dialog_content = "¡Báñate como quieras, borracho!",
  ui_story_5051_50510802_55_dialog_content = "Booze ha hecho que te olvides de todo, ¡incluso de mí y de papá! ¡No vuelvas a casa nunca más!",
  ui_story_5051_50510802_56_dialog_content = "No hables con veneno, niña.",
  ui_story_5051_50510802_57_dialog_content = "¿Dijiste que hiciste un hechizo para entrar al cristal de las notas de tu mamá?",
  ui_story_5051_50510802_58_dialog_content = "¿A quién intentas engañar? ¡Ni siquiera yo podría hacer eso!",
  ui_story_5051_50510802_59_dialog_content = "¡Cualquiera que pudiera sería un genio sin precedentes!",
  ui_story_5051_50510802_60_dialog_content = "¿G-genio...?",
  ui_story_5051_50510802_61_dialog_content = "¿Soy un genio sin precedentes?",
  ui_story_5051_50510802_62_dialog_content = "¡Jajaja, si yo fuera tu madre, sería feliz como una almeja!",
  ui_story_5051_50510802_63_dialog_content = "Jeje... ¿Lo harías?",
  ui_story_5051_50510802_64_dialog_content = "¡Espera, ese no es el punto!",
  ui_story_5051_50510802_65_dialog_content = "Quiero saber que hago ahora?!",
  ui_story_5051_50510802_66_dialog_content = "Está bien, recita el hechizo que hiciste para mí.",
  ui_story_5051_50510802_67_dialog_content = "Seguro.",
  ui_story_5051_50510802_68_dialog_content = "¡Ad praeteritum! ¡Ad praeteritum! ¡Ad praeteritum!",
  ui_story_5051_50510802_69_dialog_content = "¡Revivamos los días dorados del pasado!",
  ui_story_5051_50510802_70_dialog_content = "¡Abrahadabra!",
  ui_story_5051_50510802_71_dialog_content = "Eso es.",
  ui_story_5051_50510802_72_dialog_content = "Bueno, lo pronunciaste mal.",
  ui_story_5051_50510802_73_dialog_content = "¿Ah?",
  ui_story_5051_50510802_74_dialog_content = "No \"Abrahadabra\", es \"Abracadabra\".",
  ui_story_5051_50510802_75_dialog_content = "¿Que pasa contigo? ¡Tan descuidado!",
  ui_story_5051_50510802_76_dialog_content = "¡Pero es así en las notas! ¡Ver!",
  ui_story_5051_50510802_77_dialog_content = "Déjame ver... Qué letra tan desordenada.",
  ui_story_5051_50510802_78_dialog_content = "Míralo aquí, incluso se salió del margen. No me extraña que hayas leído mal.",
  ui_story_5051_50510802_79_dialog_content = "¿Lo escribió bajo la influencia?",
  ui_story_5051_50510802_80_dialog_content = "¡Tú eres el que lo escribió!",
  ui_story_5051_50510802_81_dialog_content = "¡Jajajaja!",
  ui_story_5051_50510802_82_dialog_content = "¡Este hechizo no es tan malo en absoluto!",
  ui_story_5051_50510802_83_dialog_content = "Pero aún tienes muchos detalles a tener en cuenta cuando realmente lo lanzas.",
  ui_story_5051_50510802_84_dialog_content = "¿Se tomaron de la mano cuando entraron?",
  ui_story_5051_50510802_85_dialog_content = "No...",
  ui_story_5051_50510802_86_dialog_content = "Con razón no fueron teletransportados juntos.",
  ui_story_5051_50510802_87_dialog_content = "Sin embargo, les dije a todos que no cambiaran este mundo de ninguna manera.",
  ui_story_5051_50510802_88_dialog_content = "Así que eso no debería ser un problema, ¿verdad?",
  ui_story_5051_50510802_89_dialog_content = "Ay no, no, no...",
  ui_story_5051_50510802_90_dialog_content = "Si no estuvieras camuflado, incluso tu respiración podría cambiar el mundo.",
  ui_story_5051_50510802_91_dialog_content = "¿Qué?",
  ui_story_5051_50510802_92_dialog_content = "Si te han notado aquí, todo se ajustará a tu alrededor.",
  ui_story_5051_50510802_93_dialog_content = "Hasta que por fin...",
  ui_story_5051_50510802_94_dialog_content = "¿Hasta por fin qué?",
  ui_story_5051_50510802_95_dialog_content = "Te vuelves parte de este mundo y <color=#FFB400>nunca puede dejar</color>.",
  ui_story_5051_50510802_96_dialog_content = "<size=45>¡¿Qué?!</size>",
  ui_story_5051_50510802_97_dialog_content = "No tan fuerte, no tan fuerte...",
  ui_story_5051_50510802_98_dialog_content = "¿Todavía podemos lograrlo? ¿Cuánto tiempo nos queda?",
  ui_story_5051_50510802_99_dialog_content = "Bueno, el cristal puede almacenar hasta aproximadamente el valor de un día...",
  ui_story_5051_50510802_100_dialog_content = "Entonces, mientras el día no termine, ¡deberías estar bien! Tal vez.",
  ui_story_5051_50510802_101_dialog_content = "¡Aún podemos lograrlo! ¡Tengo que reunirme con todos y salir de aquí!",
  ui_story_5051_50510802_102_dialog_content = "¡Gracias mamá! ¡Adiós, y te llevaré a casa algún día!",
  ui_story_5051_50510802_103_dialog_content = "Oye, espera, ¿adónde vas?",
  ui_story_5051_50510802_104_dialog_content = "¿Qué estás haciendo? ¡No tengo dinero para comprarte alcohol ahora!",
  ui_story_5051_50510802_105_dialog_content = "Has estado tratando de encontrarlos durante toda una mañana, ¿verdad?",
  ui_story_5051_50510802_106_dialog_content = "Y no habrías encontrado a nadie sin mi ayuda.",
  ui_story_5051_50510802_107_dialog_content = "Cierto.",
  ui_story_5051_50510802_108_dialog_content = "Entonces, como tu mamá y yo tenemos el mismo nombre, te daré otro empujón.",
  ui_story_5051_50510802_109_dialog_content = "Te mostraré la técnica adecuada.",
  ui_story_5051_50510802_110_dialog_content = "¡¿En serio?!",
  ui_story_5051_50510802_111_dialog_content = "Sí, en serio. Deberíamos empezar antes de que cambie de opinión.",
  ui_story_5051_50510901_1_dialog_content = "<anim type=Shake><size=32>...</size></anim>",
  ui_story_5051_50510901_2_dialog_content = "<anim type=Shake><size=32>pa...</size></anim>",
  ui_story_5051_50510901_3_dialog_content = "<anim type=Shake><size=32>un...</size></anim>",
  ui_story_5051_50510901_4_dialog_content = "<anim type=Shake><size=32>Daniel...</size></anim>",
  ui_story_5051_50510901_5_dialog_content = "<anim type=Shake><size=32>Verónica... Carleen...</size></anim>",
  ui_story_5051_50510901_6_dialog_content = "<anim type=Shake><size=37>Daniel... Verónica... Carleen...</size></anim>",
  ui_story_5051_50510901_7_dialog_content = "<anim type=Shake><size=42>¡Daniel! ¡Verónica! Carleen!</size></anim>",
  ui_story_5051_50510901_8_dialog_content = "<color=#e8d9bb>¡Retumbar!</color>",
  ui_story_5051_50510901_9_dialog_content = "¡¿Qué?!",
  ui_story_5051_50510901_10_dialog_content = "PlayerName, ¿estás bien?",
  ui_story_5051_50510901_11_dialog_content = "¿Por qué de repente te ves enfermo?",
  ui_story_5051_50510901_12_dialog_content = "N-Nada. El trueno me hizo saltar, eso es todo.",
  ui_story_5051_50510901_13_dialog_content = "¿Tronido?",
  ui_story_5051_50510901_14_dialog_content = "Escuché uno esta mañana, pero este era más fuerte que ese.",
  ui_story_5051_50510901_15_dialog_content = "Tal vez se avecina una tormenta.",
  ui_story_5051_50510901_16_dialog_content = "¿Cómo es que no escuché ningún trueno?",
  ui_story_5051_50510901_17_dialog_content = "¿Qué? ¿No fue lo suficientemente fuerte para que lo escucharas?",
  ui_story_5051_50510901_18_dialog_content = "Incluso si lo hiciera, no tendría miedo.",
  ui_story_5051_50510901_19_dialog_content = "eh, jaja, Carleen... Princesa Carleen verdaderamente es un niño valiente.",
  ui_story_5051_50510901_20_dialog_content = "¡Ya no soy un niño!",
  ui_story_5051_50510901_21_dialog_content = "...",
  ui_story_5051_50510901_22_dialog_content = "¿Carleen?",
  ui_story_5051_50510901_23_dialog_content = "(Corrió de nuevo hacia Lady Joshua.)",
  ui_story_5051_50510901_24_dialog_content = "(La mirada en sus ojos se mantuvo igual que ahora).",
  ui_story_5051_50510901_25_dialog_content = "así es princesa Carleen es. Podría guardarte rencor si la tratas como a una niña.",
  ui_story_5051_50510901_26_dialog_content = "Sin embargo, podrías ser la primera persona en la que se interese.",
  ui_story_5051_50510901_27_dialog_content = "¿Interés?",
  ui_story_5051_50510901_28_dialog_content = "¿No notaste que Su Alteza te ha estado observando durante mucho tiempo?",
  ui_story_5051_50510901_29_dialog_content = "¿Sigue advirtiéndome...?",
  ui_story_5051_50510901_30_dialog_content = "Oh, Mia... Veronica todavía está luchando contra el soldado, ¡tengo que alentarla!",
  ui_story_5051_50510901_31_dialog_content = "¡Esto es lo que puedo hacer!",
  ui_story_5051_50510901_32_dialog_content = "Uf... Tos, tos.",
  ui_story_5051_50510901_33_dialog_content = "La princesa Verónica aún no ha aplicado toda su fuerza, pero está superando a su oponente.",
  ui_story_5051_50510901_34_dialog_content = "Solo han pasado unos días y ha hecho un progreso asombroso.",
  ui_story_5051_50510901_35_dialog_content = "Tengo curiosidad por saber qué has hecho por la princesa Verónica, PlayerName.",
  ui_story_5051_50510901_36_dialog_content = "(Mia casi nunca creyó en sí misma en el camino.)",
  ui_story_5051_50510901_37_dialog_content = "(Entonces, ¿nunca tuvo la reputación de ser una buena luchadora para nadie en el pasado?)",
  ui_story_5051_50510901_38_dialog_content = "¿El tratamiento silencioso? Supongo que es otro de esos secretos que no debo saber.",
  ui_story_5051_50510901_39_dialog_content = "En realidad, no es ningún secreto.",
  ui_story_5051_50510901_40_dialog_content = "Veronica siempre ha sido formidable. Ella simplemente nunca se dio cuenta en el pasado.",
  ui_story_5051_50510901_41_dialog_content = "¿Oh?",
  ui_story_5051_50510901_42_dialog_content = "¡Eso estuvo cerca! La princesa Verónica casi golpea a ese guardia.",
  ui_story_5051_50510901_43_dialog_content = "Puedo ver las chispas de las cuchillas chocando desde aquí... ¡Qué duelo tan genuino!",
  ui_story_5051_50510901_44_dialog_content = "¡Solo te animaremos de ahora en adelante, Princesa Verónica!",
  ui_story_5051_50510901_45_dialog_content = "¡Hurra!",
  ui_story_5051_50510901_46_dialog_content = "La princesa Veronica ha ganado aplausos y vítores con sus habilidades de lucha con espadas.",
  ui_story_5051_50510901_47_dialog_content = "Hablando de eso, ¿confundiste los aplausos con truenos?",
  ui_story_5051_50510901_48_dialog_content = "¿Es así...?",
  ui_story_5051_50510901_49_dialog_content = "(¡Hey, espera!)",
  ui_story_5051_50510901_50_dialog_content = "(¿Por qué siento un escalofrío recorriendo mi columna?)",
  ui_story_5051_50510901_51_dialog_content = "(¡Alguien me está mirando!)",
  ui_story_5051_50510901_52_dialog_content = "(Que no es Carleen, el Señor de la Ciudad o Lady Joshua, quienes están obsesionados con la pelea de su hija).",
  ui_story_5051_50510901_53_dialog_content = "(No me digas que esta vibra es...)",
  ui_story_5051_50510901_54_dialog_content = "¿A dónde vas, PlayerName?",
  ui_story_5051_50510901_55_dialog_content = "Yo, uh, me gustaría usar el baño.",
  ui_story_5051_50510901_56_dialog_content = "Permíteme liderar el camino.",
  ui_story_5051_50510901_57_dialog_content = "Puedo arreglármelas sola, ¡gracias!",
  ui_story_5051_50510901_58_dialog_content = "PlayerName Seguro corre rápido.",
  ui_story_5051_50510901_59_dialog_content = "Este amigo de la princesa Verónica ciertamente es intrigante.",
  ui_story_5051_50510901_60_dialog_content = "La fuente debería estar aquí en alguna parte...",
  ui_story_5051_50510901_61_dialog_content = "Ejem.",
  ui_story_5051_50510901_62_dialog_content = "¡Fuiste tú, Señor de la Ciudad!",
  ui_story_5051_50510901_63_dialog_content = "Eres muy perceptivo, PlayerName.",
  ui_story_5051_50510901_64_dialog_content = "¿Cómo has llegado hasta aquí?",
  ui_story_5051_50510901_65_dialog_content = "A los jóvenes les encantan las celebraciones, así que pensé que te encontraría aquí.",
  ui_story_5051_50510901_66_dialog_content = "Simplemente no pensé que te encontrarías <color=#FFB400>la versión de este mundo de mí</color> muy pronto.",
  ui_story_5051_50510901_67_dialog_content = "Eso es porque...",
  ui_story_5051_50510901_68_dialog_content = "Ya debería saber que estamos involucrados en la historia registrada por el Cristal de la Memoria Eterna.",
  ui_story_5051_50510901_69_dialog_content = "Somos vistos por el mundo del que se supone que estamos ocultos.",
  ui_story_5051_50510901_70_dialog_content = "Eso también me ha estado molestando... ¿Qué salió mal exactamente?",
  ui_story_5051_50510901_71_dialog_content = "Creo que es demasiado tarde para especular sobre eso ahora, joven.",
  ui_story_5051_50510901_72_dialog_content = "Ha ocurrido. Lo urgente es tratar de evitar todos los riesgos potenciales mientras se busca una solución.",
  ui_story_5051_50510901_73_dialog_content = "Jakine dijo no intentar cambiar la historia en el Cristal o enfrentar consecuencias potencialmente graves.",
  ui_story_5051_50510901_74_dialog_content = "Para mantener las cosas en orden en este mundo, debemos mantener un perfil bajo.",
  ui_story_5051_50510901_75_dialog_content = "Mia y tuve que venir a la ciudad a buscar a los demás...",
  ui_story_5051_50510901_76_dialog_content = "...",
  ui_story_5051_50510901_77_dialog_content = "¿Por qué frunces el ceño, señor de la ciudad?",
  ui_story_5051_50510901_78_dialog_content = "Hizo Mia ¿reunirse con ellos?",
  ui_story_5051_50510901_79_dialog_content = "Ellos como en...?",
  ui_story_5051_50510901_80_dialog_content = "Ya sabes a quién me refiero.",
  ui_story_5051_50510901_81_dialog_content = "Ejem. Si te refieres a Lady Joshua, joven Carleen, y el Señor de este mundo Schwartz...",
  ui_story_5051_50510901_82_dialog_content = "Sí, se conocieron y aceptaron. Mia, incluso llamándola Verónica.",
  ui_story_5051_50510901_83_dialog_content = "De hecho, la apariencia de Mia se ha mantenido igual que en ese entonces.",
  ui_story_5051_50510901_84_dialog_content = "Entonces... ¿Lo estás admitiendo?",
  ui_story_5051_50510901_85_dialog_content = "Eso Mia ¿La princesa Verónica es tu hija?",
  ui_story_5051_50510901_86_dialog_content = "Nuestra acción ha perturbado este reino.",
  ui_story_5051_50510901_87_dialog_content = "Y tú... ¿Por qué pusiste en peligro Mia al permitirle batirse en duelo con el guardia?",
  ui_story_5051_50510901_88_dialog_content = "¿Alguna vez has considerado las ramificaciones si ella está herida?",
  ui_story_5051_50510901_89_dialog_content = "Como hija del señor de la ciudad de Lumopolis, Mia se ha escondido en Umbraton.",
  ui_story_5051_50510901_90_dialog_content = "¿Ha considerado alguna vez su padre las ramificaciones si Mia ¿Se lastimó en Umbraton?",
  ui_story_5051_50510901_91_dialog_content = "Recuerda esto, joven.",
  ui_story_5051_50510901_92_dialog_content = "Si no conoce todas las facetas de una historia, no juzgue prematuramente.",
  ui_story_5051_50510901_93_dialog_content = "Lo siento. Lo confieso, no tengo idea de lo que pasó entre ustedes.",
  ui_story_5051_50510901_94_dialog_content = "Pero tampoco creo que te hayas dado cuenta del verdadero potencial de Mia.",
  ui_story_5051_50510901_95_dialog_content = "¿Qué?",
  ui_story_5051_50510901_96_dialog_content = "¡Buen movimiento!",
  ui_story_5051_50510901_97_dialog_content = "¡Princesa Verónica! ¡Princesa Verónica! ¡Princesa Verónica!",
  ui_story_5051_50510901_98_dialog_content = "Mira, la lucha con espadas de Mia se ha ganado el reconocimiento y los aplausos de la gente.",
  ui_story_5051_50510901_99_dialog_content = "El Mia Solía saber que nunca podría pelear.",
  ui_story_5051_50510901_100_dialog_content = "Pero ahora se ha vuelto muy formidable en combate...",
  ui_story_5051_50510901_101_dialog_content = "Mia quería aprovechar esta oportunidad para mostrarle a su padre que podía lograr más.",
  ui_story_5051_50510901_102_dialog_content = "Sin embargo, ahora no es el momento adecuado.",
  ui_story_5051_50510901_103_dialog_content = "Debemos terminar este partido para Mia rápidamente, PlayerName.",
  ui_story_5051_50510901_104_dialog_content = "¿Por qué? no lo entiendo Mia está a punto de ganar.",
  ui_story_5051_50510901_105_dialog_content = "¿Todavía no crees en ella?",
  ui_story_5051_50510901_106_dialog_content = "¿Sabes lo que pasó en la ceremonia de ese año, PlayerName?",
  ui_story_5051_50510901_107_dialog_content = "¿Ah?",
  ui_story_5051_50510901_108_dialog_content = "¡Estoy a punto de dar todo lo que tengo ahora, Princesa Verónica!",
  ui_story_5051_50510901_109_dialog_content = "Entiendo. Por favor, no retengas nada.",
  ui_story_5051_50510901_110_dialog_content = "¡Hola!",
  ui_story_5051_50510901_111_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_5051_50510901_112_dialog_content = "¿Qué... incluso bloqueaste eso?",
  ui_story_5051_50510901_113_dialog_content = "Tuve suerte.",
  ui_story_5051_50510901_114_dialog_content = "(Él puso tanto detrás del golpe que apenas luché contra él).",
  ui_story_5051_50510901_115_dialog_content = "(Me pregunto si PlayerName ¿ví eso?)",
  ui_story_5051_50510901_116_dialog_content = "(Oye, ¿dónde está PlayerName?)",
  ui_story_5051_50510901_117_dialog_content = "(¡Te tengo! Pero la persona al lado...)",
  ui_story_5051_50510901_118_dialog_content = "¡Cuidado, Verónica!",
  ui_story_5051_50510901_119_dialog_content = "¡Hola!",
  ui_story_5051_50510901_120_dialog_content = "(¿Y ahora qué? N-no creo que pueda con este.)",
  ui_story_5051_50510901_121_dialog_content = "(¿Huir? N-De ninguna manera, no cuando Padre está mirando...)",
  ui_story_5051_50510901_122_dialog_content = "(¡Todavía tengo tiempo para cargar para un contraataque!)",
  ui_story_5051_50510901_123_dialog_content = "ella va a soltar <color=#FFB400>esa cosa</color>?",
  ui_story_5051_50510901_124_dialog_content = "Verónica...",
  ui_story_5051_50510901_125_dialog_content = "(No, ¿cómo puedo olvidar el hecho de que Padre no quiere que invoque a Hippoca...)",
  ui_story_5051_50510901_126_dialog_content = "(Pero, ¿qué pasa con la energía que ya cargué? Terminará lastimando al guardia).",
  ui_story_5051_50510901_127_dialog_content = "(¿Que hacer que hacer?)",
  ui_story_5051_50510901_128_dialog_content = "(¿Qué son esas cajas de ahí? ¡Tal vez puedan soportar la fuerza!)",
  ui_story_5051_50510901_129_dialog_content = "¿Qué está pasando?, ¿Por qué? Mia corriendo hacia un lado?",
  ui_story_5051_50510901_130_dialog_content = "¡Otro segundo y habría invocado con su Lumina!",
  ui_story_5051_50510901_131_dialog_content = "...",
  ui_story_5051_50510901_132_dialog_content = "Nunca convoques a ese monstruo en público de ahora en adelante, Veronica.",
  ui_story_5051_50510901_133_dialog_content = "Hippoca no es un monstruo.",
  ui_story_5051_50510901_134_dialog_content = "¿Le pusiste nombre a esa araña con cabeza de caballo?",
  ui_story_5051_50510901_135_dialog_content = "No Carleen ¿Tienes un caballo también?",
  ui_story_5051_50510901_136_dialog_content = "No tienes talento para pelear, Verónica. No discutas más sobre eso.",
  ui_story_5051_50510901_137_dialog_content = "Suspiro...",
  ui_story_5051_50510901_138_dialog_content = "Parece que ella todavía recuerda eso.",
  ui_story_5051_50510901_139_dialog_content = "Mia está chocando contra esas cajas!",
  ui_story_5051_50510901_140_dialog_content = "¿¡Qué!?",
  ui_story_5051_50510901_141_dialog_content = "<color=#e8d9bb>¡Ruido!</color>",
  ui_story_5051_50510901_142_dialog_content = "<anim type=Shake>Grahhh!</anim>",
  ui_story_5051_50510901_143_dialog_content = "¿Eclipsitos? ¡Hay eclipses!",
  ui_story_5051_50510901_144_dialog_content = "¿Por qué hay tantos eclipses escondidos en esas cajas de fondo?",
  ui_story_5051_50510901_145_dialog_content = "¡Correr! ¡Correr!",
  ui_story_5051_50510901_146_dialog_content = "Ah, ¿qué está pasando aquí?",
  ui_story_5051_50510901_147_dialog_content = "¿Es por mi culpa?",
  ui_story_5051_50510901_148_dialog_content = "<anim type=Shake>¡Gahhhh!</anim>",
  ui_story_5051_50510901_149_dialog_content = "Sabía que no debería tratar de presumir aquí...",
  ui_story_5051_50510901_150_dialog_content = "Esto es lo que sucedería cuando lo intentara.",
  ui_story_5051_50510901_151_dialog_content = "Nunca termina bien...",
  ui_story_5051_50510901_152_dialog_content = "¿Unirse a Lumo Knights? ¡No espero que destaques, Verónica, solo que no preocupes a tu madre!",
  ui_story_5051_50510901_153_dialog_content = "Por favor, no nos siga a la batalla, Su Alteza. ¡Solo quédate donde sea seguro!",
  ui_story_5051_50510901_154_dialog_content = "¿Qué pasa, Verónica?",
  ui_story_5051_50510901_155_dialog_content = "¡No!",
  ui_story_5051_50510901_156_dialog_content = "Todo es por mi culpa que...",
  ui_story_5051_50510901_157_dialog_content = "¡Cuidado! ¡Paso atrás!",
  ui_story_5051_50510901_158_dialog_content = "¿Ah?",
  ui_story_5051_50510901_159_dialog_content = "<anim type=Shake>Grahhhhhh!</anim>",
  ui_story_5051_50510901_160_dialog_content = "¡La Espada del Soberano!",
  ui_story_5051_50510901_161_dialog_content = "¿Padre? ¿E-El verdadero padre?",
  ui_story_5051_50510901_162_dialog_content = "¿Estás bien, Mia?",
  ui_story_5051_50510901_163_dialog_content = "Estoy bien, PlayerName, solo se distrajo un poco.",
  ui_story_5051_50510901_164_dialog_content = "¿Estás seguro de que estás bien?",
  ui_story_5051_50510901_165_dialog_content = "¡Estoy bien!",
  ui_story_5051_50510901_166_dialog_content = "Muy bien, vamos a cargar.",
  ui_story_5051_50510901_167_dialog_content = "Esta es la primera vez que luchas a mi lado, padre.",
  ui_story_5051_50510901_168_dialog_content = "Y...",
  ui_story_5051_50510901_169_dialog_content = "Si desea invocar a Hippoca, adelante.",
  ui_story_5051_50510901_170_dialog_content = "¿Padre?",
  ui_story_5051_50510901_171_dialog_content = "¿Listo?",
  ui_story_5051_50510901_172_dialog_content = "Cierto.",
  ui_story_5051_50510901_173_dialog_content = "<color=#e8d9bb>Por otro lado</color>",
  ui_story_5051_50510901_174_dialog_content = "Esos monstruos negros... ¿Son Eclipsitas?",
  ui_story_5051_50510901_175_dialog_content = "¡Yo también puedo protegernos, Madre!",
  ui_story_5051_50510901_176_dialog_content = "Creo que tienes la habilidad, Carleen, pero ahora no es el momento, ¿de acuerdo?",
  ui_story_5051_50510901_177_dialog_content = "...Okey.",
  ui_story_5051_50510901_178_dialog_content = "La Sra. Rot cubrirá el retiro tuyo y de Carleen, Joshua. ¡Ve ahora!",
  ui_story_5051_50510901_179_dialog_content = "Daniel, yo puedo...",
  ui_story_5051_50510901_180_dialog_content = "No te preocupes, Josué.",
  ui_story_5051_50510901_181_dialog_content = "Traeré a Veronica de vuelta sana y salva.",
  ui_story_5051_50510901_182_dialog_content = "Quiero verlos a ambos en casa ilesos.",
  ui_story_5051_50510901_183_dialog_content = "<anim type=Shake>Grahhh!</anim>",
  ui_story_5051_50510901_184_dialog_content = "¡Un tajo de soberano!",
  ui_story_5051_50510901_185_dialog_content = "Veo que estas criaturas se han extendido hasta aquí ahora.",
  ui_story_5051_50510901_186_dialog_content = "Bueno, solo lo estás pidiendo.",
  ui_story_5051_50511001_1_dialog_content = "¡Invenir eum! ¡Invenir eum! ¡Invenir eum!",
  ui_story_5051_50511001_2_dialog_content = "Por favor, dime, ¿dónde está el Señor de la Ciudad en el que estoy pensando en este momento?",
  ui_story_5051_50511001_3_dialog_content = "<size=42>¡Abracadabra!</size>",
  ui_story_5051_50511001_4_dialog_content = "<color=#e8d9bb>¡Zumbido!</color>",
  ui_story_5051_50511001_5_dialog_content = "¡Vaya, esta es la primera vez que mi bola de cristal responde tan intensamente!",
  ui_story_5051_50511001_6_dialog_content = "Supongo que nunca antes dije correctamente el encantamiento final...",
  ui_story_5051_50511001_7_dialog_content = "Pero tengo mucha curiosidad...",
  ui_story_5051_50511001_8_dialog_content = "¿Por qué \"Abracadabra\" tiene que ir siempre al final?",
  ui_story_5051_50511001_9_dialog_content = "¿\"Abracadabra\" tiene algún significado especial?",
  ui_story_5051_50511001_10_dialog_content = "¿Eh? Oh, ¿qué es de nuevo...",
  ui_story_5051_50511001_11_dialog_content = "¡Sí, ahora lo recuerdo!",
  ui_story_5051_50511001_12_dialog_content = "\"¡Te destruiré si no obedeces!\"",
  ui_story_5051_50511001_13_dialog_content = "¡¿Qué?!",
  ui_story_5051_50511001_14_dialog_content = "¡Jajajaja, te veías tan asustado! ¡Esto es divertido!",
  ui_story_5051_50511001_15_dialog_content = "¿Te estás burlando de mi?",
  ui_story_5051_50511001_16_dialog_content = "<size=30>¿Me imaginé la amabilidad de mi madre cuando yo era un niño solo?</size>",
  ui_story_5051_50511001_17_dialog_content = "¡Deja de murmurar! Vas a perder el mensaje si no hablas pronto con esa bola de cristal.",
  ui_story_5051_50511001_18_dialog_content = "¡Oh, casi lo olvido!",
  ui_story_5051_50511001_19_dialog_content = "La bola de cristal dice...",
  ui_story_5051_50511001_20_dialog_content = "Caballero Schwartz es donde PlayerName y Mia ¿son?",
  ui_story_5051_50511001_21_dialog_content = "Así que ya se han encontrado.",
  ui_story_5051_50511001_22_dialog_content = "¡Eso significa que he perdido todo este tiempo contigo!",
  ui_story_5051_50511001_23_dialog_content = "¿Cómo podría ser esto una pérdida de tiempo?",
  ui_story_5051_50511001_24_dialog_content = "¡Te enseñé mis secretos!",
  ui_story_5051_50511001_25_dialog_content = "¡Ah, sí, tienes razón!",
  ui_story_5051_50511001_26_dialog_content = "¡Y esta es la primera vez que averiguo el paradero de alguien con precisión!",
  ui_story_5051_50511001_27_dialog_content = "Pero...",
  ui_story_5051_50511001_28_dialog_content = "¿Puedes decirme qué significa realmente \"Abracadabra\" ahora?",
  ui_story_5051_50511001_29_dialog_content = "¡Ay, eso duele, me duele la cabeza!",
  ui_story_5051_50511001_30_dialog_content = "Necesito un par de tragos más para calmarme y recordarme.",
  ui_story_5051_50511001_31_dialog_content = "Tirando de eso otra vez?",
  ui_story_5051_50511001_32_dialog_content = "Debería estar bien aquí, ¿verdad?",
  ui_story_5051_50511001_33_dialog_content = "Deberíamos movernos un poco más para estar seguros. ¡Avanza!",
  ui_story_5051_50511001_34_dialog_content = "Oye, ¿por qué todos huyen de la plaza?",
  ui_story_5051_50511001_35_dialog_content = "¡Mantén la calma, no tropieces y caigas!",
  ui_story_5051_50511001_36_dialog_content = "Disculpe-",
  ui_story_5051_50511001_37_dialog_content = "¿Qué?",
  ui_story_5051_50511001_38_dialog_content = "¡Vaya, pareces más joven que yo!",
  ui_story_5051_50511001_39_dialog_content = "¿Qué puedo hacer por ti?",
  ui_story_5051_50511001_40_dialog_content = "Oh, me pregunto qué pasó en la plaza.",
  ui_story_5051_50511001_41_dialog_content = "Nada específico todavía, pero me ordenaron dirigir una evacuación.",
  ui_story_5051_50511001_42_dialog_content = "¡Pero las personas que estoy buscando todavía están allí!",
  ui_story_5051_50511001_43_dialog_content = "Espera un minuto, tu apariencia...",
  ui_story_5051_50511001_44_dialog_content = "Oh, todos me dijeron que me parecía a mi mamá... Uh, quiero decir, Boaz.",
  ui_story_5051_50511001_45_dialog_content = "Largo cabello rojo y ojos verdes... ¿Eres Jakine?",
  ui_story_5051_50511001_46_dialog_content = "¿Como sabes mi nombre?",
  ui_story_5051_50511001_47_dialog_content = "¡Espera, espera, espera, no me digas que te traje aquí por error también!",
  ui_story_5051_50511001_48_dialog_content = "Perdóname, no entiendo de lo que estás hablando.",
  ui_story_5051_50511001_49_dialog_content = "Sin embargo, la amiga de la princesa Verónica, PlayerName, nos pidió que lo cuidáramos a usted y a otros dos señores.",
  ui_story_5051_50511001_50_dialog_content = "Sí, estoy tratando de encontrar PlayerName ¡también!",
  ui_story_5051_50511001_51_dialog_content = "Pero el tipo probablemente todavía esté en la plaza central.",
  ui_story_5051_50511001_52_dialog_content = "Ven conmigo ahora. Cuando todo se calme, te llevaré a PlayerName.",
  ui_story_5051_50511001_53_dialog_content = "Aprecio los pensamientos, pero...",
  ui_story_5051_50511001_54_dialog_content = "¡Me estoy quedando sin tiempo y tengo que reunirme con todos!",
  ui_story_5051_50511001_55_dialog_content = "¿Así que vas a atravesar las masas de Eclipsites, con una dama perdida a cuestas?",
  ui_story_5051_50511001_56_dialog_content = "¿Eclipsites?",
  ui_story_5051_50511001_57_dialog_content = "¡No, estás perdido!",
  ui_story_5051_50511001_58_dialog_content = "Bueno, eso es bastante problemático.",
  ui_story_5051_50511001_59_dialog_content = "¿Puedes cuidar a esta dama, entonces?",
  ui_story_5051_50511001_60_dialog_content = "¿Vas a intentar encontrarlos por ti mismo?",
  ui_story_5051_50511001_61_dialog_content = "No me juzgues por mi apariencia. Los eclipses no son nada para mí.",
  ui_story_5051_50511001_62_dialog_content = "¿Crees que puedes dejarme atrás después de lo que aprendiste de mí?",
  ui_story_5051_50511001_63_dialog_content = "¿Crees que yo, Booz, tengo miedo de los eclipses?",
  ui_story_5051_50511001_64_dialog_content = "Gracias por enseñarme el conjuro correcto.",
  ui_story_5051_50511001_65_dialog_content = "Aunque solo estamos juntos brevemente, realmente aprecio el tiempo, y si es posible...",
  ui_story_5051_50511001_66_dialog_content = "No quisiera dejarte ahora.",
  ui_story_5051_50511001_67_dialog_content = "¡Pero no puedo abandonar a mis amigos!",
  ui_story_5051_50511001_68_dialog_content = "No estarían en este lío si no fuera por mí.",
  ui_story_5051_50511001_69_dialog_content = "No entiendo una sola palabra. ¡Solo llévame contigo, debes hacerlo!",
  ui_story_5051_50511001_70_dialog_content = "¿No quieres que te enseñe más? ¡Y todavía necesito más alcohol!",
  ui_story_5051_50511001_71_dialog_content = "...",
  ui_story_5051_50511001_72_dialog_content = "Te respeto por pensar en tus amigos en esta situación, Jakine.",
  ui_story_5051_50511001_73_dialog_content = "Para ser honesto, me gustaría ayudar con la batalla en la plaza.",
  ui_story_5051_50511001_74_dialog_content = "Si insistes en ir, puedo llevarte.",
  ui_story_5051_50511001_75_dialog_content = "¿En serio?",
  ui_story_5051_50511001_76_dialog_content = "¡Sígueme, limpiaré los Eclipsites por ti!",
  ui_story_5051_50511002_1_dialog_content = "¿Cómo se ve?",
  ui_story_5051_50511002_2_dialog_content = "La vecindad debería estar libre de eclipses ahora.",
  ui_story_5051_50511002_3_dialog_content = "Excelente.",
  ui_story_5051_50511002_4_dialog_content = "Allí hay un atajo para salir rápidamente de las áreas invadidas.",
  ui_story_5051_50511002_5_dialog_content = "Ustedes dos, síganme.",
  ui_story_5051_50511002_6_dialog_content = "¿Nos vamos ahora?",
  ui_story_5051_50511002_7_dialog_content = "Has luchado lo suficiente y necesitas descansar.",
  ui_story_5051_50511002_8_dialog_content = "Pero...",
  ui_story_5051_50511002_9_dialog_content = "Sin peros.",
  ui_story_5051_50511002_10_dialog_content = "No podemos desperdiciar demasiado tiempo o energía aquí.",
  ui_story_5051_50511002_11_dialog_content = "Quiero ayudar a limpiar los eclipses...",
  ui_story_5051_50511002_12_dialog_content = "<size=45>¡Deja de preocuparte por eso, date prisa y vete!</size>",
  ui_story_5051_50511002_13_dialog_content = "¿Ah?",
  ui_story_5051_50511002_14_dialog_content = "No tienes talento para pelear, Verónica. No discutas más sobre eso.",
  ui_story_5051_50511002_15_dialog_content = "Mmm...",
  ui_story_5051_50511002_X15_dialog_content = "(Mia tiene el mismo comportamiento que antes del duelo.)",
  ui_story_5051_50511002_X16_dialog_content = "(¿Se acuerda de algo desagradable en el pasado otra vez?)",
  ui_story_5051_50511002_16_dialog_content = "Qué tienes en mente, Mia?",
  ui_story_5051_50511002_17_dialog_content = "¡Lo siento!",
  ui_story_5051_50511002_18_dialog_content = "Todo es mi culpa...",
  ui_story_5051_50511002_19_dialog_content = "¿Acabas de enloquecer? Mia ¿Fuera lo que dijiste, Señor de la Ciudad?",
  ui_story_5051_50511002_20_dialog_content = "Recientemente mejoró y eso probablemente fue demasiado para ella.",
  ui_story_5051_50511002_21_dialog_content = "...",
  ui_story_5051_50511002_22_dialog_content = "Todavía no puedo estar a la altura de las expectativas de mi padre.",
  ui_story_5051_50511002_23_dialog_content = "No merezco ser su hijo, no lo merezco...",
  ui_story_5051_50511002_X21_dialog_content = "Admito que no debería indagar en tus asuntos familiares.",
  ui_story_5051_50511002_X22_dialog_content = "¡Pero no es normal que un niño tenga tanto miedo de su propio padre!",
  ui_story_5051_50511002_24_dialog_content = "Por que es Mia tan aterrorizado de ti?",
  ui_story_5051_50511002_25_dialog_content = "¿Es porque...",
  ui_story_5051_50511002_26_dialog_content = "tu abandonaste Mia en Umbraton y la descuidó durante todos estos años?",
  ui_story_5051_50511002_27_dialog_content = "¡Nunca la he abandonado ni por un día!",
  ui_story_5051_50511002_28_dialog_content = "No es necesario conocer los detalles.",
  ui_story_5051_50511002_X28_dialog_content = "No tienes derecho a juzgar a mi familia.",
  ui_story_5051_50511002_X29_dialog_content = "Por favor, no seas tan malo con PlayerName, Padre...",
  ui_story_5051_50511002_X30_dialog_content = "Tranquilo, sé lo que hago.",
  ui_story_5051_50511002_X31_dialog_content = "No, no puedes ser tan malo con PlayerName...!",
  ui_story_5051_50511002_X32_dialog_content = "Mia...?",
  ui_story_5051_50511002_X33_dialog_content = "Señor de Lumopolis, guardián de la casa... Tienes muchos títulos impresionantes.",
  ui_story_5051_50511002_X34_dialog_content = "Pero todos ellos sólo me asfixian.",
  ui_story_5051_50511002_X35_dialog_content = "Tal vez otros te vean majestuoso y sublime.",
  ui_story_5051_50511002_X36_dialog_content = "Pero para mí, siempre eres malo y siempre lastimas a los que te rodean...",
  ui_story_5051_50511002_X37_dialog_content = "...",
  ui_story_5051_50511002_29_dialog_content = "Admito que no debería indagar en tus asuntos familiares.",
  ui_story_5051_50511002_30_dialog_content = "Pero yo pienso Mia necesita una respuesta más que yo!",
  ui_story_5051_50511002_31_dialog_content = "...",
  ui_story_5051_50511002_32_dialog_content = "Todo es mi culpa, soy una carga para todos...",
  ui_story_5051_50511002_33_dialog_content = "Escúchame, Mia, eso no es cierto en absoluto!",
  ui_story_5051_50511002_34_dialog_content = "No tienes que consolarme. Soy un gafe que pone en peligro a todos.",
  ui_story_5051_50511002_35_dialog_content = "Si no rompiera esas cajas, los Eclipsites no habrían salido...",
  ui_story_5051_50511002_36_dialog_content = "No, los conspiradores los escondieron allí, ¡no tenía nada que ver contigo!",
  ui_story_5051_50511002_37_dialog_content = "Todo lo contrario, has estado ayudando, Mia!",
  ui_story_5051_50511002_38_dialog_content = "he estado ayudando?",
  ui_story_5051_50511002_39_dialog_content = "Fuiste tú quien me salvó de los eclipses fuera de la ciudad.",
  ui_story_5051_50511002_40_dialog_content = "También fuiste tú quien rechazó a los Eclipsites que intentaban infiltrarse en la ciudad por la puerta.",
  ui_story_5051_50511002_41_dialog_content = "Y justo ahora, salvaste a mucha gente inocente de esos monstruos.",
  ui_story_5051_50511002_42_dialog_content = "¿No prueba todo eso lo capaz que eres, Mia?",
  ui_story_5051_50511002_43_dialog_content = "Son solo coincidencias... Solo tuve suerte.",
  ui_story_5051_50511002_44_dialog_content = "Mia... ¿Qué puedo decir para que me creas?",
  ui_story_5051_50511002_45_dialog_content = "Eres mucho más sabio que yo, Señor de la Ciudad.",
  ui_story_5051_50511002_46_dialog_content = "Así que debes tener más que decirle a Mia, ¿bien?",
  ui_story_5051_50511002_47_dialog_content = "...",
  ui_story_5051_50511002_X38_dialog_content = "E-Eso es lo que realmente pienso.",
  ui_story_5051_50511002_X39_dialog_content = "¡Si eso te hace enojar, ven a mí, no a mi amigo...!",
  ui_story_5051_50511002_48_dialog_content = "Mmm...",
  ui_story_5051_50511002_49_dialog_content = "¿Tienes miedo?",
  ui_story_5051_50511002_50_dialog_content = "Yo... no diré que tengo miedo.",
  ui_story_5051_50511002_51_dialog_content = "Como tu hijo mayor, debo hacer todo lo posible para no decepcionarte.",
  ui_story_5051_50511002_52_dialog_content = "Ya sea la música y el arte que amo, o la pericia política y de lucha de la que tanto carezco...",
  ui_story_5051_50511002_53_dialog_content = "Debo sobresalir en todo.",
  ui_story_5051_50511002_54_dialog_content = "Has sobresalido lo suficiente, hijo mío.",
  ui_story_5051_50511002_55_dialog_content = "Pero todavía no podía quitarme ningún peso de encima.",
  ui_story_5051_50511002_56_dialog_content = "Lo recuerdo ahora, lo recuerdo todo ahora.",
  ui_story_5051_50511002_57_dialog_content = "Una vez reuní el coraje para unirme a los caballeros, pero Eclipsites me hirió rápidamente.",
  ui_story_5051_50511002_58_dialog_content = "Fue Madre quien me salvó entonces, ¿verdad?",
  ui_story_5051_50511002_59_dialog_content = "No logré nada más que crear más problemas.",
  ui_story_5051_50511002_60_dialog_content = "¿Y no es eso lo que acabo de hacer?",
  ui_story_5051_50511002_61_dialog_content = "De lo contrario, no te enfadarías conmigo ni querrías que me fuera.",
  ui_story_5051_50511002_X61_dialog_content = "Estás enojado porque he sido completamente inútil, ¿es así...?",
  ui_story_5051_50511002_62_dialog_content = "Esa no fue mi intención, Mia.",
  ui_story_5051_50511002_63_dialog_content = "me vas a enviar <color=#FFB400>Algún lugar lejano</color> ¿de nuevo?",
  ui_story_5051_50511002_64_dialog_content = "!!!",
  ui_story_5051_50511002_65_dialog_content = "Enviarte de forma anónima a Umbraton para recibir tratamiento fue una decisión que tuve que tomar.",
  ui_story_5051_50511002_66_dialog_content = "Pero lo admito, yo era demasiado joven entonces.",
  ui_story_5051_50511002_67_dialog_content = "Si pudiera rehacerlo, definitivamente encontraría una mejor manera de manejar todo.",
  ui_story_5051_50511002_68_dialog_content = "Es inútil decir eso ahora, pero no importa qué... esa fue una de las peores decisiones que he tomado.",
  ui_story_5051_50511002_69_dialog_content = "Lamento las dificultades que tuviste que soportar durante todos estos años...",
  ui_story_5051_50511002_70_dialog_content = "Padre...",
  ui_story_5051_50511002_71_dialog_content = "Echaba de menos a mamá y Carleen tanto... Y tú también.",
  ui_story_5051_50511002_72_dialog_content = "Lo sé, hijo mío.",
  ui_story_5051_50511002_73_dialog_content = "Mientras estés en Umbraton, Istvan Me informabas de ti constantemente.",
  ui_story_5051_50511002_74_dialog_content = "Sabía que estabas mejorando, y quizás algún día te explique todo.",
  ui_story_5051_50511002_75_dialog_content = "Nunca pensé que llegaría a esto...",
  ui_story_5051_50511002_76_dialog_content = "Te prometo que diré la verdad después de que salgamos. Pero ahora nuestra prioridad es salir de aquí.",
  ui_story_5051_50511002_77_dialog_content = "yo... eh...",
  ui_story_5051_50511002_79_dialog_content = "P-Pero si nos vamos, ¿no significa eso que nunca volveré a ver a mamá?",
  ui_story_5051_50511002_80_dialog_content = "...",
  ui_story_5051_50511002_81_dialog_content = "¿Fue por mi culpa?",
  ui_story_5051_50511002_82_dialog_content = "¿Ella falleció por mi culpa?",
  ui_story_5051_50511002_83_dialog_content = "Hablaremos de eso más tarde, niña.",
  ui_story_5051_50511002_84_dialog_content = "Primero debemos irnos de aquí.",
  ui_story_5051_50511002_85_dialog_content = "¿Déjalo aqui?",
  ui_story_5051_50511002_86_dialog_content = "No deseo que te pase nada malo, ¿de acuerdo?",
  ui_story_5051_50511002_87_dialog_content = "OK...",
  ui_story_5051_50511002_88_dialog_content = "¿Puede usted ponerse de pie?",
  ui_story_5051_50511002_89_dialog_content = "Dame tu mano y vamos juntos.",
  ui_story_5051_50511002_90_dialog_content = "<color=#e8d9bb>¡Whoosh!</color>",
  ui_story_5051_50511002_91_dialog_content = "¿Qué?",
  ui_story_5051_50511002_92_dialog_content = "¿Que esta pasando aqui?",
  ui_story_5051_50511002_93_dialog_content = "¡Padre!",
  ui_story_5051_50511002_94_dialog_content = "Mantente alejada de él, Verónica.",
  ui_story_5051_50511002_95_dialog_content = "¡No te acerques a este bandido que te está secuestrando!",
  ui_story_5051_50511002_96_dialog_content = "...",
  ui_story_5051_50511002_97_dialog_content = "(El joven Schwartz ¡no reconoció que se está enfrentando a sí mismo!)",
  ui_story_5051_50511002_98_dialog_content = "(Comprensible, aunque...)",
  ui_story_5051_50511002_99_dialog_content = "(Si no supiera la verdad, no creería que estos dos son la misma persona).",
  ui_story_5051_50511002_100_dialog_content = "Si tienes el descaro de secuestrar a una hija de Schwartz...",
  ui_story_5051_50511002_101_dialog_content = "¿Por qué no tienes el coraje de pelear conmigo ahora?",
  ui_story_5051_50511002_102_dialog_content = "No quiero causar ninguna confrontación innecesaria.",
  ui_story_5051_50511002_103_dialog_content = "¿Confrontación innecesaria?",
  ui_story_5051_50511002_104_dialog_content = "No creo haberte conocido.",
  ui_story_5051_50511002_105_dialog_content = "¿Eres un troyano? No, no pareces uno.",
  ui_story_5051_50511002_106_dialog_content = "Entonces, ¿debes ser un Kartima?",
  ui_story_5051_50511002_107_dialog_content = "Ni. Soy de Verónica...",
  ui_story_5051_50511002_108_dialog_content = "Amigo.",
  ui_story_5051_50511002_109_dialog_content = "¿Amigo?",
  ui_story_5051_50511002_110_dialog_content = "Amigo de un amigo, pero sin embargo amigo.",
  ui_story_5051_50511002_111_dialog_content = "Interesante, aunque solo he oído hablar de \"El enemigo de mi enemigo es mi amigo\".",
  ui_story_5051_50511002_112_dialog_content = "Bien ahora lo sabes.",
  ui_story_5051_50511002_113_dialog_content = "Tu tono sugiere que no estás dispuesto a ser mi amigo.",
  ui_story_5051_50511002_114_dialog_content = "De hecho es... un amigo mío de Umbraton, padre.",
  ui_story_5051_50511002_115_dialog_content = "Él también me ayudó hace un momento.",
  ui_story_5051_50511002_116_dialog_content = "Momento peculiar para que él aparezca junto a los Eclipsites.",
  ui_story_5051_50511002_117_dialog_content = "Tal vez demasiada coincidencia.",
  ui_story_5051_50511002_118_dialog_content = "Deja que tu madre filtre con quién eres amiga a partir de ahora, Veronica.",
  ui_story_5051_50511002_119_dialog_content = "...",
  ui_story_5051_50511002_120_dialog_content = "(Ejem, Schwartz debe estar furioso con su yo más joven ahora.)",
  ui_story_5051_50511002_121_dialog_content = "(Pero esto simplemente no puede continuar...)",
  ui_story_5051_50511002_122_dialog_content = "(Y no podemos simplemente decirles a los jóvenes Schwartz, \"Este eres tú dentro de una docena de años\").",
  ui_story_5051_50511002_123_dialog_content = "(Solo una carta que puedo jugar ahora...)",
  ui_story_5051_50511002_124_dialog_content = "En realidad...",
  ui_story_5051_50511002_125_dialog_content = "¿Qué?",
  ui_story_5051_50511002_126_dialog_content = "Por favor, perdóname, Señor de la Ciudad.",
  ui_story_5051_50511002_127_dialog_content = "En realidad es... mi padre, em, Soroz.",
  ui_story_5051_50511002_128_dialog_content = "No le informé que vendría a Lumopolis con la princesa Veronica.",
  ui_story_5051_50511002_129_dialog_content = "Por eso pidió a otros que vinieran a buscarme aquí.",
  ui_story_5051_50511002_130_dialog_content = "No esperaba encontrarme con Eclipsites tan pronto como nos conocimos.",
  ui_story_5051_50511002_131_dialog_content = "¡Sí!",
  ui_story_5051_50511002_132_dialog_content = "Sí. Mira, una confrontación innecesaria como dije.",
  ui_story_5051_50511002_133_dialog_content = "Aunque debo agradecerte a ti y a tu familia por cuidar PlayerName.",
  ui_story_5051_50511002_134_dialog_content = "Si ese es el caso, de hecho lo entendí mal.",
  ui_story_5051_50511002_135_dialog_content = "Sin embargo...",
  ui_story_5051_50511002_136_dialog_content = "¿Todavía no me crees?",
  ui_story_5051_50511002_137_dialog_content = "PlayerName parece solo un poco mayor que Veronica.",
  ui_story_5051_50511002_138_dialog_content = "habría adivinado que eres PlayerNameel abuelo de",
  ui_story_5051_50511002_139_dialog_content = "Ja ja ja, joven.",
  ui_story_5051_50511002_140_dialog_content = "Gracias por alertarme de lo desagradable que era en mis días de juventud.",
  ui_story_5051_50511002_141_dialog_content = "Me puedo imaginar eso.",
  ui_story_5051_50511002_142_dialog_content = "Afortunadamente, ya no me molesta a mi edad.",
  ui_story_5051_50511002_143_dialog_content = "Si no me equivoco, ¿debe tener asuntos más importantes que atender?",
  ui_story_5051_50511002_144_dialog_content = "¿A donde tratas de llegar?",
  ui_story_5051_50511002_145_dialog_content = "Puede que sea viejo, pero sé un par de cosas sobre cómo tratar con eclipses.",
  ui_story_5051_50511002_146_dialog_content = "Estoy dispuesto a llevar a Veronica y PlayerName a la seguridad.",
  ui_story_5051_50511002_147_dialog_content = "Aprecio el pensamiento.",
  ui_story_5051_50511002_148_dialog_content = "Sin embargo, Verónica es mi hija.",
  ui_story_5051_50511002_149_dialog_content = "Soy totalmente capaz de protegerla yo mismo.",
  ui_story_5051_50511002_150_dialog_content = "Nadie más necesita intervenir.",
  ui_story_5051_50511002_151_dialog_content = "...",
  ui_story_5051_50511002_152_dialog_content = "<color=#FFB400>Padre</color>...",
  ui_story_5051_50511002_153_dialog_content = "(Mia...)",
  ui_story_5051_50511002_154_dialog_content = "(Cual <color=#FFB400>padre</color> ella está respondiendo ahora?)",
  ui_story_5051_50511101_1_dialog_content = "La bola de cristal está realmente brillando...",
  ui_story_5051_50511101_2_dialog_content = "PlayerName y otros deben estar cerca!",
  ui_story_5051_50511101_3_dialog_content = "Hay tanto silencio.",
  ui_story_5051_50511101_4_dialog_content = "Sí, este no es un lugar tan animado como lo fue en nuestro camino hacia aquí.",
  ui_story_5051_50511101_5_dialog_content = "Creo que deberíamos ir a pasar el rato donde haya más gente.",
  ui_story_5051_50511101_6_dialog_content = "Está demasiado muerto por aquí.",
  ui_story_5051_50511101_7_dialog_content = "Puedo decir que no hay nadie vendiendo buena bebida.",
  ui_story_5051_50511101_8_dialog_content = "Ejem, no estamos aquí para comprar.",
  ui_story_5051_50511101_9_dialog_content = "¿Crees que has aprendido lo suficiente como para engañarme ahora?",
  ui_story_5051_50511101_10_dialog_content = "¿Esa gente de negro formal no trató de conseguir nuestro negocio?",
  ui_story_5051_50511101_11_dialog_content = "¿Gente en formal negro? ¿Estás hablando de los eclipses?",
  ui_story_5051_50511101_12_dialog_content = "¿Estás tan borracho que ni siquiera podrías decir que eran eclipses?",
  ui_story_5051_50511101_13_dialog_content = "<size=30>No es de extrañar que ni siquiera pudieras decir que era yo...</size>",
  ui_story_5051_50511101_14_dialog_content = "Revisé el área y todos los Eclipsites deberían estar muertos ahora.",
  ui_story_5051_50511101_15_dialog_content = "Debe haber amplia seguridad donde están el Señor de la Ciudad y la Princesa.",
  ui_story_5051_50511101_16_dialog_content = "Así que tus amigos deberían estar a salvo con ellos.",
  ui_story_5051_50511101_17_dialog_content = "Muchas gracias.",
  ui_story_5051_50511101_18_dialog_content = "Si no mataras a esos Eclipsites en un santiamén, no sabría cómo pude llegar tan lejos.",
  ui_story_5051_50511101_19_dialog_content = "¡Eres el caballero más confiable que he conocido en Lumopolis!",
  ui_story_5051_50511101_20_dialog_content = "Incluso puedo decir sin la bola de cristal...",
  ui_story_5051_50511101_21_dialog_content = "¡Con el tiempo te convertirás en una figura destacada!",
  ui_story_5051_50511101_22_dialog_content = "Gracias por el comentario.",
  ui_story_5051_50511101_23_dialog_content = "Solo soy un aprendiz en este momento.",
  ui_story_5051_50511101_24_dialog_content = "Que me creas es el mayor estímulo para mí.",
  ui_story_5051_50511101_25_dialog_content = "¡Está bien, todavía eres joven! Tendrás la oportunidad de...",
  ui_story_5051_50511101_26_dialog_content = "¡Hey, espera!",
  ui_story_5051_50511101_27_dialog_content = "(Lo que sucede aquí es lo que el Cristal registró hace doce años).",
  ui_story_5051_50511101_28_dialog_content = "(¡Eso significa que este caballero es mucho mayor que yo ahora!)",
  ui_story_5051_50511101_29_dialog_content = "Ejem. Entonces, ¿cuántos años tienes ahora?",
  ui_story_5051_50511101_30_dialog_content = "Fuiste bastante insistente cuando querías que yo fuera tu amo.",
  ui_story_5051_50511101_31_dialog_content = "¿Por qué eres tan torpe e insípido ahora?",
  ui_story_5051_50511101_32_dialog_content = "¡Solo dilo si estás interesado!",
  ui_story_5051_50511101_33_dialog_content = "¿Qué? ¡N-No, eso no es lo que quiero decir!",
  ui_story_5051_50511101_34_dialog_content = "¿Ah?",
  ui_story_5051_50511101_35_dialog_content = "¡Por supuesto, eso no significa que no me gustes!",
  ui_story_5051_50511101_36_dialog_content = "Es solo que... no importa, yo tampoco sé por dónde empezar.",
  ui_story_5051_50511101_37_dialog_content = "Pero si dentro de doce años sigues siendo un caballero en Lumopolis...",
  ui_story_5051_50511101_38_dialog_content = "¡Nos encontraremos de nuevo seguro!",
  ui_story_5051_50511101_39_dialog_content = "¿Te refieres al cliché de \"Volveré tantos años después, así que espérame\"?",
  ui_story_5051_50511101_40_dialog_content = "Hice eso cuando tenía ocho años. ¿Qué tal algo más fresco?",
  ui_story_5051_50511101_41_dialog_content = "Uh, jaja...",
  ui_story_5051_50511101_42_dialog_content = "Esta mujer borracha no sabe lo que dice, ¡así que no le hagas caso!",
  ui_story_5051_50511101_43_dialog_content = "¡Te sostendré!",
  ui_story_5051_50511101_44_dialog_content = "¿Ah?",
  ui_story_5051_50511101_45_dialog_content = "Mis parientes no vieron mucho en mí debido a diferentes preocupaciones.",
  ui_story_5051_50511101_46_dialog_content = "Pero no estaría aquí hoy sin ellos turnándose para criarme.",
  ui_story_5051_50511101_47_dialog_content = "Espero poder demostrarles mi valía algún día y reconstruir la gloria de la Casa Kartima.",
  ui_story_5051_50511101_48_dialog_content = "Dentro de doce años, dijiste...",
  ui_story_5051_50511101_49_dialog_content = "¡Me verás como el caballero más poderoso al frente de un ejército cuando regreses!",
  ui_story_5051_50511101_50_dialog_content = "Wow, eso suena muy impresionante!",
  ui_story_5051_50511101_51_dialog_content = "Es una promesa entonces. ¡Te buscaré en los Lumo Knights!",
  ui_story_5051_50511101_52_dialog_content = "Pero aún no sé tu nombre...",
  ui_story_5051_50511101_53_dialog_content = "Sharona Kartima.",
  ui_story_5051_50511101_54_dialog_content = "Sharona? Que nombre tan adorable.",
  ui_story_5051_50511101_55_dialog_content = "Aguanta...",
  ui_story_5051_50511101_56_dialog_content = "¡¿Así que en realidad eres una chica?!",
  ui_story_5051_50511101_57_dialog_content = "<color=#e8d9bb>Otro extremo de la calle</color>",
  ui_story_5051_50511101_58_dialog_content = "No seas precipitado, joven.",
  ui_story_5051_50511101_59_dialog_content = "Entiendo tu situación así como tus sentimientos.",
  ui_story_5051_50511101_60_dialog_content = "Me tomó mucho tiempo finalmente darme cuenta de \"la delicadeza sobre el poder\".",
  ui_story_5051_50511101_61_dialog_content = "Espero que puedas considerar mantener a tu familia fuera de otros asuntos.",
  ui_story_5051_50511101_62_dialog_content = "Si tengo la oportunidad, debo presentarte al Consejo de Ancianos.",
  ui_story_5051_50511101_63_dialog_content = "Tendrían mucho en común para discutir, y a todos ustedes les encanta ser mentores de los jóvenes.",
  ui_story_5051_50511101_64_dialog_content = "¿Qué piensas?",
  ui_story_5051_50511101_65_dialog_content = "Veo que se me ha olvidado...",
  ui_story_5051_50511101_66_dialog_content = "Que encontré que la prédica santurrona era más molesta cuando era joven.",
  ui_story_5051_50511101_67_dialog_content = "<size=45>¡Guau!</size>",
  ui_story_5051_50511101_68_dialog_content = "¿Qué?",
  ui_story_5051_50511101_69_dialog_content = "¡Finalmente los encontré a todos! ¿Todos están bien?",
  ui_story_5051_50511101_70_dialog_content = "Todo está adjunto y se ve animado... Supongo que no pasa nada. ¡Maravilloso!",
  ui_story_5051_50511101_71_dialog_content = "Jakine...",
  ui_story_5051_50511101_72_dialog_content = "no te preocupes por mi PlayerName. ¡Mira, todavía estoy bien y de una sola pieza!",
  ui_story_5051_50511101_73_dialog_content = "Entonces, no nos quedemos por aquí.",
  ui_story_5051_50511101_74_dialog_content = "Ejem, debido a ciertas razones especiales...",
  ui_story_5051_50511101_75_dialog_content = "¡Debemos irnos de aquí HOY!",
  ui_story_5051_50511101_76_dialog_content = "Shhh...",
  ui_story_5051_50511101_77_dialog_content = "Problemas, PlayerName?",
  ui_story_5051_50511101_78_dialog_content = "Oh, quieres saber quién es la señora borracha conmigo, ¿verdad?",
  ui_story_5051_50511101_79_dialog_content = "¡Es bastante complicado, pero ciertamente puedo presentarles al caballero que nos ayudó!",
  ui_story_5051_50511101_80_dialog_content = "Oye, ¿dónde está ella?",
  ui_story_5051_50511101_81_dialog_content = "¿Se fue después de ver que encontré a mis amigos?",
  ui_story_5051_50511101_82_dialog_content = "Vamos, ¿nadie en Lumopolis puede despedirse como la gente normal?",
  ui_story_5051_50511101_83_dialog_content = "Oye, ¿es él a quien estás buscando, niña?",
  ui_story_5051_50511101_84_dialog_content = "¿Cómo es que me parece familiar?",
  ui_story_5051_50511101_85_dialog_content = "¿Boaz? ¿No partiste hacia Northland anoche como estaba previsto?",
  ui_story_5051_50511101_86_dialog_content = "No vengo a menudo a Lumopolis *hipo*, así que pensé en relajarme un poco.",
  ui_story_5051_50511101_87_dialog_content = "Oh, ahora recuerdo. De ayer...",
  ui_story_5051_50511101_88_dialog_content = "¡Eres ese señor de la ciudad!",
  ui_story_5051_50511101_89_dialog_content = "(¿Qué? ¿Este es el Señor de la Ciudad?)",
  ui_story_5051_50511101_90_dialog_content = "(No es de extrañar PlayerName me estaba guiñando un ojo...)",
  ui_story_5051_50511101_91_dialog_content = "<size=30>PlayerName, ¡ven aquí!</size>",
  ui_story_5051_50511101_92_dialog_content = "Vaya, tómatelo con calma...",
  ui_story_5051_50511101_93_dialog_content = "Dime, ¿qué está pasando con todo esto?",
  ui_story_5051_50511101_94_dialog_content = "Eso es lo que he estado tratando de resolver, pero se volvió más complicado ahora que tú también apareciste...",
  ui_story_5051_50511101_95_dialog_content = "¿Cómo puede algo ser complicado? Probablemente todo esté en tu cabeza.",
  ui_story_5051_50511101_96_dialog_content = "De todos modos, el Señor de la Ciudad acaba de notar al Señor de la Ciudad y lo confundió con un secuestrador...",
  ui_story_5051_50511101_97_dialog_content = "¿Por qué me siento aún más perdido por eso?",
  ui_story_5051_50511101_98_dialog_content = "Por eso digo que es muy complicado...",
  ui_story_5051_50511101_99_dialog_content = "El problema es ¿cómo vamos a diferenciar a un señor de la ciudad de otro?",
  ui_story_5051_50511101_100_dialog_content = "Solo les dije que el Señor de la Ciudad que vino aquí con nosotros es mi padre, Soroz...",
  ui_story_5051_50511101_101_dialog_content = "¿Soroz? ¿No es ese el nombre de tu Coloso, PlayerName?",
  ui_story_5051_50511101_102_dialog_content = "Estaba presionando por un nombre en ese momento...",
  ui_story_5051_50511101_103_dialog_content = "uno es viejo Schwartz, el otro es joven Schwartz. ¿No sería eso más fácil?",
  ui_story_5051_50511101_104_dialog_content = "Bueno, probablemente sea descortés con el Señor de la Ciudad, pero por conveniencia...",
  ui_story_5051_50511101_105_dialog_content = "Entonces, el viejo Schwartz trató de tomar Mia lejos, sólo para los jóvenes Schwartz confundirlo con un secuestrador.",
  ui_story_5051_50511101_106_dialog_content = "¡Ahora estamos tratando de salir del aprieto!",
  ui_story_5051_50511101_107_dialog_content = "¡Ah, ahora lo entiendo ya que lo pones de esa manera!",
  ui_story_5051_50511101_108_dialog_content = "¡Lo tengo!",
  ui_story_5051_50511101_109_dialog_content = "¡Estoy bien, no estoy... perdido en absoluto!",
  ui_story_5051_50511101_110_dialog_content = "Muy bien, ¿te importaría decirme quién es la joven entonces?",
  ui_story_5051_50511101_111_dialog_content = "¡Puedo hacerlo yo mismo muy bien! ¡Yo, alumno de Booz!",
  ui_story_5051_50511101_112_dialog_content = "No sabía que Su Majestad envió dos enviados esta vez.",
  ui_story_5051_50511101_113_dialog_content = "Por supuesto, el Señor de la Ciudad no lo sabría, ya que solo hay un enviado.",
  ui_story_5051_50511101_114_dialog_content = "¡Solo soy un seguidor! ¡Aunque los seguidores también tienen trabajos que hacer!",
  ui_story_5051_50511101_115_dialog_content = "Mi trabajo es diferente al de Boaz, así que no pude conocerte ni a ti ni a tu dama.",
  ui_story_5051_50511101_116_dialog_content = "¿Oh? ¿Cuál es tu misión?",
  ui_story_5051_50511101_117_dialog_content = "Invitar PlayerName a Northland para la fiesta de Su Majestad.",
  ui_story_5051_50511101_118_dialog_content = "¡¿Qué?!",
  ui_story_5051_50511101_119_dialog_content = "Parece PlayerName no es consciente de esto.",
  ui_story_5051_50511101_120_dialog_content = "Por supuesto que no. ¡Acabo de rastrear al tipo!",
  ui_story_5051_50511101_121_dialog_content = "Entonces, PlayerName, ¿Te gustaría ir?",
  ui_story_5051_50511101_122_dialog_content = "<size=30>*tos* ¡Di que sí! *tos*</size>",
  ui_story_5051_50511101_123_dialog_content = "¿Eh? Oh...",
  ui_story_5051_50511101_124_dialog_content = "¡Ciertamente no voy a rechazar una invitación de la Reina!",
  ui_story_5051_50511101_125_dialog_content = "¿Está bien? ¡Genial!",
  ui_story_5051_50511101_126_dialog_content = "Mi maestra hizo su trabajo y yo hice el mío.",
  ui_story_5051_50511101_127_dialog_content = "¡Todos podemos volver a Northland con alegría ahora!",
  ui_story_5051_50511101_128_dialog_content = "(Jakine es un genio!)",
  ui_story_5051_50511101_129_dialog_content = "(Joven Schwartz tiene que dejarnos ir ahora.)",
  ui_story_5051_50511101_130_dialog_content = "...",
  ui_story_5051_50511101_131_dialog_content = "(Pero ¿por qué es el viejo Schwartz todavía tenso?)",
  ui_story_5051_50511101_132_dialog_content = "(Hizo Jakine y subestimo groseramente la situación?)",
  ui_story_5051_50511101_133_dialog_content = "Comprendo.",
  ui_story_5051_50511101_134_dialog_content = "(¿Estaba yo viendo cosas o el joven Schwartz solo reírse?)",
  ui_story_5051_50511101_135_dialog_content = "Tengo el máximo respeto por la Reina del Norte. Cualquier huésped suyo es un huésped mío.",
  ui_story_5051_50511101_136_dialog_content = "Siento mucho que veas a Lumopolis en tal caos.",
  ui_story_5051_50511101_137_dialog_content = "Pero te prometo que no durará mucho.",
  ui_story_5051_50511101_138_dialog_content = "Hasta entonces, les pido que me sigan.",
  ui_story_5051_50511101_139_dialog_content = "¡Garantizaré la seguridad de todo tu grupo!",
  ui_story_5051_50511101_140_dialog_content = "<size=30>Su actitud es totalmente diferente...</size>",
  ui_story_5051_50511101_141_dialog_content = "<size=30>¿No explotarías ningún peón gratis envuelto para ti, PlayerName?</size>",
  ui_story_5051_50511101_142_dialog_content = "<size=30>¿Peones?</size>",
  ui_story_5051_50511101_143_dialog_content = "(¿Qué significa eso? ¿Somos todos peones para jóvenes Schwartz ¿ahora?)",
  ui_story_5051_50511101_144_dialog_content = "(Pero, ¿qué beneficios podemos traerle unos pocos?)",
  ui_story_5051_50511101_145_dialog_content = "(También, viejo Schwartz dice eso...)",
  ui_story_5051_50511101_146_dialog_content = "(¿Porque había tratado a los demás como piezas de ajedrez de esta manera?)",
  ui_story_5051_50511101_147_dialog_content = "<size=30>PlayerName, debes saber que el ajedrez es más que un juego en este momento.</size>",
  ui_story_5051_50511101_148_dialog_content = "¡Padre!",
  ui_story_5051_50511101_149_dialog_content = "Esa voz.",
  ui_story_5051_50511101_150_dialog_content = "¡Padre!",
  ui_story_5051_50511101_151_dialog_content = "Auto...",
  ui_story_5051_50511101_152_dialog_content = "¡Carleen! ¿Qué estás haciendo acá?",
  ui_story_5051_50511101_153_dialog_content = "La traje aquí.",
  ui_story_5051_50511101_154_dialog_content = "...",
  ui_story_5051_50511101_155_dialog_content = "¿Por qué estás de vuelta? ¿Se ha eliminado la segunda ola de eclipses?",
  ui_story_5051_50511101_156_dialog_content = "¿Segunda ola de eclipses?",
  ui_story_5051_50511101_157_dialog_content = "Uh, simplemente me preocupa que tal vez surjan más eclipses en otros lugares.",
  ui_story_5051_50511101_158_dialog_content = "No puedo corroborar la sospecha, pero tampoco podemos ser descuidados.",
  ui_story_5051_50511101_159_dialog_content = "¿Dónde está la Sra. Rot? Se suponía que ella se iría contigo. ¿Por qué descuidó su puesto?",
  ui_story_5051_50511101_160_dialog_content = "La Sra. Rot no descuidó su publicación. En comparación conmigo, los civiles necesitaban más su ayuda.",
  ui_story_5051_50511101_161_dialog_content = "Me lo estás poniendo difícil, Joshua.",
  ui_story_5051_50511101_162_dialog_content = "Y sabes que no es la primera vez, Daniel.",
  ui_story_5051_50511101_163_dialog_content = "¿Cuándo recordarás que mis habilidades con la espada rivalizan con las tuyas?",
  ui_story_5051_50511101_164_dialog_content = "Parece que tienes muchos amigos que necesitan ayuda aquí...",
  ui_story_5051_50511101_165_dialog_content = "Permíteme compartir algo de esa carga, Daniel.",
  ui_story_5051_50511101_166_dialog_content = "Josué!",
  ui_story_5051_50511101_167_dialog_content = "¡Tos tos!",
  ui_story_5051_50511101_168_dialog_content = "¿Está bien, señor?",
  ui_story_5051_50511101_169_dialog_content = "Me pareces algo familiar...",
  ui_story_5051_50511101_170_dialog_content = "Eso fue lo que dijiste cuando nos conocimos por primera vez.",
  ui_story_5051_50511101_171_dialog_content = "Nos hemos visto antes...?",
  ui_story_5051_50511101_172_dialog_content = "(Ahora, ¿quién fue el que me advirtió que no me involucrara en este mundo?)",
  ui_story_5051_50511101_173_dialog_content = "Ejem. Veo que mi padre conocía a Lady Joshua.",
  ui_story_5051_50511101_174_dialog_content = "Mis disculpas, creo que me equivoqué de persona.",
  ui_story_5051_50511101_175_dialog_content = "Oh, es PlayerName¡El padre del padre, no me extraña que te pareciera familiar!",
  ui_story_5051_50511101_176_dialog_content = "¡Ay!",
  ui_story_5051_50511101_177_dialog_content = "¡Eclipsitos! ¡Más eclipses!",
  ui_story_5051_50511101_178_dialog_content = "El Señor de la Ciudad lo adivinó justo en el punto. ¡Aquí viene la segunda ola!",
  ui_story_5051_50511101_179_dialog_content = "¿Puede predecir el futuro también? ¿Quizás incluso mejor que yo?",
  ui_story_5051_50511101_180_dialog_content = "...",
  ui_story_5051_50511101_181_dialog_content = "¡Daniel!",
  ui_story_5051_50511101_182_dialog_content = "¡Cuidado con los eclipses, todos!",
  ui_story_5051_50511101_183_dialog_content = "<color=#e8d9bb>¡Chunda chunda!</color>",
  ui_story_5051_50511101_184_dialog_content = "Escucho pasos nítidos y ordenados...",
  ui_story_5051_50511101_185_dialog_content = "¡Probablemente no sean los eclipses!",
  ui_story_5051_50511101_186_dialog_content = "¡Eso es genial!",
  ui_story_5051_50511101_187_dialog_content = "¡El refuerzo está aquí!",
  ui_story_5051_50511101_188_dialog_content = "Sostenlo.",
  ui_story_5051_50511101_189_dialog_content = "Estos soldados no están aquí para ayudarnos.",
  ui_story_5051_50511101_190_dialog_content = "¿Ah?",
  ui_story_5051_50511101_191_dialog_content = "¡A la carga!",
  ui_story_5051_50511101_192_dialog_content = "¡Guau—!",
  ui_story_5051_50511101_193_dialog_content = "¿Por qué nos apuntan con sus armas?",
  ui_story_5051_50511102_1_dialog_content = "Detrás de ti a la izquierda, Jakine!",
  ui_story_5051_50511102_2_dialog_content = "¡Oye, mantente alejado!",
  ui_story_5051_50511102_3_dialog_content = "Oh...",
  ui_story_5051_50511102_4_dialog_content = "¿Eh? ¿Me salvaste? PlayerName?",
  ui_story_5051_50511102_5_dialog_content = "N-No...",
  ui_story_5051_50511102_6_dialog_content = "Mirad dónde tropezáis, piedras andantes.",
  ui_story_5051_50511102_7_dialog_content = "¿Quién me dará alcohol si mi alumno está herido?",
  ui_story_5051_50511102_8_dialog_content = "¡Sí, el asombrosamente intrépido Booz a quien recuerdo ha regresado!",
  ui_story_5051_50511102_9_dialog_content = "Estoy mareado, debo haber puesto demasiado en eso...",
  ui_story_5051_50511102_10_dialog_content = "Tú toma el control, chica, he terminado...",
  ui_story_5051_50511102_11_dialog_content = "No-! ¡Todavía no hemos tenido la oportunidad de ponernos al día!",
  ui_story_5051_50511102_12_dialog_content = "¿En realidad? Quedarse dormido en un momento como este. ¡Retiro lo que dije antes!",
  ui_story_5051_50511102_13_dialog_content = "PlayerName, llevar Jakine y Mia y salir del hueco correcto. ¡Te cubriré!",
  ui_story_5051_50511102_14_dialog_content = "¿Estamos dejando a otros atrás?",
  ui_story_5051_50511102_15_dialog_content = "Estamos fuera de hora. El <color=#FFB400>insurrección</color> está sucediendo. ¡Cada segundo aquí solo aumenta el peligro!",
  ui_story_5051_50511102_16_dialog_content = "¿Insurrección?",
  ui_story_5051_50511102_17_dialog_content = "¿Cómo es que no recuerdo nada de esto? ¿Sabía yo sobre esto en ese entonces?",
  ui_story_5051_50511102_18_dialog_content = "No te esfuerces, Mia!",
  ui_story_5051_50511102_19_dialog_content = "<color=#e8d9bb>¡Whoosh!</color>",
  ui_story_5051_50511102_20_dialog_content = "¿Quien era ese?",
  ui_story_5051_50511102_21_dialog_content = "¿Parecía estar volando desde el cielo y persiguiendo un objetivo específico?",
  ui_story_5051_50511102_22_dialog_content = "¿Puede ser el objetivo <color=#FFB400>joven Schwartz</color>?",
  ui_story_5051_50511102_23_dialog_content = "Joven Schwartz ¡Está prestando demasiada atención al enemigo para notar el peligro desde arriba!",
  ui_story_5051_50511102_24_dialog_content = "¡De ninguna manera, incluso nuestro antiguo Señor de la Ciudad lo habría visto!",
  ui_story_5051_50511102_25_dialog_content = "...",
  ui_story_5051_50511102_26_dialog_content = "¡Cuidado, Daniel!",
  ui_story_5051_50511102_27_dialog_content = "¡Hola!",
  ui_story_5051_50511102_28_dialog_content = "Err...",
  ui_story_5051_50511102_29_dialog_content = "¡Oh, eso parece doloroso!",
  ui_story_5051_50511102_30_dialog_content = "¿Fue apuñalado en el hombro?",
  ui_story_5051_50511102_31_dialog_content = "¡Tenemos que darnos prisa mientras todos están distraídos!",
  ui_story_5051_50511102_32_dialog_content = "Pero...",
  ui_story_5051_50511102_33_dialog_content = "¡Padre!",
  ui_story_5051_50511102_34_dialog_content = "¡Voy a ayudar a papá!",
  ui_story_5051_50511102_35_dialog_content = "¿En serio?",
  ui_story_5051_50511102_36_dialog_content = "Carleen...",
  ui_story_5051_50511102_37_dialog_content = "Oh no, los rebeldes vieron jóvenes Carleen!",
  ui_story_5051_50511102_38_dialog_content = "... ¿Qué?",
  ui_story_5051_50511102_39_dialog_content = "A-¿Eres un chico malo también?",
  ui_story_5051_50511102_40_dialog_content = "¡Hola, princesita!",
  ui_story_5051_50511102_41_dialog_content = "¡N-No creas que te tengo miedo!",
  ui_story_5051_50511102_42_dialog_content = "¡Soy muy hábil con las espadas! ¡Golpeé a muchos soldados!",
  ui_story_5051_50511102_43_dialog_content = "¡Lástima que no tendré piedad de ti como esos soldados!",
  ui_story_5051_50511102_44_dialog_content = "¡Agh!",
  ui_story_5051_50511102_45_dialog_content = "¡Je, ni siquiera me puse a sudar y ya estás en el suelo!",
  ui_story_5051_50511102_46_dialog_content = "No te molestes en levantarte. Te caerás de todos modos.",
  ui_story_5051_50511102_47_dialog_content = "¡Agh!",
  ui_story_5051_50511102_48_dialog_content = "¡La Espada del Soberano!",
  ui_story_5051_50511102_49_dialog_content = "Que demonios...",
  ui_story_5051_50511102_50_dialog_content = "(Viejo Schwartz nos instó a correr sólo para salvar Carleen él mismo.)",
  ui_story_5051_50511102_51_dialog_content = "¿Estoy salvado? Padre, ¿eres tú...?",
  ui_story_5051_50511102_52_dialog_content = "...",
  ui_story_5051_50511102_53_dialog_content = "¡¡¡Carleen!!!",
  ui_story_5051_50511102_54_dialog_content = "¿Estás herida?",
  ui_story_5051_50511102_55_dialog_content = "No te preocupes, madre, no estoy herido.",
  ui_story_5051_50511102_56_dialog_content = "¿Por qué sigues hablando duro, niño...",
  ui_story_5051_50511102_57_dialog_content = "Probablemente solo se asustó, eso es todo.",
  ui_story_5051_50511102_58_dialog_content = "gracias por salvar Carleen, padre de PlayerName!",
  ui_story_5051_50511102_59_dialog_content = "No tienes que agradecerme. Es algo que debería hacer.",
  ui_story_5051_50511102_60_dialog_content = "mi pobrecito Carleen...",
  ui_story_5051_50511102_61_dialog_content = "Madre, ¿cómo está *tos tos* Padre?",
  ui_story_5051_50511102_62_dialog_content = "el, eh...",
  ui_story_5051_50511102_63_dialog_content = "No te preocupes, pronto derrotará a los malos.",
  ui_story_5051_50511102_64_dialog_content = "Madre, deberías ir y ayudar a Padre. Estoy bien... ¡totalmente bien!",
  ui_story_5051_50511102_65_dialog_content = "Oh, mi niña tonta.",
  ui_story_5051_50511102_66_dialog_content = "¡Hola!",
  ui_story_5051_50511102_67_dialog_content = "Tos...",
  ui_story_5051_50511102_68_dialog_content = "¡Daniel!",
  ui_story_5051_50511102_69_dialog_content = "No te preocupes, es más que suficiente para enfrentarse solo al asesino.",
  ui_story_5051_50511102_70_dialog_content = "Pero está herido...",
  ui_story_5051_50511102_71_dialog_content = "Entonces quédese aquí y permítame ayudar a su esposo.",
  ui_story_5051_50511102_72_dialog_content = "¿Qué? No deberías arriesgar tu vida por eso.",
  ui_story_5051_50511102_73_dialog_content = "Como puedes ver, los traidores no te están apuntando a ti, sino a mí y a mi familia.",
  ui_story_5051_50511102_74_dialog_content = "No hay tiempo para tales distinciones bajo esta circunstancia.",
  ui_story_5051_50511102_75_dialog_content = "Espera aquí.",
  ui_story_5051_50511102_76_dialog_content = "PlayerName, espera aquí con Jakine y Mia también.",
  ui_story_5051_50511102_77_dialog_content = "Ya vuelvo.",
  ui_story_5051_50511102_78_dialog_content = "¡Espera!",
  ui_story_5051_50511102_79_dialog_content = "Me gustaría ir contigo.",
  ui_story_5051_50511102_80_dialog_content = "...",
  ui_story_5051_50511102_81_dialog_content = "Tú tomas el flanco izquierdo y yo tomo el derecho. ¡Vamos a mudarnos!",
  ui_story_5051_50511102_82_dialog_content = "... ¡S-Claro!",
  ui_story_5051_50511102_83_dialog_content = "¿Estoy alucinando?",
  ui_story_5051_50511102_84_dialog_content = "¿O es que Daniel vi en PlayerNameel padre...?",
  ui_story_5051_50511102_85_dialog_content = "Err...",
  ui_story_5051_50511102_86_dialog_content = "Te he estado esperando durante mucho tiempo.",
  ui_story_5051_50511102_87_dialog_content = "¿Qué?",
  ui_story_5051_50511102_88_dialog_content = "Je, esta herida ni siquiera es tan mala como imaginé que sería.",
  ui_story_5051_50511102_89_dialog_content = "Así que ya te diste cuenta.",
  ui_story_5051_50511102_90_dialog_content = "Deja de hablar y déjanos terminar esto.",
  ui_story_5051_50511102_91_dialog_content = "¡Yo ayudaré!",
  ui_story_5051_50511102_92_dialog_content = "¡Retiro!",
  ui_story_5051_50511102_93_dialog_content = "¡Todos, retírense!",
  ui_story_5051_50511102_94_dialog_content = "Gracias a todos por darme esta oportunidad...",
  ui_story_5051_50511102_95_dialog_content = "¡Aurora Aeterna bajo la Luz!",
  ui_story_5051_50511102_96_dialog_content = "¡Urgh!",
  ui_story_5051_50511102_97_dialog_content = "Como he mencionado...",
  ui_story_5051_50511102_98_dialog_content = "Como señor de la ciudad, soy más que un simple burócrata.",
  ui_story_5051_50511201_1_dialog_content = "Huff... Huff... Huff...",
  ui_story_5051_50511201_2_dialog_content = "¿Estás bien, tío?",
  ui_story_5051_50511201_3_dialog_content = "Sharona?!",
  ui_story_5051_50511201_4_dialog_content = "¿No te dije que te tomaras medio día libre? ¿Qué estás haciendo aquí?",
  ui_story_5051_50511201_5_dialog_content = "Le prometimos al amigo de la princesa Verónica que encontraríamos a algunas personas esta mañana, así que pensé que tal vez podría ayudar...",
  ui_story_5051_50511201_6_dialog_content = "Es mi culpa por no seguir tus órdenes, tío.",
  ui_story_5051_50511201_7_dialog_content = "Pero cuando los eclipses invadieron la ciudad, ¡es mi deber como caballero en entrenamiento proteger a la gente!",
  ui_story_5051_50511201_8_dialog_content = "Además, estaba preocupado por los Kartimas que patrullaban la ciudad... así como por ti.",
  ui_story_5051_50511201_9_dialog_content = "Está bien.",
  ui_story_5051_50511201_10_dialog_content = "¡Irás a casa ahora y te irás de Lumopolis con tu tía y tus primos!",
  ui_story_5051_50511201_11_dialog_content = "Tome la aeronave estacionada en el jardín trasero.",
  ui_story_5051_50511201_12_dialog_content = "¿Por qué, tío?",
  ui_story_5051_50511201_13_dialog_content = "No preguntes por qué, ¡solo hazlo!",
  ui_story_5051_50511201_14_dialog_content = "Mira los Eclipsites en la calle, tío. Parecen dudar en atacarte a ti o a mí.",
  ui_story_5051_50511201_15_dialog_content = "La sangre de Kartima que corre a través de nosotros podría ser su perdición.",
  ui_story_5051_50511201_16_dialog_content = "Si podemos lograr que todo el clan rechace a los Eclipsites de Lumopolis esta vez...",
  ui_story_5051_50511201_17_dialog_content = "¡Definitivamente ganaremos el favor del Señor de la Ciudad y recuperaremos la gloria familiar!",
  ui_story_5051_50511201_18_dialog_content = "Entonces, ¿por qué me instruyes que huya con la familia en este momento?",
  ui_story_5051_50511201_19_dialog_content = "Acabas de recordarme que podrías encontrarte con otros Eclipsites después de salir de Lumopolis...",
  ui_story_5051_50511201_20_dialog_content = "En mi estudio hay una katana reliquia de Kartima llamada Azure Fuego.",
  ui_story_5051_50511201_21_dialog_content = "¡Recuerda traerlo contigo!",
  ui_story_5051_50511201_22_dialog_content = "No entiendo, tío...",
  ui_story_5051_50511201_23_dialog_content = "Tal vez esa profecía sea cierta, pero nunca lo creí.",
  ui_story_5051_50511201_24_dialog_content = "La persona que salvará a los Kartimas eres tú...",
  ui_story_5051_50511201_25_dialog_content = "Yo no.",
  ui_story_5051_50511201_26_dialog_content = "...",
  ui_story_5051_50511201_27_dialog_content = "¿Todo esto sucedió exactamente como la vez anterior?",
  ui_story_5051_50511201_28_dialog_content = "Prácticamente idéntico.",
  ui_story_5051_50511201_29_dialog_content = "Excepto que la herida de Carleen fue peor y yo no estaba allí para protegerla.",
  ui_story_5051_50511201_30_dialog_content = "Es por eso que no pudiste evitar irte cuando escuchaste su voz.",
  ui_story_5051_50511201_31_dialog_content = "¿Estabas tratando de compensar eso?",
  ui_story_5051_50511201_32_dialog_content = "Mentiría si dijera que no.",
  ui_story_5051_50511201_33_dialog_content = "Como es Carleen?",
  ui_story_5051_50511201_34_dialog_content = "En general bien, solo algunos rasguños en las manos y los pies.",
  ui_story_5051_50511201_35_dialog_content = "¡Pero tú, sin embargo, estás sangrando por el hombro!",
  ui_story_5051_50511201_36_dialog_content = "No es más grave que la picadura de un mosquito.",
  ui_story_5051_50511201_37_dialog_content = "Hace mucho tiempo que no practicamos juntos la lucha con espadas.",
  ui_story_5051_50511201_38_dialog_content = "Este nivel de emboscada no te habría tocado antes...",
  ui_story_5051_50511201_39_dialog_content = "Fue abrupto, y probablemente yo también perdí un poco el equilibrio.",
  ui_story_5051_50511201_40_dialog_content = "Primero una invasión de Eclipsites, luego el envío de asesinos el mismo día de Schwartz Dia familiar...",
  ui_story_5051_50511201_41_dialog_content = "¿Quién nos guardaría tanto rencor?",
  ui_story_5051_50511201_42_dialog_content = "Caballero Schwartz, Señora Josué.",
  ui_story_5051_50511201_43_dialog_content = "Por favor, disculpe a mí y a mi escuadrón por nuestra llegada tardía.",
  ui_story_5051_50511201_44_dialog_content = "Es nuestra negligencia lo que causó que la princesa y el señor resultaran heridos.",
  ui_story_5051_50511201_45_dialog_content = "La culpa no es suya, Sra. Rot.",
  ui_story_5051_50511201_46_dialog_content = "Porque garantizar la seguridad de los civiles es su prioridad.",
  ui_story_5051_50511201_47_dialog_content = "Gracias mi Señora.",
  ui_story_5051_50511201_48_dialog_content = "¿Algo más que informar?",
  ui_story_5051_50511201_49_dialog_content = "Si mi señor.",
  ui_story_5051_50511201_50_dialog_content = "Peinamos los alrededores y capturamos vivos a varios rebeldes.",
  ui_story_5051_50511201_51_dialog_content = "Dime lo que has descubierto.",
  ui_story_5051_50511201_52_dialog_content = "Encontramos armas con imágenes únicas en sus personas.",
  ui_story_5051_50511201_53_dialog_content = "Después de las comparaciones, verificamos que las imágenes fueran marcas de House Kartima.",
  ui_story_5051_50511201_54_dialog_content = "¿Casa Kartima?",
  ui_story_5051_50511201_55_dialog_content = "Estaba teniendo una agradable charla con la esposa de Mime en una fiesta no hace mucho tiempo.",
  ui_story_5051_50511201_56_dialog_content = "Sus dos hijos tenían aproximadamente la misma edad que Carleen.",
  ui_story_5051_50511201_57_dialog_content = "No, algo anda mal aquí.",
  ui_story_5051_50511201_58_dialog_content = "¿Por qué llevarían armas que fácilmente podrían incriminarse a sí mismos?",
  ui_story_5051_50511201_59_dialog_content = "Las personas arrogantes también suelen ser muy ingenuas.",
  ui_story_5051_50511201_60_dialog_content = "Estaban seguros de que podrían acabar conmigo hoy y acabar con el reinado de Schwartz.",
  ui_story_5051_50511201_61_dialog_content = "Sra. rot.",
  ui_story_5051_50511201_62_dialog_content = "A su servicio, mi señor.",
  ui_story_5051_50511201_63_dialog_content = "Notificar al Salón de Justicia sobre evidencia concreta de la insurrección de la Casa Kartima.",
  ui_story_5051_50511201_64_dialog_content = "Ponga un boletín de todos los puntos de toda la ciudad en <color=#FFB400>todos los miembros</color> de la familia Kartima inmediatamente",
  ui_story_5051_50511201_65_dialog_content = "Solicite que Hall of Justice emita lo mismo y nos ayude a detenerlos.",
  ui_story_5051_50511201_66_dialog_content = "Ejecutar al sospechoso en el acto cuando encuentre resistencia.",
  ui_story_5051_50511201_67_dialog_content = "Si mi señor.",
  ui_story_5051_50511201_68_dialog_content = "¿Todos los miembros de la Casa Kartima? ¿Qué haces, Daniel...?",
  ui_story_5051_50511201_69_dialog_content = "He visto demasiadas cosas como esta suceder este año.",
  ui_story_5051_50511201_70_dialog_content = "¿No son suficientes los espíritus de la Casa Pyrrhus y la Casa Gautier?",
  ui_story_5051_50511201_71_dialog_content = "Josué...",
  ui_story_5051_50511201_72_dialog_content = "Carleen necesita descanso. Llevala a su casa.",
  ui_story_5051_50511201_73_dialog_content = "...",
  ui_story_5051_50511201_74_dialog_content = "Joshua... Lady Joshua, estoy a punto de irme con mi hijo también.",
  ui_story_5051_50511201_75_dialog_content = "Permíteme acompañarte de regreso.",
  ui_story_5051_50511201_76_dialog_content = "Agradezco la oferta.",
  ui_story_5051_50511201_77_dialog_content = "Pero dado que los Eclipsites se eliminan en la ciudad, creo que puedo manejarlo por mi cuenta.",
  ui_story_5051_50511201_78_dialog_content = "Sr. Soroz... Si no recuerdo mal, ese es su nombre, ¿verdad?",
  ui_story_5051_50511201_79_dialog_content = "Sí.",
  ui_story_5051_50511201_80_dialog_content = "Lamento haber dudado de ti.",
  ui_story_5051_50511201_81_dialog_content = "Como mencionaste, eres bastante capaz de lidiar con los Eclipsites.",
  ui_story_5051_50511201_82_dialog_content = "Un destacado guerrero como tú no debería permanecer en el anonimato.",
  ui_story_5051_50511201_83_dialog_content = "No he sido un anfitrión perfecto hoy, así que tal vez podamos tener un largo intercambio después de que todo esto termine.",
  ui_story_5051_50511201_84_dialog_content = "Soy simplemente un anciano ordinario.",
  ui_story_5051_50511201_85_dialog_content = "Que deseaba un viaje seguro a casa para su hijo.",
  ui_story_5051_50511201_86_dialog_content = "Qué lástima, pensé que tendríamos mucho en común de qué hablar.",
  ui_story_5051_50511201_87_dialog_content = "Tal vez aquellos que son demasiado similares no deberían ser amigos.",
  ui_story_5051_50511201_88_dialog_content = "Je, ¿es así?",
  ui_story_5051_50511201_89_dialog_content = "Está bien. Ven, Verónica.",
  ui_story_5051_50511201_90_dialog_content = "M-yo?",
  ui_story_5051_50511201_91_dialog_content = "¿Hay alguien más aquí que se llame Verónica?",
  ui_story_5051_50511201_92_dialog_content = "¿A dónde vamos?",
  ui_story_5051_50511201_93_dialog_content = "Para perseguir a los rebeldes Kartima supervivientes.",
  ui_story_5051_50511201_94_dialog_content = "Espero que puedas aprender a pelear conmigo, a partir de hoy.",
  ui_story_5051_50511201_95_dialog_content = "¿Cree que estoy calificado, padre...",
  ui_story_5051_50511201_96_dialog_content = "Las habilidades de la princesa Veronica estaban a la vista.",
  ui_story_5051_50511201_97_dialog_content = "Pero ella todavía es joven y gastó mucha energía hoy.",
  ui_story_5051_50511201_98_dialog_content = "Es mejor para ella volver a casa a descansar.",
  ui_story_5051_50511201_99_dialog_content = "Sr. Soroz, tal vez PlayerName necesita un descanso, pero Verónica es mi hija.",
  ui_story_5051_50511201_100_dialog_content = "Cuidemos a nuestros hijos, respectivamente.",
  ui_story_5051_50511201_101_dialog_content = "<size=30>Bueno, eh...</size>",
  ui_story_5051_50511201_102_dialog_content = "Ella necesita descansar.",
  ui_story_5051_50511201_103_dialog_content = "Ella necesita aprender.",
  ui_story_5051_50511201_104_dialog_content = "<size=45>¡Bien!</size>",
  ui_story_5051_50511201_105_dialog_content = "¿Qué?",
  ui_story_5051_50511201_106_dialog_content = "Yo, yo...",
  ui_story_5051_50511201_107_dialog_content = "¡Yo quiero ir!",
  ui_story_5051_50511201_108_dialog_content = "¡¿?!",
  ui_story_5051_50511201_109_dialog_content = "Mi padre nunca me ha aprobado más...",
  ui_story_5051_50511201_110_dialog_content = "¡Nunca lo decepcionaré de nuevo!",
  ui_story_5051_50511201_111_dialog_content = "Además, me gustaría ver cómo resultará esta historia de la que nunca formé parte.",
  ui_story_5051_50511201_112_dialog_content = "...",
  ui_story_5051_50511201_113_dialog_content = "¡Hora de irse, Verónica!",
  ui_story_5051_50511201_114_dialog_content = "C-Ya viene!",
  ui_story_5051_50511201_115_dialog_content = "¡Entonces yo también voy!",
  ui_story_5051_50511201_116_dialog_content = "Todos ustedes son demasiado tercos.",
  ui_story_5051_50511201_117_dialog_content = "hola viejo Schwartz, Boaz está completamente fuera y no se siente bien...",
  ui_story_5051_50511201_118_dialog_content = "La señora dijo que la traería para que la trataran, pero no puedo dejarla al destino.",
  ui_story_5051_50511201_119_dialog_content = "Debes tener cuidado si vas a otro lugar.",
  ui_story_5051_50511201_120_dialog_content = "Además, asegúrate de regresar antes de que termine el día, o podríamos quedarnos atrapados aquí para siempre...",
  ui_story_5051_50511201_121_dialog_content = "...Ya veo.",
  ui_story_5051_50511201_122_dialog_content = "Pero, ¿cómo me acabas de llamar?",
  ui_story_5051_50511201_123_dialog_content = "Vaya, fue un desliz.",
  ui_story_5051_50511201_124_dialog_content = "De todos modos, vuelve tan pronto como puedas!",
  ui_story_5051_50511201_125_dialog_content = "<color=#e8d9bb>Residencia Otto</color>",
  ui_story_5051_50511201_126_dialog_content = "¿Sabías esto, duque Troy?",
  ui_story_5051_50511201_127_dialog_content = "¿Qué? ¿A qué te refieres, duque Hermes?",
  ui_story_5051_50511201_128_dialog_content = "Hay un gran lío ahí afuera, así que deja de engañarme.",
  ui_story_5051_50511201_129_dialog_content = "Oh, ¿quieres decir que alguien trató de aprovechar una incursión de Eclipsite para asesinar al Señor de la Ciudad?",
  ui_story_5051_50511201_130_dialog_content = "¡Sí!",
  ui_story_5051_50511201_131_dialog_content = "A pesar de lo mucho que desapruebo Schwartz, nunca me rebajaría tanto y me arriesgaría a arruinar el nombre de mi familia.",
  ui_story_5051_50511201_132_dialog_content = "Entonces, ¿de verdad no sabías nada de eso?",
  ui_story_5051_50511201_133_dialog_content = "Duque Hermes, ¿por qué debes ser tan paranoico y sospechar de todos?",
  ui_story_5051_50511201_134_dialog_content = "No pretendo cuestionarte, duque Troy.",
  ui_story_5051_50511201_135_dialog_content = "Pero... ya sabes, los descendientes de la familia Hermes se han unido a los Lumo Knights.",
  ui_story_5051_50511201_136_dialog_content = "Schwartz ahora está pidiendo a toda la orden que ayude a Umbraton, ¡a lo que me he opuesto todo el tiempo!",
  ui_story_5051_50511201_137_dialog_content = "Esos eclipses terrestres no pueden afectar a Lumopolis.",
  ui_story_5051_50511201_138_dialog_content = "Entonces, ¿por qué debemos ser enviados a nuestra muerte?",
  ui_story_5051_50511201_139_dialog_content = "No soy el único con ese pensamiento, ¿verdad?",
  ui_story_5051_50511201_140_dialog_content = "El señor de la ciudad también tiene sus preocupaciones, duque Hermes.",
  ui_story_5051_50511201_141_dialog_content = "Lumopolis podría ejercer un control más estricto sobre Umbraton si lo defendemos, ¿no es eso mejor?",
  ui_story_5051_50511201_142_dialog_content = "No es que no lo entiendas, duque Hermes.",
  ui_story_5051_50511201_143_dialog_content = "Incluso una pequeña ventaja como esa probablemente terminaría siendo agarrada por Schwartz, de todos modos.",
  ui_story_5051_50511201_144_dialog_content = "Y tuvo el descaro de celebrar el llamado Schwartz Dia familiar.",
  ui_story_5051_50511201_145_dialog_content = "¡Las familias Hermes y Troy hicieron contribuciones significativas para hacer de Lumopolis lo que es hoy!",
  ui_story_5051_50511201_146_dialog_content = "¿Por qué House debería Schwartz ¡¿consigue todo?!",
  ui_story_5051_50511201_147_dialog_content = "Si los Kartimas nos hubieran dejado entrar en el plan y combinado nuestras fuerzas...",
  ui_story_5051_50511201_148_dialog_content = "Estaríamos de pie para Schwartz!",
  ui_story_5051_50511201_149_dialog_content = "Tenga cuidado con sus palabras, duque Hermes.",
  ui_story_5051_50511201_150_dialog_content = "Acabo de recibir la noticia de que el Señor de la Ciudad ordenó el arresto de todos los Kartimas.",
  ui_story_5051_50511201_151_dialog_content = "Incluso un niño pequeño puede descubrir cómo va a terminar para ellos.",
  ui_story_5051_50511201_152_dialog_content = "¡No puede ser tan malo como para la Casa Pyrrhus y la Casa Gautier!",
  ui_story_5051_50511201_153_dialog_content = "Suspiro. ¿Aún no lo entiendes? Ahí es donde radica el problema.",
  ui_story_5051_50511201_154_dialog_content = "¿Qué? Te refieres a...",
  ui_story_5051_50511201_155_dialog_content = "Espera, lo entiendo, ¡conecto todos los puntos ahora!",
  ui_story_5051_50511201_156_dialog_content = "¡Los Kartimas son tan tontos!",
  ui_story_5051_50511201_157_dialog_content = "ellos solo dieron Schwartz más influencia con lo que acaban de hacer!",
  ui_story_5051_50511201_158_dialog_content = "Schwartz puede usarlo para convocar a los Lumo Knights e incluso a los ejércitos domésticos privados a su muerte en Umbraton.",
  ui_story_5051_50511201_159_dialog_content = "¡Mime Kartima, tonto sin cerebro!",
  ui_story_5051_50511201_160_dialog_content = "Dadas las circunstancias, cuanto menos se hable mejor, duque Hermes.",
  ui_story_5051_50511201_161_dialog_content = "Y me quedé dormido y me perdí todo lo que dijiste.",
  ui_story_5051_50511201_162_dialog_content = "Gracias, duque Troy. Por favor, no me dejes retenerte. Despedida.",
  ui_story_5051_50511201_163_dialog_content = "Servidor.",
  ui_story_5051_50511201_164_dialog_content = "Sí.",
  ui_story_5051_50511201_165_dialog_content = "Y destruye todo indicio de correspondencia con la Casa Kartima.",
  ui_story_5051_50511201_166_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_5051_50511201_167_dialog_content = "¿Qué fue eso?",
  ui_story_5051_50511201_168_dialog_content = "voy a comprobar",
  ui_story_5051_50511201_169_dialog_content = "¿Viste quién era?",
  ui_story_5051_50511201_170_dialog_content = "Era la señorita Rohsee. Se supone que debes verla antes de la cena.",
  ui_story_5051_50511201_171_dialog_content = "Ella había estado esperando afuera por un tiempo.",
  ui_story_5051_50511201_172_dialog_content = "Pero simplemente se fue presa del pánico.",
  ui_story_5051_50511201_173_dialog_content = "Ah, los niños de estos días...",
  ui_story_5051_50511301_1_dialog_content = "Tampoco encontramos nada en esta propiedad de Kartima, Señor de la Ciudad.",
  ui_story_5051_50511301_2_dialog_content = "Todos los bienes de Kartima en Lumopolis Gardens han sido confiscados. Aparte de los sirvientes, no se descubrió personal armado.",
  ui_story_5051_50511301_3_dialog_content = "Excepto por una aeronave que ignoró las advertencias y abandonó Lumopolis...",
  ui_story_5051_50511301_4_dialog_content = "Todos los demás miembros de House Kartima aún deberían estar escondidos dentro de la ciudad.",
  ui_story_5051_50511301_5_dialog_content = "¿Qué pasa con Lumopolis Courtyard y Lower Lumopolis?",
  ui_story_5051_50511301_6_dialog_content = "Se ha enviado personal, pero se requiere tiempo para recopilar detalles específicos.",
  ui_story_5051_50511301_7_dialog_content = "¿No huyeron sino que se escondieron en la ciudad?",
  ui_story_5051_50511301_8_dialog_content = "Parece que están esperando una oportunidad para atacar de nuevo.",
  ui_story_5051_50511301_9_dialog_content = "House Kartima cuenta con muchos miembros y ha ganado numerosos afiliados en los últimos años.",
  ui_story_5051_50511301_10_dialog_content = "Dado eso, la situación es más precaria de lo imaginado...",
  ui_story_5051_50511301_11_dialog_content = "No podemos ser pasivos.",
  ui_story_5051_50511301_12_dialog_content = "Debemos continuar la búsqueda en Lumopolis Courtyard.",
  ui_story_5051_50511301_13_dialog_content = "Un momento, por favor.",
  ui_story_5051_50511301_14_dialog_content = "¡T-Has venido después de todo!",
  ui_story_5051_50511301_15_dialog_content = "...",
  ui_story_5051_50511301_16_dialog_content = "<size=30>no tengas miedo, Mia, no estoy aquí para llevarte de vuelta.</size>",
  ui_story_5051_50511301_17_dialog_content = "<size=30>Lo reflexioné y tienes derecho a conocer esta parte de la historia.</size>",
  ui_story_5051_50511301_18_dialog_content = "Sr. Soroz? Sabía que nos volveríamos a encontrar muy pronto.",
  ui_story_5051_50511301_19_dialog_content = "Aunque no esperaba que fuera tan rápido.",
  ui_story_5051_50511301_20_dialog_content = "De repente recordé que es posible que tenga las pistas que está buscando.",
  ui_story_5051_50511301_21_dialog_content = "Espero que no me estés retrasando a propósito.",
  ui_story_5051_50511301_22_dialog_content = "Por supuesto que no. También espero que mi hijo rebelde se vaya a casa conmigo voluntariamente a tiempo.",
  ui_story_5051_50511301_23_dialog_content = "Sin embargo, me gustaría que me prometa que no buscará mi fuente de información.",
  ui_story_5051_50511301_24_dialog_content = "Claro, te prometo que no perseguiré tu fuente. Dime, ¿qué pistas tienes?",
  ui_story_5051_50511301_25_dialog_content = "Hay señales de ejércitos privados acampando en un campo sin desarrollar en el Bajo Lumopolis.",
  ui_story_5051_50511301_26_dialog_content = "¿Ha escuchado esto, Sra. Rot?",
  ui_story_5051_50511301_27_dialog_content = "Desierto cerca de las afueras...",
  ui_story_5051_50511301_28_dialog_content = "¿Puede ser esa colina rocosa?",
  ui_story_5051_50511301_29_dialog_content = "He oído relatos de gritos extraños y ocasionales de animales, pero está desolado.",
  ui_story_5051_50511301_30_dialog_content = "¿Está diciendo, Sr. Soroz, que ahí es donde pueden estar escondidos los Kartima?",
  ui_story_5051_50511301_31_dialog_content = "Estoy cien por ciento seguro.",
  ui_story_5051_50511301_32_dialog_content = "¿Por qué estás tan seguro? ¿De dónde sacaste esa información?",
  ui_story_5051_50511301_33_dialog_content = "Me prometiste no preguntar.",
  ui_story_5051_50511301_34_dialog_content = "Pero puedes castigarme como quieras si la información es falsa.",
  ui_story_5051_50511301_35_dialog_content = "Está bien. Sra. Rot, vayamos al área.",
  ui_story_5051_50511301_36_dialog_content = "¿Es digno de confianza el líder, señor de la ciudad?",
  ui_story_5051_50511301_37_dialog_content = "La rendición y la caída de los Kartimas son inevitables.",
  ui_story_5051_50511301_38_dialog_content = "Importa no confiar en él esta vez.",
  ui_story_5051_50511301_39_dialog_content = "Eso sí, tampoco dejes de peinar otras zonas.",
  ui_story_5051_50511301_40_dialog_content = "Si mi señor.",
  ui_story_5051_50511301_41_dialog_content = "Mmm...",
  ui_story_5051_50511301_42_dialog_content = "Tienes alguna pregunta para mi?",
  ui_story_5051_50511301_43_dialog_content = "Sobre esa pista, ¿la obtuviste de alguien en ese entonces?",
  ui_story_5051_50511301_44_dialog_content = "No, no encontramos ninguna información útil en la ciudad.",
  ui_story_5051_50511301_45_dialog_content = "Solo por la noche notamos movimientos en el desierto y sufrimos una brutal ofensiva de ellos.",
  ui_story_5051_50511301_46_dialog_content = "Sin embargo, en última instancia, todavía no pudieron evitar la derrota.",
  ui_story_5051_50511301_47_dialog_content = "¿Aceleraste la línea de tiempo para que podamos regresar lo antes posible?",
  ui_story_5051_50511301_48_dialog_content = "A veces, pensaba que si hubiera localizado antes a las fuerzas rebeldes...",
  ui_story_5051_50511301_49_dialog_content = "Tal vez los soldados que me han seguido durante años tendrían algunos hijos que ahora encuentran problemáticos.",
  ui_story_5051_50511301_50_dialog_content = "¿No has sentido aprensión por arruinar este mundo?",
  ui_story_5051_50511301_51_dialog_content = "Ya hemos hecho suficiente. Este no hará una gran diferencia.",
  ui_story_5051_50511301_52_dialog_content = "No eres del todo el Señor Schwartz Ahora lo sabía.",
  ui_story_5051_50511301_53_dialog_content = "¿Crees que sí? Yo también me siento diferente, una vez que dejo ir mi estatus de Señor de la Ciudad.",
  ui_story_5051_50511301_54_dialog_content = "Especialmente después de conocer a mi yo más joven.",
  ui_story_5051_50511301_55_dialog_content = "¿Este es el lugar?",
  ui_story_5051_50511301_56_dialog_content = "Según los exploradores, los Kartimas se han reunido en la colina que hay más adelante.",
  ui_story_5051_50511301_57_dialog_content = "¡Parecen estar planeando luchar hasta el último aliento!",
  ui_story_5051_50511301_58_dialog_content = "Ven, Verónica.",
  ui_story_5051_50511301_59_dialog_content = "Dime, ¿qué harías en esta situación si estuvieras al mando?",
  ui_story_5051_50511301_60_dialog_content = "Si yo estuviera al mando...",
  ui_story_5051_50511301_61_dialog_content = "Enviaría un enviado para razonar con ellos o persuadirlos.",
  ui_story_5051_50511301_62_dialog_content = "Anímelos a admitir el error de sus caminos y compensarlo.",
  ui_story_5051_50511301_63_dialog_content = "Mal, Verónica.",
  ui_story_5051_50511301_64_dialog_content = "Si quieres asumir mayores responsabilidades, debes obligarte a ganar <color=#FFB400>a cualquier precio</color>.",
  ui_story_5051_50511301_65_dialog_content = "¿Ganar a cualquier precio?",
  ui_story_5051_50511301_66_dialog_content = "Desde Lumopolis Gardens hasta Umbraton, todos los ojos están puestos en esta batalla.",
  ui_story_5051_50511301_67_dialog_content = "Están esperando a ver quién saldrá victorioso y solo elogiarán al ganador, sin importar quién sea.",
  ui_story_5051_50511301_68_dialog_content = "La historia la escriben los vencedores.",
  ui_story_5051_50511301_69_dialog_content = "Es probable que la historia de Lumopolis cambie en un futuro no muy lejano.",
  ui_story_5051_50511301_70_dialog_content = "Aún tienes mucho que aprender, Verónica.",
  ui_story_5051_50511301_71_dialog_content = "Cualquiera que sea el costo? Encuentro esa perspectiva... difícil de tragar.",
  ui_story_5051_50511301_72_dialog_content = "¿En serio?",
  ui_story_5051_50511301_73_dialog_content = "(Uy, olvidé que gruñendo al joven Schwartz es lo mismo que gruñirlo!)",
  ui_story_5051_50511301_74_dialog_content = "Uh, eso no fue intencional...",
  ui_story_5051_50511301_75_dialog_content = "Solo tienes que tomar algunas decisiones cuando estás en la cima, aunque eso suene como una excusa para eludir la culpa.",
  ui_story_5051_50511301_76_dialog_content = "Pero el presente yo no se jactará enfáticamente de que soy un gran líder impecable.",
  ui_story_5051_50511301_77_dialog_content = "solo espero...",
  ui_story_5051_50511301_78_dialog_content = "Que abrirás tu propio camino en el futuro y encontrarás un camino que te pertenece únicamente a ti.",
  ui_story_5051_50511301_79_dialog_content = "¡Lo haré!",
  ui_story_5051_50511301_80_dialog_content = "Espero que cuando sea viejo, no me arrepienta de mi yo más joven.",
  ui_story_5051_50511301_81_dialog_content = "Uh, ¡eso no pretendía ser un sarcasmo hacia ti!",
  ui_story_5051_50511301_82_dialog_content = "¡Hahaha!",
  ui_story_5051_50511301_83_dialog_content = "(Esta es la primera vez que recuerdo haber visto Schwartz riendo a carcajadas.)",
  ui_story_5051_50511301_84_dialog_content = "(Me acabo de dar cuenta, fuera de este viejo y joven Schwartz...)",
  ui_story_5051_50511301_85_dialog_content = "(En un pasado aún más lejano, había un Daniel inocente y risueño...)",
  ui_story_5051_50511301_86_dialog_content = "Siento algo más adelante.",
  ui_story_5051_50511301_87_dialog_content = "... ¡Rebeldes al acecho!",
  ui_story_5051_50511302_1_dialog_content = "He buscado en todas las habitaciones principales.",
  ui_story_5051_50511302_2_dialog_content = "¡Sin embargo, todavía no puedo encontrarlo!",
  ui_story_5051_50511302_3_dialog_content = "Hizo Schwartz construir una cámara secreta?",
  ui_story_5051_50511302_4_dialog_content = "Ese debe ser el caso.",
  ui_story_5051_50511302_5_dialog_content = "A juzgar por la personalidad de Schwartz, debe estar escondiendo muchos secretos de Joshua.",
  ui_story_5051_50511302_6_dialog_content = "¿Podría estar la entrada secreta en su estudio?",
  ui_story_5051_50511302_7_dialog_content = "Hmm, ¿qué es eso en la estantería?",
  ui_story_5051_50511302_8_dialog_content = "¡¿El Cristal de la Memoria Eterna?!",
  ui_story_5051_50511302_9_dialog_content = "¡Sí, de hecho es el Cristal de la Memoria Eterna!",
  ui_story_5051_50511302_10_dialog_content = "El lugar más peligroso es el más seguro, ¿eh?",
  ui_story_5051_50511302_11_dialog_content = "Jajaja.",
  ui_story_5051_50511302_12_dialog_content = "no puedo creer Schwartz dejaría algo tan precioso a la vista.",
  ui_story_5051_50511302_13_dialog_content = "Al igual que lo que le hizo a mi querida hermana...",
  ui_story_5051_50511302_14_dialog_content = "¡Has vuelto, mi señora!",
  ui_story_5051_50511302_15_dialog_content = "Es ella...",
  ui_story_5051_50511302_16_dialog_content = "Pareces nervioso. ¿Qué pasó?",
  ui_story_5051_50511302_17_dialog_content = "¡Por favor, perdonen mi ineptitud!",
  ui_story_5051_50511302_18_dialog_content = "Un guardia de la puerta fue noqueado esta tarde y todavía está en la enfermería.",
  ui_story_5051_50511302_19_dialog_content = "Revisamos por todos lados pero aún no pudimos encontrar al culpable...",
  ui_story_5051_50511302_20_dialog_content = "¿Alguien de la Casa Kartima otra vez?",
  ui_story_5051_50511302_21_dialog_content = "Comprendo.",
  ui_story_5051_50511302_22_dialog_content = "Tenemos invitados para la noche. Por favor, esté más atento.",
  ui_story_5051_50511302_23_dialog_content = "¡Sí, mi señora!",
  ui_story_5051_50511302_24_dialog_content = "Además, asegúrese de que el guardia herido se recupere en paz.",
  ui_story_5051_50511302_25_dialog_content = "Yo pagaré la factura médica.",
  ui_story_5051_50511302_26_dialog_content = "¡Gracias mi Señora!",
  ui_story_5051_50511302_27_dialog_content = "Los Kartima...",
  ui_story_5051_50511302_28_dialog_content = "¿No conoces a alguien de esa familia?",
  ui_story_5051_50511302_29_dialog_content = "Sí, pero no creo que sea una de las traidoras.",
  ui_story_5051_50511302_30_dialog_content = "Ella era obviamente muy amable y recta.",
  ui_story_5051_50511302_31_dialog_content = "¡También me dijo que quiere convertirse en una increíble capitana de caballeros!",
  ui_story_5051_50511302_32_dialog_content = "Es probable que tu amigo sea inocente y no supiera nada de la trama.",
  ui_story_5051_50511302_33_dialog_content = "¿Qué va a pasar si la atrapan?",
  ui_story_5051_50511302_34_dialog_content = "no lo sé todavía",
  ui_story_5051_50511302_35_dialog_content = "Pero relájate, haré todo lo posible para defender a los inocentes.",
  ui_story_5051_50511302_36_dialog_content = "¿A pesar de que su gente trató de asesinarte a ti y a tu familia?",
  ui_story_5051_50511302_37_dialog_content = "Los pecadores merecen ser castigados.",
  ui_story_5051_50511302_38_dialog_content = "Pero no creo que los inocentes deban serlo solo por su linaje.",
  ui_story_5051_50511302_39_dialog_content = "No hablemos de esto ahora.",
  ui_story_5051_50511302_40_dialog_content = "Déjame ir a preparar la cena y una cura para la resaca para Booz.",
  ui_story_5051_50511302_41_dialog_content = "¿No te preocupa el Señor de la Ciudad?",
  ui_story_5051_50511302_42_dialog_content = "¡Claro que lo soy!",
  ui_story_5051_50511302_43_dialog_content = "Pero tengo mucha más confianza en que Daniel regrese sano y salvo.",
  ui_story_5051_50511302_44_dialog_content = "¡Por eso tengo que tener la cena lista cuando vuelva!",
  ui_story_5051_50511302_45_dialog_content = "¡Ya empiezo a extrañarla, Lady Joshua!",
  ui_story_5051_50511302_46_dialog_content = "Entonces deberías pasarte por Lumopolis más a menudo, Jakine!",
  ui_story_5051_50511302_47_dialog_content = "Verónica y Carleen Me encantaría tener un nuevo amigo como tú.",
  ui_story_5051_50511302_48_dialog_content = "*lloriqueo*",
  ui_story_5051_50511302_49_dialog_content = "Shhh—",
  ui_story_5051_50511302_50_dialog_content = "Booz y Carleen todavía están dormidos. ¡Intenta no despertarlos!",
  ui_story_5051_50511401_1_dialog_content = "Supuse que con los Eclipsites ejecutando interferencias, tenía Schwartz en la bolsa.",
  ui_story_5051_50511401_2_dialog_content = "Sin embargo, todavía lo subestimaba.",
  ui_story_5051_50511401_3_dialog_content = "Anunciar al mundo que está enfermo fue una artimaña deliberada.",
  ui_story_5051_50511401_4_dialog_content = "Supongo que ya vio a través de mi plan.",
  ui_story_5051_50511401_5_dialog_content = "Cuando se trata de astucia, muy pocos en Lumopolis pueden Schwartz.",
  ui_story_5051_50511401_6_dialog_content = "Y pensé que me había vuelto lo suficientemente tortuoso con los años...",
  ui_story_5051_50511401_7_dialog_content = "...",
  ui_story_5051_50511401_8_dialog_content = "¿Cómo pudo pasar esto? Mimo, ¿por qué despertaste al <color=#FFB400>Dragonante</color>?",
  ui_story_5051_50511401_9_dialog_content = "¡Eso es imperdonable en la Casa Kartima!",
  ui_story_5051_50511401_10_dialog_content = "No lo hice a propósito... ¡Sálvame, Madre!",
  ui_story_5051_50511401_11_dialog_content = "Nunca dejes que nadie sepa sobre esto, hijo mío.",
  ui_story_5051_50511401_12_dialog_content = "Pero mi cabeza está a punto de partirse...",
  ui_story_5051_50511401_13_dialog_content = "¡Espera, Mimo! Dime... ¡Dime que puedes suprimir este poder!",
  ui_story_5051_50511401_14_dialog_content = "¡La persona que dirija House Kartima tiene que ser y debe ser usted!",
  ui_story_5051_50511401_15_dialog_content = "Duele... ¡No puedo hacer esto!",
  ui_story_5051_50511401_16_dialog_content = "¡Usted debe!",
  ui_story_5051_50511401_17_dialog_content = "¡Te reto a que lo digas de nuevo!",
  ui_story_5051_50511401_18_dialog_content = "Aunque me encerraste en esta torre tambaleante *tos*",
  ui_story_5051_50511401_19_dialog_content = "¡Todavía repetiré las mismas palabras!",
  ui_story_5051_50511401_20_dialog_content = "Mimo, no puedes salvar a la familia Kartima.",
  ui_story_5051_50511401_21_dialog_content = "¡Tú no eres el líder de la familia!",
  ui_story_5051_50511401_22_dialog_content = "Sí, desperté a los Dragonantes, ¿y qué?",
  ui_story_5051_50511401_23_dialog_content = "Porque yo soy el líder de la Casa Kartima. Eso es un hecho simple.",
  ui_story_5051_50511401_X23_dialog_content = "¡¿Has despertado a los Dragonantes?!",
  ui_story_5051_50511401_X24_dialog_content = "Me sorprende que consiguieras ocultar la verdad a esos miembros del clan que consideran a los Dragonantes un pecado... Realmente tienes algunos trucos bajo la manga.",
  ui_story_5051_50511401_X25_dialog_content = "Aún así, debo decir que no eres tú quien salvará a la Casa Kartima.",
  ui_story_5051_50511401_X26_dialog_content = "No importa si has despertado a los Dragonantes o no.",
  ui_story_5051_50511401_X27_dialog_content = "Lástima que nadie creerá tu profecía.",
  ui_story_5051_50511401_24_dialog_content = "¡Jajajaja! Tos...",
  ui_story_5051_50511401_25_dialog_content = "Ten miedo, la chica que salvará a los Kartimas pronto se te aparecerá.",
  ui_story_5051_50511401_26_dialog_content = "Estás completamente loco.",
  ui_story_5051_50511401_27_dialog_content = "A nadie más le gusta este niño o está dispuesto a acogerlo.",
  ui_story_5051_50511401_28_dialog_content = "Buenas noches, Señor Mimo.",
  ui_story_5051_50511401_29_dialog_content = "Soy Sharona.",
  ui_story_5051_50511401_30_dialog_content = "!!!",
  ui_story_5051_50511401_31_dialog_content = "¿Puedes ser tú de quien habló el anciano?",
  ui_story_5051_50511401_32_dialog_content = "Te prometo que no te causaré ningún problema.",
  ui_story_5051_50511401_33_dialog_content = "Me llevo a este chico.",
  ui_story_5051_50511401_34_dialog_content = "¡G-Gracias, Lord Mime!",
  ui_story_5051_50511401_35_dialog_content = "Prepárate, nunca llegarás a nada aquí.",
  ui_story_5051_50511401_36_dialog_content = "Suspiro...",
  ui_story_5051_50511401_37_dialog_content = "Señor Mimo, Señor Mimo...",
  ui_story_5051_50511401_38_dialog_content = "¿Qué es?",
  ui_story_5051_50511401_39_dialog_content = "Todos los miembros y soldados de la Casa Kartima se han reunido.",
  ui_story_5051_50511401_40_dialog_content = "Los hice cómplices al final...",
  ui_story_5051_50511401_41_dialog_content = "¡No tenemos ningún problema con eso, mi señor!",
  ui_story_5051_50511401_42_dialog_content = "Schwartz ha ido disminuyendo el poder de la Casa Kartima.",
  ui_story_5051_50511401_43_dialog_content = "Si no fuera por ti, Schwartz ya nos habría arruinado por mucho tiempo.",
  ui_story_5051_50511401_44_dialog_content = "Muy bien, suficiente de eso.",
  ui_story_5051_50511401_45_dialog_content = "¡No, debo hablar! ¡Debemos hablar!",
  ui_story_5051_50511401_46_dialog_content = "Todos vimos las contribuciones que hiciste a House Kartima.",
  ui_story_5051_50511401_47_dialog_content = "¡Estamos dispuestos a seguirte hasta el final sin remordimientos!",
  ui_story_5051_50511401_48_dialog_content = "Schwartz sabía que todos se oponían a enviar refuerzos a Umbraton...",
  ui_story_5051_50511401_49_dialog_content = "Sin embargo, trató de obligarte a prestar juramento en apoyo de esa misma idea en la ceremonia de hoy.",
  ui_story_5051_50511401_50_dialog_content = "Eso claramente nos convirtió en el objetivo de otras casas para promover su propia ambición.",
  ui_story_5051_50511401_51_dialog_content = "Comparado con morir en manos de Eclipsites por el interés de Schwartz...",
  ui_story_5051_50511401_52_dialog_content = "¡Estamos mucho más dispuestos a morir por la Casa Kartima!",
  ui_story_5051_50511401_53_dialog_content = "<size=45>¡Muere por la Casa Kartima! ¡Muere por la Casa Kartima! ¡Muere por la Casa Kartima!</size>",
  ui_story_5051_50511401_54_dialog_content = "¡Maravilloso! Pero no estoy de acuerdo con uno de los puntos.",
  ui_story_5051_50511401_55_dialog_content = "¡El resultado de esta batalla aún no se ha determinado!",
  ui_story_5051_50511401_56_dialog_content = "¡Tiene razón, mi señor!",
  ui_story_5051_50511401_57_dialog_content = "¡Estamos listos para seguirte y recuperar la gloria perdida de Kartimas!",
  ui_story_5051_50511401_58_dialog_content = "Estamos completamente preparados y esperando su pedido.",
  ui_story_5051_50511401_59_dialog_content = "¡Prometemos defender el honor de la Casa Kartima hasta nuestra muerte!",
  ui_story_5051_50511401_60_dialog_content = "<size=45>¡Defiende el honor de Kartima! ¡Defiende el honor de Kartima! ¡Defiende el honor de Kartima!</size>",
  ui_story_5051_50511401_61_dialog_content = "¡Está bien!",
  ui_story_5051_50511401_62_dialog_content = "Ahora, permítanme desvelar nuestro refuerzo final.",
  ui_story_5051_50511401_63_dialog_content = "¿Refuerzos?",
  ui_story_5051_50511401_64_dialog_content = "\"El dragón que surca los cielos, el compañero eterno de Kartima\".",
  ui_story_5051_50511401_65_dialog_content = "\"Despliega tus alas y perfora la noche sin fin\".",
  ui_story_5051_50511401_66_dialog_content = "\"Ven a mí.\"",
  ui_story_5051_50511401_67_dialog_content = "\"Ven a nosotros.\"",
  ui_story_5051_50511401_68_dialog_content = "\"La casa Kartima nunca olvida nuestro pacto\".",
  ui_story_5051_50511401_69_dialog_content = "<anim type=Shake><size=45>Rugido-!</size></anim>",
  ui_story_5051_50511401_70_dialog_content = "Esa voz.",
  ui_story_5051_50511401_71_dialog_content = "¿Acabas de convocar al <color=#FFB400>continuar</color>, ¡¿mi señor?!",
  ui_story_5051_50511401_72_dialog_content = "El dragón siempre ha sido el aliado más leal de la Casa Kartima.",
  ui_story_5051_50511401_73_dialog_content = "Algunas personas envidiaban nuestro poder y convencieron a nuestros antepasados de que los dragones son presagios del mal.",
  ui_story_5051_50511401_74_dialog_content = "¿Algunas personas? ¿Podría ser esa casa? Schwartz...?",
  ui_story_5051_50511401_75_dialog_content = "<size=45>¡Ven, Ganón! ¡Ven con tus amigos y familiares!</size>",
  ui_story_5051_50511401_76_dialog_content = "<anim type=Shake><size=45>¡Gruñido!</size></anim>",
  ui_story_5051_50511401_77_dialog_content = "Ahora, no tenemos que preocuparnos más por los herejes.",
  ui_story_5051_50511401_78_dialog_content = "<anim type=Shake><size=45>¡Rugido!</size></anim>",
  ui_story_5051_50511401_79_dialog_content = "¡Escuchen, miembros de la Casa Kartima!",
  ui_story_5051_50511401_80_dialog_content = "¡El dragón ha vuelto!",
  ui_story_5051_50511401_81_dialog_content = "¡Nos ayudará a dominar Lumopolis!",
  ui_story_5051_50511401_82_dialog_content = "¡Viva el dragón!",
  ui_story_5051_50511401_83_dialog_content = "<anim type=Shake><size=45>Rugido-!!!</size></anim>",
  ui_story_5051_50511401_84_dialog_content = "<color=#e8d9bb>Mientras tanto en Umbraton</color>",
  ui_story_5051_50511401_85_dialog_content = "¿Escuchaste eso?",
  ui_story_5051_50511401_86_dialog_content = "¡Pensé que algo andaba mal con mi oído!",
  ui_story_5051_50511401_87_dialog_content = "No pueden ser Eclipsites atacando de nuevo, ¿verdad?",
  ui_story_5051_50511401_88_dialog_content = "¡Deja de decir tonterías y vete a casa!",
  ui_story_5051_50511401_89_dialog_content = "Sí, vamos a esperar nuestro destino en casa.",
  ui_story_5051_50511401_90_dialog_content = "Umbraton es más húmedo de lo que recordaba.",
  ui_story_5051_50511401_91_dialog_content = "Mirando Lumopolis desde este punto de vista...",
  ui_story_5051_50511401_92_dialog_content = "Se ve muy diferente.",
  ui_story_5051_50511401_93_dialog_content = "Las noches allá arriba se sienten más frías que aquí abajo.",
  ui_story_5051_50511401_94_dialog_content = "¿Ese rugido vino de un Eclipsite?",
  ui_story_5051_50511401_95_dialog_content = "No, no Eclipse.",
  ui_story_5051_50511401_96_dialog_content = "¿Qué más podría ser, entonces?",
  ui_story_5051_50511401_97_dialog_content = "Mira, ya viene.",
  ui_story_5051_50511401_98_dialog_content = "<anim type=Shake><size=45>Rugido-!</size></anim>",
  ui_story_5051_50511401_99_dialog_content = "¿Un dragón volador?",
  ui_story_5051_50511401_100_dialog_content = "Sí, de hecho están cegados por el odio del malvado dragón.",
  ui_story_5051_50511401_101_dialog_content = "¿Está el linaje de Kartima destinado a estar ligado para siempre a ese antiguo trato?",
  ui_story_5051_50511401_102_dialog_content = "¡El dragón va a estar aquí pronto!",
  ui_story_5051_50511401_103_dialog_content = "¡Atrás, Verónica!",
  ui_story_5051_50511401_104_dialog_content = "Déjame ver de qué es capaz este dragón.",
  ui_story_5051_50511401_105_dialog_content = "Es de tamaño enorme, capaz de escupir fuego.",
  ui_story_5051_50511401_106_dialog_content = "Para evitar lesiones graves, la mejor opción es golpear primero su punto vulnerable.",
  ui_story_5051_50511401_107_dialog_content = "Y el punto vulnerable de este dragón es...",
  ui_story_5051_50511401_108_dialog_content = "Sé lo que es, naturalmente.",
  ui_story_5051_50511401_109_dialog_content = "Se fue antes de que pudieras terminar.",
  ui_story_5051_50511401_110_dialog_content = "Veo que esta batalla va a tomar algún tiempo.",
  ui_story_5051_50511401_111_dialog_content = "¿No conocías el punto débil del dragón?",
  ui_story_5051_50511401_112_dialog_content = "¿O no fuiste capaz de acertar en el primer intento?",
  ui_story_5051_50511401_113_dialog_content = "...",
  ui_story_5051_50511401_114_dialog_content = "<color=#e8d9bb>Whoosh.</color>",
  ui_story_5051_50511401_115_dialog_content = "El viento está aumentando. Esto es diferente de lo que recordaba.",
  ui_story_5051_50511401_116_dialog_content = "(¿Simplemente ignoró selectivamente esa pregunta?)",
  ui_story_5051_50511401_117_dialog_content = "Si podemos aprovechar la dirección del viento, quizás...",
  ui_story_5051_50511401_118_dialog_content = "La batalla puede terminar temprano.",
  ui_story_5051_50511401_119_dialog_content = "Decir ah-!",
  ui_story_5051_50511401_120_dialog_content = "¡Luz de la Noche Blanca!",
  ui_story_5051_50511401_121_dialog_content = "<anim type=Shake>Grau!</anim>",
  ui_story_5051_50511401_122_dialog_content = "(Joven Schwartz golpeó al dragón precisamente en la garganta para evitar que respirara fuego temporalmente...)",
  ui_story_5051_50511401_123_dialog_content = "(¿Sin embargo, esa es su debilidad?)",
  ui_story_5051_50511401_124_dialog_content = "(Realmente no puedo decirlo, pero parece haber una figura en la espalda del dragón).",
  ui_story_5051_50511401_125_dialog_content = "¡Es Mimo Kartima!",
  ui_story_5051_50511401_126_dialog_content = "¿El capitán de los caballeros que conocimos cuando entramos en la ciudad?",
  ui_story_5051_50511401_127_dialog_content = "Je, ¿es esto todo lo que el dragón puede hacer?",
  ui_story_5051_50511401_128_dialog_content = "Veo que no necesito luchar con todas mis fuerzas.",
  ui_story_5051_50511401_129_dialog_content = "Considérese afortunado de resistir el primer ataque.",
  ui_story_5051_50511401_130_dialog_content = "No confundas la suerte con la destreza, estimado Señor de la Ciudad.",
  ui_story_5051_50511401_131_dialog_content = "Por casualidad evadiste la llama de Ganon, como por casualidad te convertiste en el Señor de la Ciudad.",
  ui_story_5051_50511401_132_dialog_content = "¿Ganón? Veo que nombraste a tu dragón.",
  ui_story_5051_50511401_133_dialog_content = "Este es un movimiento peligroso, Mime.",
  ui_story_5051_50511401_134_dialog_content = "Estarás increíblemente triste cuando lo maten.",
  ui_story_5051_50511401_135_dialog_content = "¡Hablas demasiado!",
  ui_story_5051_50511401_136_dialog_content = "¡Carga, Ganon!",
  ui_story_5051_50511401_137_dialog_content = "¡Entrega tu llama más feroz a este hombre ante ti!",
  ui_story_5051_50511401_138_dialog_content = "Un regalo tuyo a mi hombro es suficiente. No debo aceptar otro.",
  ui_story_5051_50511401_139_dialog_content = "Sin embargo, ¡permítame corresponder!",
  ui_story_5051_50511401_140_dialog_content = "¡Noches efímeras y días sin fin!",
  ui_story_5051_50511401_141_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5051_50511401_142_dialog_content = "¡A la carga!",
  ui_story_5051_50511401_143_dialog_content = "Los rebeldes están cargando...",
  ui_story_5051_50511401_144_dialog_content = "¡Todas las manos, escuchen!",
  ui_story_5051_50511401_145_dialog_content = "¡Prepárate para la batalla!",
  ui_story_5051_50511401_146_dialog_content = "...",
  ui_story_5051_50511401_147_dialog_content = "¿Estás luchando también, Mia?",
  ui_story_5051_50511401_148_dialog_content = "Si es posible, no quiero manchar mi arma con la sangre de mi gente...",
  ui_story_5051_50511401_149_dialog_content = "¿Por qué hicimos la elección en ese entonces, Padre?",
  ui_story_5051_50511401_150_dialog_content = "Porque querían manchar sus armas con nuestra sangre.",
  ui_story_5051_50511402_1_dialog_content = "<anim type=Shake>Rugido...</anim>",
  ui_story_5051_50511402_2_dialog_content = "¡No, Ganón!",
  ui_story_5051_50511402_3_dialog_content = "Esto no es real...",
  ui_story_5051_50511402_4_dialog_content = "¡No se supone que suceda así!",
  ui_story_5051_50511402_5_dialog_content = "(Joven Schwartz de hecho derrotó al dragón aprovechando el viento.)",
  ui_story_5051_50511402_6_dialog_content = "(Esta batalla terminó más rápido de lo que imaginé).",
  ui_story_5051_50511402_7_dialog_content = "Mimo Kartima!",
  ui_story_5051_50511402_8_dialog_content = "Como capitán de Lumopolis Knights, debes estar decidido a defender la ciudad.",
  ui_story_5051_50511402_9_dialog_content = "Pero elegiste traicionar a Lumopolis y la fe como un caballero.",
  ui_story_5051_50511402_10_dialog_content = "Has causado daños y sufrimientos irreparables a la gente de Lumopolis.",
  ui_story_5051_50511402_11_dialog_content = "¡Noche Blanca en lo alto!",
  ui_story_5051_50511402_12_dialog_content = "Tus acciones constituyeron traición.",
  ui_story_5051_50511402_13_dialog_content = "De ahora en adelante, serás despojado para siempre de todos los títulos y publicaciones.",
  ui_story_5051_50511402_14_dialog_content = "Estás condenado a esperar el juicio final de la Sala de Justicia en prisión.",
  ui_story_5051_50511402_15_dialog_content = "Je, ¿por qué esperar ...",
  ui_story_5051_50511402_16_dialog_content = "Solo matame ahora, Schwartz!",
  ui_story_5051_50511402_17_dialog_content = "¿No deseas volver a ver a tus parientes?",
  ui_story_5051_50511402_18_dialog_content = "¡Tú!",
  ui_story_5051_50511402_19_dialog_content = "Todo esto es mi culpa. ¡Nadie más tiene nada que ver con esto!",
  ui_story_5051_50511402_20_dialog_content = "Los obligué a atacar...",
  ui_story_5051_50511402_21_dialog_content = "Si todavía te queda un hilo de decencia, ¡perdona a los niños y ancianos!",
  ui_story_5051_50511402_22_dialog_content = "En este punto, la decisión no depende de mí.",
  ui_story_5051_50511402_23_dialog_content = "Guarda tu súplica para la corte.",
  ui_story_5051_50511402_24_dialog_content = "La Sala de Justicia dictará un juicio justo.",
  ui_story_5051_50511402_25_dialog_content = "Jejeje...",
  ui_story_5051_50511402_26_dialog_content = "<anim type=Shake><size=45>¡Jajaja!</size></anim>",
  ui_story_5051_50511402_27_dialog_content = "De hecho, no soy quien para salvar a la Casa Kartima...",
  ui_story_5051_50511402_28_dialog_content = "¡Si el anciano estaba en lo correcto, ella completaría la misión por mí!",
  ui_story_5051_50511402_29_dialog_content = "Eres tú quien acaba de destruir la Casa Kartima.",
  ui_story_5051_50511402_30_dialog_content = "Si hace públicamente el juramento de reforzar Umbraton conmigo como acordamos previamente...",
  ui_story_5051_50511402_31_dialog_content = "Tal vez el final sería diferente.",
  ui_story_5051_50511402_32_dialog_content = "¡Por qué tú...!",
  ui_story_5051_50511402_33_dialog_content = "¡De ninguna manera!",
  ui_story_5051_50511402_34_dialog_content = "¡¡Cuidado!!",
  ui_story_5051_50511402_35_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_5051_50511402_36_dialog_content = "Err...",
  ui_story_5051_50511402_37_dialog_content = "(Mime todavía trató de atacar a pesar de que sabía que era inútil...)",
  ui_story_5051_50511402_38_dialog_content = "Admiro tu valentía, Mime Kartima.",
  ui_story_5051_50511402_39_dialog_content = "Hágase cargo por mí, Sra. Rot.",
  ui_story_5051_50511402_40_dialog_content = "necesito verificar Carleen. Espérame en la sala de conferencias.",
  ui_story_5051_50511402_41_dialog_content = "¡Sí!",
  ui_story_5051_50511501_1_dialog_content = "Estoy de vuelta, Josué.",
  ui_story_5051_50511501_2_dialog_content = "Daniel...",
  ui_story_5051_50511501_3_dialog_content = "Déjame ver... ¿Se abrió la herida? ¿Alguna lesión nueva?",
  ui_story_5051_50511501_4_dialog_content = "Relájate, Josué. Te dije que estaría bien.",
  ui_story_5051_50511501_5_dialog_content = "Por cierto, ¿cómo es Carleen?",
  ui_story_5051_50511501_6_dialog_content = "El médico estuvo aquí y dijo que estaría bien después de unos días de descanso.",
  ui_story_5051_50511501_7_dialog_content = "Es bueno escuchar.",
  ui_story_5051_50511501_8_dialog_content = "La cena está lista para que usted participe.",
  ui_story_5051_50511501_9_dialog_content = "No, todavía tengo asuntos que atender.",
  ui_story_5051_50511501_10_dialog_content = "Deberías acostarte temprano.",
  ui_story_5051_50511501_11_dialog_content = "Has estado ocupado todo el día, Daniel. Tú eres el que debe entregarse.",
  ui_story_5051_50511501_12_dialog_content = "Debo consultar con el Consejo de Ancianos y el Salón de Justicia sobre el asunto con la Casa Kartima tan pronto como sea posible.",
  ui_story_5051_50511501_13_dialog_content = "Lo siento, Josué.",
  ui_story_5051_50511501_14_dialog_content = "La próxima vez, después de que termine con esto, los cuatro nos sentaremos a cenar en familia, ¿de acuerdo?",
  ui_story_5051_50511501_15_dialog_content = "Daniel, ¿puedes decirme qué le van a hacer a la Casa Kartima?",
  ui_story_5051_50511501_16_dialog_content = "Ni siquiera te preocupes por ello. Los Kartima obtendrán lo que se merecen.",
  ui_story_5051_50511501_17_dialog_content = "¿Qué pasa con aquellos que no sabían nada de eso?",
  ui_story_5051_50511501_18_dialog_content = "¿También se verán atrapados en él?",
  ui_story_5051_50511501_19_dialog_content = "No lo olvides, Josué.",
  ui_story_5051_50511501_20_dialog_content = "Hoy, esa gente de la Casa Kartima nos apuntó con espadas frías, a nuestras queridas hijas.",
  ui_story_5051_50511501_21_dialog_content = "Nunca consideraron inocentes a nuestras hijas cuando nos traicionaron.",
  ui_story_5051_50511501_22_dialog_content = "Pero...",
  ui_story_5051_50511501_23_dialog_content = "Déjame hacerte una pregunta, Daniel.",
  ui_story_5051_50511501_24_dialog_content = "¿Te enteraste de la trama de Kartima antes de tiempo?",
  ui_story_5051_50511501_25_dialog_content = "¿Quien te lo dijo?",
  ui_story_5051_50511501_26_dialog_content = "Eres tú, Daniel, no has estado actuando como tú mismo últimamente.",
  ui_story_5051_50511501_27_dialog_content = "Detén la teoría de la conspiración, ¿quieres?",
  ui_story_5051_50511501_28_dialog_content = "Pero, ¿cómo supiste que habría dos oleadas de eclipses?",
  ui_story_5051_50511501_29_dialog_content = "Además, pensé en esto...",
  ui_story_5051_50511501_30_dialog_content = "Cuando estábamos practicando, podías sentir un pequeño movimiento a cincuenta metros de distancia.",
  ui_story_5051_50511501_31_dialog_content = "Sin embargo, ¿no pudiste reaccionar a tiempo ante el evidente ataque del asesino?",
  ui_story_5051_50511501_32_dialog_content = "Hiciste eso... <color=#FFB400>a propósito</color>?",
  ui_story_5051_50511501_33_dialog_content = "Aunque no pude entender por qué lo hiciste.",
  ui_story_5051_50511501_34_dialog_content = "¿Es para ganarse la simpatía del público por la lesión y solidificar el caso contra Kartimas?",
  ui_story_5051_50511501_35_dialog_content = "No es lo que piensas.",
  ui_story_5051_50511501_36_dialog_content = "Si supiera sus planes, ¿por qué permitiría que tú y nuestros hijos vinieran?",
  ui_story_5051_50511501_37_dialog_content = "!!!",
  ui_story_5051_50511501_38_dialog_content = "Con Carleen y yo a tu lado, los rebeldes no sospecharían nada y seguirían con su plan...",
  ui_story_5051_50511501_39_dialog_content = "Nos trataste como <color=#FFB400>peones</color>!",
  ui_story_5051_50511501_40_dialog_content = "...",
  ui_story_5051_50511501_41_dialog_content = "Soy el Señor de la Ciudad de Lumopolis y decido el futuro de esta ciudad flotante.",
  ui_story_5051_50511501_42_dialog_content = "Con ese fin, me convertiré incluso a mí mismo en una pieza de ajedrez.",
  ui_story_5051_50511501_43_dialog_content = "Tal es la obligación que asumimos, Joshua.",
  ui_story_5051_50511501_44_dialog_content = "Sé que todo lo que hiciste fue para luchar contra los Eclipsites.",
  ui_story_5051_50511501_45_dialog_content = "Pero ¿por qué no me dijiste?",
  ui_story_5051_50511501_46_dialog_content = "Tal vez podamos idear un plan perfecto.",
  ui_story_5051_50511501_47_dialog_content = "No me quejaré de que me uses como peón.",
  ui_story_5051_50511501_48_dialog_content = "Pero, ¿cómo podrías realmente usar a nuestros hijos como piezas de ajedrez también?",
  ui_story_5051_50511501_49_dialog_content = "Y si Carleen consiguió-",
  ui_story_5051_50511501_50_dialog_content = "No dejaré que eso suceda.",
  ui_story_5051_50511501_51_dialog_content = "De hecho, ella está bastante bien ahora, ¿no es así?",
  ui_story_5051_50511501_52_dialog_content = "Eso fue pura suerte, pero ¿y si?",
  ui_story_5051_50511501_53_dialog_content = "Si hay una próxima vez, prométeme que me lo dirás de antemano.",
  ui_story_5051_50511501_54_dialog_content = "La política de la vida real es miles de veces más complicada que en los libros.",
  ui_story_5051_50511501_55_dialog_content = "Te amo, Josué...",
  ui_story_5051_50511501_56_dialog_content = "Por eso no quiero enredarte en la inmunda vorágine.",
  ui_story_5051_50511501_57_dialog_content = "Eso no es lo que me dijiste cuando estábamos en la escuela.",
  ui_story_5051_50511501_58_dialog_content = "Dijiste que cambiaremos Lumopolis juntos.",
  ui_story_5051_50511501_59_dialog_content = "Y ahora te niegas a confiar en mí.",
  ui_story_5051_50511501_60_dialog_content = "Siempre he confiado en ti. No tengo ningún problema en dejarte llevar la familia.",
  ui_story_5051_50511501_61_dialog_content = "Asimismo, debe confiar en mis decisiones en el ámbito político.",
  ui_story_5051_50511501_62_dialog_content = "Sacrificar a toda una familia para allanar el camino a tu dominación política.",
  ui_story_5051_50511501_63_dialog_content = "Si ese es tu juego final...",
  ui_story_5051_50511501_64_dialog_content = "Creo que ya no sé quién eres, Daniel...",
  ui_story_5051_50511501_65_dialog_content = "Estás empezando a hacer lo que sea necesario para asegurar tu asiento como el Señor de la Ciudad.",
  ui_story_5051_50511501_66_dialog_content = "No, no es solo lo que sea necesario.",
  ui_story_5051_50511501_67_dialog_content = "¡Tienes un corazón más gélido que la nieve en los picos de Northland!",
  ui_story_5051_50511501_68_dialog_content = "Verónica se convirtió en una rareza a la vista del público gracias a ti...",
  ui_story_5051_50511501_69_dialog_content = "Carleen probablemente perderá su vida algún día por tu culpa también...",
  ui_story_5051_50511501_70_dialog_content = "Yo también te dejaré y desapareceré del mundo...",
  ui_story_5051_50511501_71_dialog_content = "Josué... ¡Josué!",
  ui_story_5051_50511501_72_dialog_content = "¡Mi Josué!",
  ui_story_5051_50511501_73_dialog_content = "¿Por qué?",
  ui_story_5051_50511501_74_dialog_content = "<size=45>¡¿Por qué me dejaste?!</size>",
  ui_story_5051_50511501_75_dialog_content = "<anim type=Shake>Jadeo... Jadeo... Jadeo...</anim>",
  ui_story_5051_50511501_76_dialog_content = "¿Estás bien? ¿Hay algún problema?",
  ui_story_5051_50511501_77_dialog_content = "Josué!",
  ui_story_5051_50511501_78_dialog_content = "¿Qué le pasa, Sr. Soroz?",
  ui_story_5051_50511501_79_dialog_content = "Tu agarre está cortando la mano de Lady Joshua, PADRE.",
  ui_story_5051_50511501_80_dialog_content = "Lo siento mucho.",
  ui_story_5051_50511501_X80_dialog_content = "Por alguna razón me recuerda las pesadillas que tengo a menudo.",
  ui_story_5051_50511501_81_dialog_content = "Probablemente necesito más descanso a esta edad...",
  ui_story_5051_50511501_82_dialog_content = "Por favor, póngase cómodo. La comida se servirá en breve.",
  ui_story_5051_50511501_83_dialog_content = "Eres un gran anfitrión, Josué.",
  ui_story_5051_50511501_84_dialog_content = "La cena estará lista pronto. ¿Por qué no vamos todos al comedor?",
  ui_story_5051_50511501_85_dialog_content = "Yo no, todavía tengo asuntos que atender.",
  ui_story_5051_50511501_86_dialog_content = "Asegúrese de entregarse temprano después de que haya terminado, todos ustedes.",
  ui_story_5051_50511501_87_dialog_content = "Has estado ocupado todo el día, Daniel. Tú eres el que debe entregarse.",
  ui_story_5051_50511501_88_dialog_content = "...",
  ui_story_5051_50511501_89_dialog_content = "<size=30>PlayerName, haz algo para distraerlos, ¡rápido!</size>",
  ui_story_5051_50511501_90_dialog_content = "<size=30>¿Qué? ¿Por qué?</size>",
  ui_story_5051_50511501_91_dialog_content = "<size=30>De lo contrario, veremos una pelea que no deseo volver a presenciar...</size>",
  ui_story_5051_50511501_92_dialog_content = "Debo consultar con el Consejo de Ancianos y el Salón de Justicia sobre el asunto con la Casa Kartima tan pronto como sea posible.",
  ui_story_5051_50511501_93_dialog_content = "Lo siento, Josué.",
  ui_story_5051_50511501_94_dialog_content = "La próxima vez, después de que termine con esto, los cuatro nos sentaremos a cenar en familia, ¿de acuerdo?",
  ui_story_5051_50511501_95_dialog_content = "¡Sí, creo que es una gran idea!",
  ui_story_5051_50511501_96_dialog_content = "¿Ah?",
  ui_story_5051_50511501_97_dialog_content = "Los que deben trabajar deben trabajar, los que deben descansar deben descansar.",
  ui_story_5051_50511501_98_dialog_content = "Creo... que es lo mejor para todos.",
  ui_story_5051_50511501_99_dialog_content = "Sí, los niños y yo estamos hambrientos dadas las actividades de hoy.",
  ui_story_5051_50511501_100_dialog_content = "Tómese su tiempo y descanse un poco, Sr. Soroz. Podemos charlar otro día.",
  ui_story_5051_50511501_101_dialog_content = "Eso es todo.",
  ui_story_5051_50511501_102_dialog_content = "...",
  ui_story_5051_50511501_103_dialog_content = "Y se va así como así.",
  ui_story_5051_50511501_104_dialog_content = "Lo siento, Sr. Soroz, pero necesitaré unos minutos.",
  ui_story_5051_50511501_105_dialog_content = "La cena debería estar lista pronto.",
  ui_story_5051_50511501_106_dialog_content = "Gracias.",
  ui_story_5051_50511501_107_dialog_content = "Es imposible para mí imaginarte discutiendo con alguien tan dulce como Lady Joshua.",
  ui_story_5051_50511501_108_dialog_content = "¿Tú y mamá... discutieron en este día?",
  ui_story_5051_50511501_109_dialog_content = "...",
  ui_story_5051_50511501_110_dialog_content = "¿Eres tan cobarde como para admitir lo que hiciste?",
  ui_story_5051_50511501_111_dialog_content = "¿Caleb? ¿De donde vienes?",
  ui_story_5051_50511501_112_dialog_content = "¿Tío?",
  ui_story_5051_50511501_113_dialog_content = "he oído Jakine huir y dejarte atrás, Caleb. ¿Cuándo vas a mostrar algo de madurez?",
  ui_story_5051_50511501_114_dialog_content = "No se vaya por la tangente, señor de la ciudad.",
  ui_story_5051_50511501_115_dialog_content = "¿De verdad no vas a admitir lo que hiciste?",
  ui_story_5051_50511501_116_dialog_content = "Entonces déjame refrescarte la memoria.",
  ui_story_5051_50511501_117_dialog_content = "Por esa discusión, mi hermana se fue de Castle. Schwartz con Carleen.",
  ui_story_5051_50511501_118_dialog_content = "Ustedes dos prácticamente nunca volvieron a hablar o tuvieron una comida familiar juntos...",
  ui_story_5051_50511501_119_dialog_content = "Hasta que mi hermana trajo a la moribunda Veronica del campo de batalla.",
  ui_story_5051_50511501_120_dialog_content = "Fingiste estar enterrado en la lucha contra los Eclipsites, cuando en realidad, no querías enfrentarte a ella...",
  ui_story_5051_50511501_121_dialog_content = "Luego, debido a sus ambiciones políticas, envió a la herida Veronica a ese laboratorio en Illumina.",
  ui_story_5051_50511501_122_dialog_content = "Sin saber que la instalación estaba dirigida por lunáticos despiadados.",
  ui_story_5051_50511501_123_dialog_content = "Mi hermana una vez más rescató a Verónica del laboratorio, pero resultó gravemente herida y quedó postrada en cama...",
  ui_story_5051_50511501_124_dialog_content = "¿Tengo razón, cuñado?",
  ui_story_5051_50511501_125_dialog_content = "<color=#FFB400>laboratorio de iluminación</color>... Me duele la cabeza.",
  ui_story_5051_50511501_126_dialog_content = "Siéntate, Mia. Deja de pensar en el pasado.",
  ui_story_5051_50511501_127_dialog_content = "...",
  ui_story_5051_50511501_128_dialog_content = "¿Adónde te escapaste, Caleb?",
  ui_story_5051_50511501_129_dialog_content = "Has estado desaparecido durante todo un día. ¡Me hizo pensar que no querías irte!",
  ui_story_5051_50511501_130_dialog_content = "Estuve aquí todo el tiempo, simplemente no me reconoció.",
  ui_story_5051_50511501_131_dialog_content = "No quería que mi presencia la distrajera...",
  ui_story_5051_50511501_132_dialog_content = "Pero sí, no puedo quedarme más.",
  ui_story_5051_50511501_133_dialog_content = "Sácame de aquí, Jakine!",
  ui_story_5051_50511501_134_dialog_content = "Eso es lo más directo que puedes conseguir para alguien que ha estado desaparecido.",
  ui_story_5051_50511501_135_dialog_content = "Bueno, todos están aquí, ¿no deberíamos irnos ahora?",
  ui_story_5051_50511501_136_dialog_content = "¿No dijiste que tenemos que dejar el Cristal de la Memoria Eterna rápido o habría problemas?",
  ui_story_5051_50511501_137_dialog_content = "Sí, dije eso.",
  ui_story_5051_50511501_138_dialog_content = "¿Listos para partir, todos?",
  ui_story_5051_50511501_139_dialog_content = "Madre todavía nos espera para la cena...",
  ui_story_5051_50511501_140_dialog_content = "Todavía hay tiempo. Podemos quedarnos un rato.",
  ui_story_5051_50511501_141_dialog_content = "¿Pero no nos estabas instando a que nos fuéramos antes, Señor de la Ciudad?",
  ui_story_5051_50511501_142_dialog_content = "Eso es porque todos estábamos en peligro.",
  ui_story_5051_50511501_143_dialog_content = "Pero ahora la mayor amenaza ha pasado.",
  ui_story_5051_50511501_144_dialog_content = "Y...",
  ui_story_5051_50511501_145_dialog_content = "(Tal vez Caleb tenga razón. Esa pelea fue el principio del fin).",
  ui_story_5051_50511501_146_dialog_content = "(Mientras obtuve el apoyo de todos los nobles en Lumopolis ese día, lastimé profundamente a mi amada).",
  ui_story_5051_50511501_147_dialog_content = "¿Padre?",
  ui_story_5051_50511501_148_dialog_content = "Ni hablar si nos vamos ahora...",
  ui_story_5051_50511501_149_dialog_content = "Joshua se quedará solo para pasar una noche estresante como antes.",
  ui_story_5051_50511501_150_dialog_content = "¿Por qué tratas de convencer con tu acto, Schwartz?",
  ui_story_5051_50511501_151_dialog_content = "Sé que siempre me odiaste por lo que le pasó a Joshua, Caleb.",
  ui_story_5051_50511501_152_dialog_content = "Es demasiado tarde para reparar los errores del pasado.",
  ui_story_5051_50511501_153_dialog_content = "Entiendo la animosidad que sientes hacia mí.",
  ui_story_5051_50511501_154_dialog_content = "Si tengo otra oportunidad, no la dejaré...",
  ui_story_5051_50511501_155_dialog_content = "Heh, no sirve de nada hablar de eso ahora.",
  ui_story_5051_50511501_156_dialog_content = "Todo este mundo es falso hasta la médula...",
  ui_story_5051_50511501_157_dialog_content = "¡La expiación aquí no cambiará nada!",
  ui_story_5051_50511501_158_dialog_content = "T-tío...",
  ui_story_5051_50511501_159_dialog_content = "Quisiera despedirme de mamá",
  ui_story_5051_50511501_160_dialog_content = "Sé que este mundo no es real, pero las emociones ciertamente lo son.",
  ui_story_5051_50511501_161_dialog_content = "Por favor danos este precioso último momento.",
  ui_story_5051_50511501_162_dialog_content = "A-En realidad, me gustaría despedirme de alguien también.",
  ui_story_5051_50511501_163_dialog_content = "Todavía tenemos tiempo y ninguna amenaza por el momento...",
  ui_story_5051_50511501_164_dialog_content = "Entonces, ¿por qué no van todos a despedirse?",
  ui_story_5051_50511501_165_dialog_content = "Es posible que no nos reconozcan la próxima vez que vengamos, después de todo.",
  ui_story_5051_50511501_166_dialog_content = "Tu gente...!",
  ui_story_5051_50511501_167_dialog_content = "Mente acompañándome para mi despedida, PlayerName?",
  ui_story_5051_50511501_168_dialog_content = "Solo soy un extraño para ella ahora. No será apropiado sin usted presente.",
  ui_story_5051_50511501_169_dialog_content = "Pero, ¿cómo vas a decir lo que quieres decir cuando se supone que eres mi padre?",
  ui_story_5051_50511501_170_dialog_content = "Si tan solo Joshua pudiera reconocerte...",
  ui_story_5051_50511501_171_dialog_content = "Ey, Jakine, ¿no puedes controlar el Cristal?",
  ui_story_5051_50511501_172_dialog_content = "¿Alguna forma de hacer que Joshua reconozca a nuestro Señor de la Ciudad?",
  ui_story_5051_50511501_173_dialog_content = "Bueno, no es que no haya manera...",
  ui_story_5051_50511501_174_dialog_content = "Es solo que nunca lo he intentado antes y no quiero otro error.",
  ui_story_5051_50511501_175_dialog_content = "Está bien. Intentalo.",
  ui_story_5051_50511501_176_dialog_content = "¿Confías en mí, Señor de la Ciudad?",
  ui_story_5051_50511501_177_dialog_content = "Supongo que ya no tengo excusas. ¡Te ayudaré a limpiar el aire!",
  ui_story_5051_50511501_178_dialog_content = "Sin embargo...",
  ui_story_5051_50511501_179_dialog_content = "¡Dame tiempo para leer mi libro primero! Jejeje.",
  ui_story_5051_50511501_180_dialog_content = "Ejem, ¿funcionará esto, mi señor?",
  ui_story_5051_50511501_181_dialog_content = "Me he agachado y esquivado durante más de una década, joven...",
  ui_story_5051_50511501_182_dialog_content = "Para mí, venir aquí puede no ser pura coincidencia.",
  ui_story_5051_50511501_183_dialog_content = "Quizás el Dios de la Luz me está guiando.",
  ui_story_5051_50511501_184_dialog_content = "Es hora de que enfrente mi cobardía.",
  ui_story_5051_50511501_185_dialog_content = "Debo recordarle que la ilusión solo durará un poco, mi señor.",
  ui_story_5051_50511501_186_dialog_content = "¡Asegúrate de volver antes de que se acabe el tiempo!",
  ui_story_5051_50511501_187_dialog_content = "Estoy listo.",
  ui_story_5051_50511501_188_dialog_content = "¡Déjame empezar, entonces!",
  ui_story_5051_50511501_189_dialog_content = "¡Mutatio! ¡Mutatio! ¡Mutatio!",
  ui_story_5051_50511501_190_dialog_content = "por favor cambia daniel Schwartz de vuelta a su día más joven!",
  ui_story_5051_50511501_191_dialog_content = "¡Abracadabra!",
  ui_story_5051_50511501_192_dialog_content = "<color=#828282>¡Bam!</color>",
  ui_story_5051_50511501_193_dialog_content = "¡Wow!",
  ui_story_5051_50511501_194_dialog_content = "¿Qué está pasando? Por qué estás tan sorprendido, PlayerName?",
  ui_story_5051_50511501_195_dialog_content = "Ciertamente te ves... memorable cuando eras joven.",
  ui_story_5051_50511501_196_dialog_content = "Bu ju...",
  ui_story_5051_50511501_197_dialog_content = "Uh, ¿cómo es que cambiaste a City Lord para que se pareciera a Judge Jr.?",
  ui_story_5051_50511501_198_dialog_content = "Judge Jr.?!",
  ui_story_5051_50511501_199_dialog_content = "Ejem... Supongo que me emocioné demasiado y no imaginé cómo se veía tu yo joven en mi mente...",
  ui_story_5051_50511501_200_dialog_content = "¿No conocimos a su yo más joven hace unos minutos?",
  ui_story_5051_50511501_201_dialog_content = "¡Oh, es cierto!",
  ui_story_5051_50511501_202_dialog_content = "Eso debería hacerlo más fácil. ¡Déjame intentar de nuevo!",
  ui_story_5051_50511501_203_dialog_content = "¡Mutatio! ¡Mutatio! ¡Mutatio!",
  ui_story_5051_50511501_204_dialog_content = "por favor cambia daniel Schwartz de vuelta a su día más joven!",
  ui_story_5051_50511501_205_dialog_content = "¡Abracadabra!",
  ui_story_5051_50511501_206_dialog_content = "<color=#828282>¡Bam!</color>",
  ui_story_5051_50511501_207_dialog_content = "¿Eres tú en la puerta, guardia?",
  ui_story_5051_50511501_208_dialog_content = "La cena está lista. ¿Te importaría informar a todos por mí?",
  ui_story_5051_50511501_209_dialog_content = "...",
  ui_story_5051_50511501_210_dialog_content = "¿Guardia?",
  ui_story_5051_50511501_211_dialog_content = "¿Eres tu?",
  ui_story_5051_50511501_212_dialog_content = "...",
  ui_story_5051_50511501_213_dialog_content = "<size=30>Lo siento.</size>",
  ui_story_5051_50511501_214_dialog_content = "¿Qué dijiste?",
  ui_story_5051_50511501_215_dialog_content = "Nada.",
  ui_story_5051_50511501_216_dialog_content = "¿Acabas de decir lo siento, Daniel?",
  ui_story_5051_50511501_217_dialog_content = "Josué...",
  ui_story_5051_50511501_218_dialog_content = "Es bueno que estés de vuelta.",
  ui_story_5051_50511501_219_dialog_content = "Deberías volver a casa cuando estés exhausto.",
  ui_story_5051_50511501_220_dialog_content = "Estoy bien. Y los niños y yo nos quedaremos contigo, siempre.",
  ui_story_5051_50511501_221_dialog_content = "...",
  ui_story_5051_50511501_222_dialog_content = "Tómate un descanso mientras consigo que alguien coloque otro asiento en la mesa.",
  ui_story_5051_50511501_223_dialog_content = "...",
  ui_story_5051_50511501_224_dialog_content = "¿Cómo voy a hacer algo contigo aferrándote a mí, Daniel?",
  ui_story_5051_50511501_225_dialog_content = "Tengo mucho que quiero contarte.",
  ui_story_5051_50511501_226_dialog_content = "¿Finalmente recordaste que hay alguien más en la familia que escuchará tus quejas?",
  ui_story_5051_50511501_227_dialog_content = "¿Qué es, y tiene que ser ahora?",
  ui_story_5051_50511501_228_dialog_content = "Sí.",
  ui_story_5051_50511501_229_dialog_content = "Muy bien, supongo que todos tendrán que aguantar el hambre un poco más.",
  ui_story_5051_50511501_230_dialog_content = "¡Vamos a escuchar lo que tienes que decir!",
  ui_story_5051_50511501_231_dialog_content = "...",
  ui_story_5051_50511501_232_dialog_content = "Te extraño mucho.",
  ui_story_5051_50511501_233_dialog_content = "¿Ah?",
  ui_story_5051_50511501_234_dialog_content = "<color=#e8d9bb>en un rincón</color>",
  ui_story_5051_50511501_235_dialog_content = "Darse prisa, Jakine!",
  ui_story_5051_50511501_236_dialog_content = "¿Por qué tu hechizo deja de funcionar cuando es mi turno?",
  ui_story_5051_50511501_237_dialog_content = "¡Oye, no me apresures, está bien! Tienes que estar de humor para lanzar el hechizo, ya sabes.",
  ui_story_5051_50511501_238_dialog_content = "¡O tal vez preferiste la cabeza de yeso que acabamos de ver!",
  ui_story_5051_50511501_239_dialog_content = "¡Tú!",
  ui_story_5051_50511501_240_dialog_content = "Mi padre... ¿Se lo sacó del pecho?",
  ui_story_5051_50511501_241_dialog_content = "Creo que sí por lo que parece. Esos dos todavía parecen bastante amigos.",
  ui_story_5051_50511501_242_dialog_content = "<size=45>¡Ahhh! ¡Qué intenta hacerle ese hipócrita a mi hermana!</size>",
  ui_story_5051_50511501_243_dialog_content = "¿Por qué acabas de taparme los ojos? PlayerName?",
  ui_story_5051_50511501_244_dialog_content = "¿No eres tú quien me tapó los ojos, Mia?",
  ui_story_5051_50511501_245_dialog_content = "Caramba, cada uno de ustedes, mocosos...",
  ui_story_5051_50511501_246_dialog_content = "<size=45>¡No más mirar a escondidas!</size>",
  ui_story_5051_50511601_1_dialog_content = "Huff... Huff... Huff...",
  ui_story_5051_50511601_2_dialog_content = "¿Cómo puede alguien seguir fuera después de esa cura para la resaca?",
  ui_story_5051_50511601_3_dialog_content = "Pero está bien, esto me da la oportunidad de llamarte en voz alta...",
  ui_story_5051_50511601_4_dialog_content = "M-mamá...",
  ui_story_5051_50511601_5_dialog_content = "Je, ¿qué me pasa? Me siento un poco incómodo gritándolo.",
  ui_story_5051_50511601_6_dialog_content = "He esperado volver a verte desde que te fuiste de casa hace una docena de años para meditar.",
  ui_story_5051_50511601_7_dialog_content = "Fantaseaba que algún día podría encontrar dónde estás con la adivinación.",
  ui_story_5051_50511601_8_dialog_content = "Y me preguntaba si todavía te veías igual...",
  ui_story_5051_50511601_9_dialog_content = "Siempre usando un velo, estando ocupado en una remota cabaña en el bosque solo.",
  ui_story_5051_50511601_10_dialog_content = "Pero han pasado los años y mis recuerdos de ti se han vuelto borrosos.",
  ui_story_5051_50511601_11_dialog_content = "Imagina mi sorpresa cuando me encontré con tu joven en Lumopolis hoy.",
  ui_story_5051_50511601_12_dialog_content = "Lo que es aún más sorprendente es que parecías tan... ¡poco confiable!",
  ui_story_5051_50511601_13_dialog_content = "Pero en comparación con lo que recordaba, eras aún más extrovertida, adorable, descarada...",
  ui_story_5051_50511601_14_dialog_content = "Después de que te fuiste, papá pensó en mudarnos de Northland.",
  ui_story_5051_50511601_15_dialog_content = "Pero temí que si nos íbamos, no nos encontrarías cuando regresaras, así que me quedé atrás, solo.",
  ui_story_5051_50511601_16_dialog_content = "Pero no te preocupes, ¡tengo montones, montones de amigos!",
  ui_story_5051_50511601_17_dialog_content = "Aprendí hechizos del libro de adivinación que dejaste atrás... Aunque todavía no soy muy bueno y cometí muchos errores.",
  ui_story_5051_50511601_18_dialog_content = "¡Pero solo espera!",
  ui_story_5051_50511601_19_dialog_content = "¡Me convertiré en el mejor alumno de Booz y crearé una bola de cristal aún más poderosa que el Cristal de la Memoria Eterna!",
  ui_story_5051_50511601_20_dialog_content = "Tal vez entonces pueda detectar dónde te escondes en Northland.",
  ui_story_5051_50511601_21_dialog_content = "De todos modos, ¡ya verás cuando nos volvamos a encontrar!",
  ui_story_5051_50511601_22_dialog_content = "Mi niño.",
  ui_story_5051_50511601_23_dialog_content = "¿Qué? ¿Estas despierto?",
  ui_story_5051_50511601_24_dialog_content = "Ejem, solo estaba bromeando. No le hagas caso.",
  ui_story_5051_50511601_25_dialog_content = "No es que comprendas una palabra de lo que dije, de todos modos... Lamento despertarte. Solo quería despedirme.",
  ui_story_5051_50511601_26_dialog_content = "Oh, ¿piensas tan mal de mi comprensión?",
  ui_story_5051_50511601_27_dialog_content = "Sí, ya que has estado borracho todo este tiempo...",
  ui_story_5051_50511601_28_dialog_content = "Espera, ¿por qué estás actuando en serio ahora? ¡No estoy acostumbrado a esto!",
  ui_story_5051_50511601_29_dialog_content = "Se necesitarán habilidades mucho más allá de su nivel actual para desbloquear los secretos de Crystal.",
  ui_story_5051_50511601_30_dialog_content = "Y mucho menos crear uno.",
  ui_story_5051_50511601_31_dialog_content = "¿Estás seguro de que eso es lo que quieres hacer? Jakine?",
  ui_story_5051_50511601_32_dialog_content = "¡Sí, cien por cien seguro!",
  ui_story_5051_50511601_33_dialog_content = "Espera, ¿no te negaste a admitir que soy tu hija?",
  ui_story_5051_50511601_34_dialog_content = "Tú, de hecho, no eres MI hija. Jakine.",
  ui_story_5051_50511601_35_dialog_content = "Pero también sé que de hecho eres Jakine.",
  ui_story_5051_50511601_36_dialog_content = "Por fin estás de vuelta, Jakine.",
  ui_story_5051_50511601_37_dialog_content = "Oye, lo siento, tenía mucho que decir y olvidé la hora.",
  ui_story_5051_50511601_38_dialog_content = "¿Qué ocurre? ¿Algo te esta molestando?",
  ui_story_5051_50511601_39_dialog_content = "E-¿Hay?",
  ui_story_5051_50511601_40_dialog_content = "Oh, Caleb, ¿quieres intentarlo de nuevo? ¡Te garantizo que te haré lucir más joven!",
  ui_story_5051_50511601_X41_dialog_content = "Olvídalo. Tener cabeza de conejo no es para mí.",
  ui_story_5051_50511601_42_dialog_content = "Shhh...",
  ui_story_5051_50511601_43_dialog_content = "Que el Padre y la Madre no nos descubran.",
  ui_story_5051_50511601_44_dialog_content = "¿El Señor de la Ciudad todavía se está despidiendo de Lady Joshua?",
  ui_story_5051_50511601_45_dialog_content = "No parece que vaya a terminar pronto...",
  ui_story_5051_50511601_46_dialog_content = "Hmm, ¿cómo es que los niños y los invitados aún no están aquí?",
  ui_story_5051_50511601_47_dialog_content = "Ellos... ya están dormidos.",
  ui_story_5051_50511601_48_dialog_content = "Todos hemos tenido un día agotador, ¡pero no podemos saltarnos las comidas!",
  ui_story_5051_50511601_49_dialog_content = "Conseguiré que alguien envíe comida a sus habitaciones...",
  ui_story_5051_50511601_50_dialog_content = "Ya di la orden. No tienes que preocuparte por eso.",
  ui_story_5051_50511601_51_dialog_content = "¿Oh? Esto es diferente a ti, Daniel.",
  ui_story_5051_50511601_52_dialog_content = "¿Te sientes culpable por algo?",
  ui_story_5051_50511601_53_dialog_content = "¿Te sientes culpable?",
  ui_story_5051_50511601_54_dialog_content = "Sí. De lo contrario, ¿por qué el Señor de la Ciudad inundada de repente haría tiempo para su esposa?",
  ui_story_5051_50511601_55_dialog_content = "Yo solo siento...",
  ui_story_5051_50511601_56_dialog_content = "Hacía tiempo que no nos sentábamos a disfrutar de una cena así en pareja.",
  ui_story_5051_50511601_57_dialog_content = "Eso es cierto, pero pensé que ya no te importaba.",
  ui_story_5051_50511601_58_dialog_content = "Lo siento.",
  ui_story_5051_50511601_59_dialog_content = "Oh, ¿por qué has estado diciendo eso todo el tiempo esta noche?",
  ui_story_5051_50511601_60_dialog_content = "¿Qué te obligó a disculparte conmigo?",
  ui_story_5051_50511601_61_dialog_content = "No puedo decírtelo en este momento.",
  ui_story_5051_50511601_62_dialog_content = "Daniel...",
  ui_story_5051_50511601_63_dialog_content = "¿Es por la Casa Kartima?",
  ui_story_5051_50511601_64_dialog_content = "¿De verdad no vas a dejar ir a cada uno de ellos, Daniel?",
  ui_story_5051_50511601_65_dialog_content = "...",
  ui_story_5051_50511601_66_dialog_content = "No es verdad.",
  ui_story_5051_50511601_67_dialog_content = "Solo los verdaderos infractores deben ser castigados.",
  ui_story_5051_50511601_68_dialog_content = "¿Acabas de mentir para aplacarme?",
  ui_story_5051_50511601_69_dialog_content = "¡No es eso, Josué!",
  ui_story_5051_50511601_70_dialog_content = "<color=#e8d9bb>¡Hacer clic!</color>",
  ui_story_5051_50511601_71_dialog_content = "Josué?",
  ui_story_5051_50511601_72_dialog_content = "<anim type=Shake>Mintiéndome.</anim>",
  ui_story_5051_50511601_73_dialog_content = "Josué?",
  ui_story_5051_50511601_74_dialog_content = "¡¿Qué pasa, Josué?!",
  ui_story_5051_50511601_75_dialog_content = "<anim type=Shake>Me mentiste...</anim>",
  ui_story_5051_50511601_76_dialog_content = "¿Tuve la culpa de lo que te convertiste, Joshua?",
  ui_story_5051_50511601_77_dialog_content = "Puse todo en deshacerse de la Casa Kartima...",
  ui_story_5051_50511601_78_dialog_content = "No confié en tu juicio, eligiendo ignorar tu consejo...",
  ui_story_5051_50511601_79_dialog_content = "No aprecié tu esfuerzo, encomendándote cada obligación familiar...",
  ui_story_5051_50511601_80_dialog_content = "No estuve a tu lado cuando más me necesitabas...",
  ui_story_5051_50511601_81_dialog_content = "¡Lo siento!",
  ui_story_5051_50511601_82_dialog_content = "<color=#e8d9bb>¡Grieta!</color>",
  ui_story_5051_50511601_83_dialog_content = "<anim type=Shake>Daniel...</anim>",
  ui_story_5051_50511601_84_dialog_content = "¡Estoy aquí, estoy aquí, Josué!",
  ui_story_5051_50511601_85_dialog_content = "<anim type=Shake>Daniel... Verónica... Carleen...</anim>",
  ui_story_5051_50511601_86_dialog_content = "<anim type=Shake>¡¡¡Ahhhh!!!</anim>",
  ui_story_5051_50511601_87_dialog_content = "Josué!",
  ui_story_5051_50511601_88_dialog_content = "¿Madre? ¿Qué le pasó a mamá?",
  ui_story_5051_50511601_89_dialog_content = "<color=#e8d9bb>Retumbar</color>",
  ui_story_5051_50511601_90_dialog_content = "<color=#e8d9bb>Retumbar-!!!</color>",
  ui_story_5051_50511601_91_dialog_content = "¿Otra vez ese ruido de trueno?",
  ui_story_5051_50511601_92_dialog_content = "¿Terremoto? ¿Es un terremoto?",
  ui_story_5051_50511601_93_dialog_content = "No. Ningún terremoto esa noche en la historia real.",
  ui_story_5051_50511601_94_dialog_content = "No creo que pueda ver nada...",
  ui_story_5051_50511601_95_dialog_content = "¡Yo también! Estoy recurriendo a los pocos poderes psíquicos que me quedan para discernir la dirección.",
  ui_story_5051_50511601_96_dialog_content = "¿Ya casi se acaba el tiempo? Jakine?",
  ui_story_5051_50511601_97_dialog_content = "No, todavía deberíamos tener mucho tiempo hasta que termine el día. ¡¿Esto no puede ser?!",
  ui_story_5051_50511601_98_dialog_content = "¡No me digas que estamos a punto de caer por las grietas entre el Cristal y el mundo real!",
  ui_story_5051_50511601_99_dialog_content = "Que estas esperando, Jakine?",
  ui_story_5051_50511601_100_dialog_content = "¡Sácanos a todos!",
  ui_story_5051_50511601_101_dialog_content = "¡Reúnanse a mi alrededor, todos!",
  ui_story_5051_50511601_102_dialog_content = "Pero nos falta mi padre...",
  ui_story_5051_50511601_103_dialog_content = "Es apropiado que ese tipo santurrón esté atrapado aquí. ¡Olvídalo, vámonos!",
  ui_story_5051_50511601_104_dialog_content = "Incluso si es el más vil de los sinvergüenzas, no deberíamos dejarlo así...",
  ui_story_5051_50511601_105_dialog_content = "Llamado al Señor de la Ciudad",
  ui_story_5051_50511601_106_dialog_content = "Estamos aquí, Señor Schwartz!",
  ui_story_5051_50511601_107_dialog_content = "¡Padre!",
  ui_story_5051_50511601_108_dialog_content = "Caballero Schwartz!",
  ui_story_5051_50511601_109_dialog_content = "¿Por qué no responde...?",
  ui_story_5051_50511601_110_dialog_content = "Póngase en contacto con City Lord mentalmente",
  ui_story_5051_50511601_111_dialog_content = "Maldiciones...",
  ui_story_5051_50511601_112_dialog_content = "¡Todavía no puedo contactar a nadie mentalmente en el Cristal!",
  ui_story_5051_50511601_113_dialog_content = "¡Oh!",
  ui_story_5051_50511601_114_dialog_content = "¿Qué te pasa, Mia?",
  ui_story_5051_50511601_115_dialog_content = "El espacio detrás de nosotros... ¡Se está derrumbando lentamente en el vacío!",
  ui_story_5051_50511601_116_dialog_content = "tengo prisa, PlayerName!",
  ui_story_5051_50511601_117_dialog_content = "¡Sígueme y dirígete hacia donde estaba el Señor de la Ciudad!",
  ui_story_5051_50511601_118_dialog_content = "Jakine, si aún no podemos verlo en el último segundo...",
  ui_story_5051_50511601_119_dialog_content = "¡Sácanos de aquí!",
  ui_story_5051_50511601_120_dialog_content = "¡Está bien!",
  ui_story_5051_50511601_121_dialog_content = "Psst.",
  ui_story_5051_50511601_122_dialog_content = "<color=#e8d9bb>¡Whoosh!</color>",
  ui_story_5051_50511601_123_dialog_content = "¿Alguien pasó corriendo?",
  ui_story_5051_50511601_124_dialog_content = "¿Quién podría correr tan rápido bajo las circunstancias?",
  ui_story_5051_50511601_125_dialog_content = "<anim type=Shake><size=30>Daniel... Verónica... Carleen...</size></anim>",
  ui_story_5051_50511601_126_dialog_content = "¿Alguien está llamando mi nombre?",
  ui_story_5051_50511601_127_dialog_content = "Apenas se escucha. No puedo decir de dónde viene.",
  ui_story_5051_50511601_128_dialog_content = "<anim type=Shake>¿Aquí?</anim>",
  ui_story_5051_50511601_129_dialog_content = "Qué...",
  ui_story_5051_50511601_130_dialog_content = "¡Cuidado!",
  ui_story_5051_50511601_131_dialog_content = "¡Padre!",
  ui_story_5051_50511601_132_dialog_content = "Esté alerta, tenemos un visitante no invitado aquí.",
  ui_story_5051_50511601_133_dialog_content = "Qué ataque tan despiadado... ¿Quién nos asaltaría así?",
  ui_story_5051_50511601_134_dialog_content = "¿Ya estamos en la brecha entre el Cristal y el mundo real?",
  ui_story_5051_50511601_135_dialog_content = "¡No! No-!",
  ui_story_5051_50511601_136_dialog_content = "<anim type=Shake>¿Aquí?</anim>",
  ui_story_5051_50511601_137_dialog_content = "¡Eek, monstruo!",
  ui_story_5051_50511601_138_dialog_content = "Solo tú puedes decir la dirección ahora, PlayerName.",
  ui_story_5051_50511601_139_dialog_content = "¡Tomar la iniciativa!",
  ui_story_5051_50511602_1_dialog_content = "Buf... buf...",
  ui_story_5051_50511602_2_dialog_content = "Pausa para un descanso, Mia!",
  ui_story_5051_50511602_3_dialog_content = "Pero... no, quiero ayudarte, ayudar a todos...",
  ui_story_5051_50511602_4_dialog_content = "¿Aqui?",
  ui_story_5051_50511602_5_dialog_content = "¡Actívate, bola de cristal!",
  ui_story_5051_50511602_6_dialog_content = "Vamos, ¿por qué el monstruo sigue atacando?",
  ui_story_5051_50511602_7_dialog_content = "¿Cómo es que hay tal monstruo en el Cristal, Jakine?",
  ui_story_5051_50511602_8_dialog_content = "Yo tampoco tengo idea.",
  ui_story_5051_50511602_9_dialog_content = "¿Estás seguro de que no es algo que apareció en Lumopolis?",
  ui_story_5051_50511602_10_dialog_content = "...",
  ui_story_5051_50511602_11_dialog_content = "¡Noche Blanca, protégenos!",
  ui_story_5051_50511602_12_dialog_content = "No había tal monstruo en Lumopolis en ese momento.",
  ui_story_5051_50511602_13_dialog_content = "¡Pero no cedas!",
  ui_story_5051_50511602_14_dialog_content = "Comparado con antes, sus poderes obviamente han disminuido y los intervalos entre ataques son cada vez más largos.",
  ui_story_5051_50511602_15_dialog_content = "Jakine, después de que ataque de nuevo, ¡sácanos durante la brecha!",
  ui_story_5051_50511602_16_dialog_content = "Lo tengo, Señor Schwartz!",
  ui_story_5051_50511602_17_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5051_50511602_18_dialog_content = "¿Cómo es que todo se detuvo de repente?",
  ui_story_5051_50511602_19_dialog_content = "Tranquilo... ¿Escuchaste eso?",
  ui_story_5051_50511602_20_dialog_content = "<anim type=Shake><size=30>Daniel... Verónica... Carleen...</size></anim>",
  ui_story_5051_50511602_21_dialog_content = "¿Está llamando mi nombre y el de mi padre y hermana?",
  ui_story_5051_50511602_22_dialog_content = "<anim type=Shake>Daniel, Verónica, Carleen.</anim>",
  ui_story_5051_50511602_23_dialog_content = "Esa voz.",
  ui_story_5051_50511602_24_dialog_content = "<anim type=Shake>Y... Caleb.</anim>",
  ui_story_5051_50511602_25_dialog_content = "<color=#FFB400>Josué</color>?!",
  ui_story_5051_50511602_26_dialog_content = "¿Cómo puede ser esto?",
  ui_story_5051_50511602_27_dialog_content = "¿E-Es mi hermana?",
  ui_story_5051_50511602_28_dialog_content = "No, no, no... ¡Imposible, ella no puede estar aquí!",
  ui_story_5051_50511602_29_dialog_content = "¿Podría ser?",
  ui_story_5051_50511602_30_dialog_content = "...",
  ui_story_5051_50511602_31_dialog_content = "¿Por qué se detuvo?",
  ui_story_5051_50511602_32_dialog_content = "<anim type=Shake>¡No!</anim>",
  ui_story_5051_50511602_33_dialog_content = "<anim type=Shake>¡No puedes hacer esto!</anim>",
  ui_story_5051_50511602_34_dialog_content = "<anim type=Shake>¿Por qué no?</anim>",
  ui_story_5051_50511602_35_dialog_content = "<anim type=Shake>Ellos son la fuente de todo tu dolor.</anim>",
  ui_story_5051_50511602_36_dialog_content = "<anim type=Shake>¡El obstáculo para cumplir tus sueños!</anim>",
  ui_story_5051_50511602_37_dialog_content = "<anim type=Shake>¡Son las personas que más me importan!</anim>",
  ui_story_5051_50511602_38_dialog_content = "<anim type=Shake>¡Mátalos y eres libre de irte!</anim>",
  ui_story_5051_50511602_39_dialog_content = "<anim type=Shake>¿Por qué esperar? Están casi al final de la cuerda.</anim>",
  ui_story_5051_50511602_40_dialog_content = "<anim type=Shake>¡Esto es molesto!</anim>",
  ui_story_5051_50511602_41_dialog_content = "<anim type=Shake>¡Salir!</anim>",
  ui_story_5051_50511602_42_dialog_content = "¿Se está hablando a sí mismo?",
  ui_story_5051_50511602_X43_dialog_content = "Esto es demasiado raro... se siente como discutir conmigo mismo.",
  ui_story_5051_50511602_44_dialog_content = "Josué, ¿eres realmente tú?",
  ui_story_5051_50511602_45_dialog_content = "Madre...?",
  ui_story_5051_50511602_46_dialog_content = "¿Cómo te atreves a hacerte pasar por la voz de Joshua?",
  ui_story_5051_50511602_47_dialog_content = "¡No tendré piedad contigo!",
  ui_story_5051_50511602_48_dialog_content = "<anim type=Shake>Schwar...</anim>",
  ui_story_5051_50511602_49_dialog_content = "Sacudiré cada estrella—!!!",
  ui_story_5051_50511602_50_dialog_content = "<anim type=Shake>Puaj...</anim>",
  ui_story_5051_50511602_51_dialog_content = "<anim type=Shake><size=45>Te odio...!</size></anim>",
  ui_story_5051_50511602_52_dialog_content = "¿Qué?",
  ui_story_5051_50511602_53_dialog_content = "¡Su ataque funcionó!",
  ui_story_5051_50511602_54_dialog_content = "Parece estar en agonía, pero no exactamente del tipo físico...",
  ui_story_5051_50511602_55_dialog_content = "No puede ser ella. Imposible. Si es ella...",
  ui_story_5051_50511602_56_dialog_content = "Sácanos de aquí ahora, Jakine. ¡Ahora!",
  ui_story_5051_50511602_57_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_5051_50511602_58_dialog_content = "¿Es ese el sonido de un reloj?",
  ui_story_5051_50511602_59_dialog_content = "Oh, no, no, no... ¡El reloj está dando las doce!",
  ui_story_5051_50511602_60_dialog_content = "¿Vamos a quedar atrapados aquí?",
  ui_story_5051_50511602_61_dialog_content = "Por qué... lo encuentro después de todo esto...",
  ui_story_5051_50511602_62_dialog_content = "A solo otro minuto de distancia...",
  ui_story_5051_50511602_63_dialog_content = "¡¿Por qué?!",
  ui_story_5051_50511602_64_dialog_content = "¿Qué es eso que tienes en la mano, Caleb?",
  ui_story_5051_50511602_65_dialog_content = "¿Es ese el Cristal de la Memoria Eterna para este mundo?",
  ui_story_5051_50511602_66_dialog_content = "¿Un cristal dentro del cristal?",
  ui_story_5051_50511602_67_dialog_content = "¿Así que lo que? Es inútil incluso si lo encontrara.",
  ui_story_5051_50511602_68_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_5051_50511602_69_dialog_content = "¡El reloj está a punto de dar las doce!",
  ui_story_5051_50511602_70_dialog_content = "¿Por qué estabas buscando esto en el Cristal, Caleb?",
  ui_story_5051_50511602_71_dialog_content = "Ya lo dije, es inútil.",
  ui_story_5051_50511602_72_dialog_content = "¡No, podría haber una manera!",
  ui_story_5051_50511602_73_dialog_content = "¡Dame el Cristal, Caleb!",
  ui_story_5051_50511602_74_dialog_content = "Tómalo.",
  ui_story_5051_50511602_75_dialog_content = "Mamá...",
  ui_story_5051_50511602_76_dialog_content = "Usted previó que esto sucediera, ¿no es así?",
  ui_story_5051_50511602_77_dialog_content = "A la gente le gusta predecir el futuro a través de la adivinación.",
  ui_story_5051_50511602_78_dialog_content = "Pero luego me di cuenta de que siempre subestimamos lo rápido que olvidamos las cosas.",
  ui_story_5051_50511602_79_dialog_content = "Entonces, en ciertos aspectos, lo que es más impredecible es el <color=#FFB400>pasado</color>.",
  ui_story_5051_50511602_80_dialog_content = "Por eso creé el Cristal de la Memoria Eterna en primer lugar.",
  ui_story_5051_50511602_81_dialog_content = "Originalmente pensé que sería el método más seguro para revisar la historia.",
  ui_story_5051_50511602_82_dialog_content = "Pero tu apariencia me avisó de escenarios imprevistos con el Cristal.",
  ui_story_5051_50511602_83_dialog_content = "Afortunadamente, hay un mecanismo de seguridad en el mundo interior.",
  ui_story_5051_50511602_84_dialog_content = "... Un Cristal dentro del Cristal.",
  ui_story_5051_50511602_85_dialog_content = "Eso es lo único que falta en el libro.",
  ui_story_5051_50511602_86_dialog_content = "Espero que nunca tengas que acceder a esa información.",
  ui_story_5051_50511602_87_dialog_content = "¡No te decepcionaré!",
  ui_story_5051_50511602_88_dialog_content = "¡Reditus, reditus, reditus!",
  ui_story_5051_50511602_89_dialog_content = "Anuncio praessence!",
  ui_story_5051_50511602_90_dialog_content = "¡Rebobinar al principio, volvamos a la realidad!",
  ui_story_5051_50511602_91_dialog_content = "<size=45>¡Abracadabra!</size>",
  ui_story_5051_50511602_92_dialog_content = "¡Uh!",
  ui_story_5051_50511602_93_dialog_content = "De nuevo... El mundo da vueltas a mi alrededor...",
  ui_story_5051_50511602_94_dialog_content = "¡Agárrense unos a otros y no se suelten!",
  ui_story_5051_50511602_95_dialog_content = "Ven a mí, Mia y PlayerName!",
  ui_story_5051_50511602_96_dialog_content = "¡Oh, no, no puedo atraer a Caleb!",
  ui_story_5051_50511602_97_dialog_content = "Lo siento, mi hermana... Ya no estaré cerca de ti...",
  ui_story_5051_50511602_98_dialog_content = "¡No podemos... dejar a nadie atrás!",
  ui_story_5051_50511602_99_dialog_content = "¡¿PlayerName?!",
  ui_story_5051_50511602_100_dialog_content = "¡Caleb!",
  ui_story_5051_50511602_101_dialog_content = "¡Toma mi mano!",
  ui_story_5051_50511602_102_dialog_content = "¡Agh!",
  ui_story_5051_50511602_103_dialog_content = "Deja de estirarte, PlayerName. ¡Mi padre está perdiendo el control sobre ti!",
  ui_story_5051_50511602_104_dialog_content = "¡No puedo rendirme!",
  ui_story_5051_50511602_105_dialog_content = "¡¡¡PlayerName!!!",
  ui_story_5051_50511602_106_dialog_content = "¡Entendido! ¡Tengo a Caleb!",
  ui_story_5051_50511602_107_dialog_content = "PlayerName...?",
  ui_story_5051_50511602_108_dialog_content = "<color=#e8d9bb>¡Choque!</color>",
  ui_story_5051_50511602_109_dialog_content = "(¿Eso es una copa rompiéndose?)",
  ui_story_5051_50511602_110_dialog_content = "(Pero solo hay una taza en la habitación...)",
  ui_story_5051_50511602_111_dialog_content = "(Así que ese buen vino todavía no pudo calmar al Sr. Caleb, ya veo...)",
  ui_story_5051_50511602_112_dialog_content = "Eso fue toda una conmoción, Sra. Rot.",
  ui_story_5051_50511602_113_dialog_content = "¿Qué invitado de honor fue tan descuidado como para romper objetos en la habitación del Señor de la Ciudad?",
  ui_story_5051_50511602_114_dialog_content = "¿O debería decir qué invitado enfureció tanto al señor que debe recurrir a arrojar objetos?",
  ui_story_5051_50511602_115_dialog_content = "Admiro tu imaginación, Duke.",
  ui_story_5051_50511602_116_dialog_content = "Sin embargo, no es asunto nuestro discutir o especular sobre el contenido de la conversación del Señor de la Ciudad y su invitado.",
  ui_story_5051_50511602_117_dialog_content = "Humph. Ya no eres el capitán de Nightwatch, ¿verdad?",
  ui_story_5051_50511602_118_dialog_content = "Pero no seré negligente en el desempeño de mis deberes para el Señor de la Ciudad.",
  ui_story_5051_50511602_119_dialog_content = "¿Deberes? Eres solo un anfitrión interino de la fiesta.",
  ui_story_5051_50511602_120_dialog_content = "Si le gusta hacer esto, ¿puedo invitarla a ayudar con el cumpleaños de mi hijo, Sra. Rot?",
  ui_story_5051_50511602_121_dialog_content = "Creo que no me aclaré, Duke.",
  ui_story_5051_50511602_122_dialog_content = "Todavía estoy trabajando para el Señor de la Ciudad.",
  ui_story_5051_50511602_123_dialog_content = "Digas lo que digas, no podrá conceder una audiencia a tu hijo esta noche.",
  ui_story_5051_50511602_124_dialog_content = "Bueno, nunca hice tal demanda, Sra. Rot.",
  ui_story_5051_50511602_125_dialog_content = "Solo quería despedirme de él ya que se estaba haciendo tarde.",
  ui_story_5051_50511602_126_dialog_content = "Pero la forma en que elegiste tomar el camino bajo...",
  ui_story_5051_50511602_127_dialog_content = "Eso es impropio para alguien que trabaja para el Señor de la Ciudad.",
  ui_story_5051_50511602_128_dialog_content = "Bueno, nunca se puede ser demasiado cuidadoso.",
  ui_story_5051_50511602_129_dialog_content = "<color=#e8d9bb>Whoosh.</color>",
  ui_story_5051_50511602_130_dialog_content = "¿Qué?",
  ui_story_5051_50511602_131_dialog_content = "Fuera...",
  ui_story_5051_50511602_132_dialog_content = "El viento está aumentando.",
  ui_story_5051_50511602_133_dialog_content = "<color=#e8d9bb>Mientras tanto en la residencia de Caleb</color>",
  ui_story_5051_50511602_134_dialog_content = "<color=#e8d9bb>Whoosh.</color>",
  ui_story_5051_50511602_135_dialog_content = "<color=#e8d9bb>¡Retumbar!</color>",
  ui_story_5051_50511602_136_dialog_content = "<color=#e8d9bb>Retumbar-!</color>",
  ui_story_5051_50511602_137_dialog_content = "...",
  ui_story_5051_50511602_138_dialog_content = "...",
  ui_story_5051_50511602_139_dialog_content = "...",
  ui_story_5051_50511602_140_dialog_content = "<color=#e8d9bb>¡Retumbar!</color>",
  ui_story_5051_50511602_141_dialog_content = "<color=#e8d9bb>Retumbar-!</color>",
  ui_story_5051_50511602_142_dialog_content = "<color=#e8d9bb>¡¡¡Retumbar!!!</color>",
  ui_story_5051_50511602_143_dialog_content = "Continuará..."
}
return config
